window.__D("text/igrot-rebbe/c057",{"p":[[1200950089,"ז'תתמד\n\n<p>ב\"ה, ו' אלול, תש\"ט</p><p>הרה\"ח וו\"ח אי\"א נו\"מ וכו' מהור\"מ שי'<br>\nהעכט</p>\n<p>שלום וברכה!</p>\n<p>מוסג\"פ החוברת של הרופא גרוצענדלער שהלוה לי, ות\"ח.</p>\n<p>כתבתי להנ\"ל מכתב ומוסג\"פ העתקה, ומטובו להאחר שיקראנה להחזירה לי.</p>\n<p>בהמשך למה שדברנו עוד קודם נסיעתו נתברר שמפני שלוה על אחריותו הפרטית עוד בהיותו בוואוסטער נ\"ח עדיין שלש מאות וארבעים שקל, ובודאי כהבטחתו ובהתחשב עם המצב של המל\"ח ישתדל שיסולק חוב זה בהקדם היותר אפשרי, ות\"ח בשם המל\"ח מראש.</p>\n<p>המחכה לבשו\"ט וחותם בברכת כוח\"ט לו ולכב\"ב ורחל שיחיו.</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><h4><i><b>ז'תתמד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 79.</p>\n<p><b>הרה\"ח... העכט:</b> אגרות נוספות אליו - לעיל חי\"ח ו'תשלח, ובהנסמן בהערות שם.</p>\n<p>לקמן ז'תתסב. ז'תתקמט.</p>\n<p><b>כתבתי להנ,ל:</b> לעיל ח\"ג אגרת ז'תתמג.</p>\n<p><b>בהיותו בוואוסטער:</b> ראה תולדות חב\"ד בארה\"ב ע' רמד.</p>\n<p><b>נ\"ח:</b> נשאר חייב.</p>\n<p><b>ולרחל:</b> בתו שנקראה ע\"ש אם אם כ\"ק אדמו\"ר שליט\"א. ראה לעילח\"ב אגרת שמה.</p>"],[1200950090,"ז'תתמה\n\n<p>ב\"ה, כ\"ו אלול, תש\"ט</p><p>הרה\"ג וו\"ח אי\"א וכו' מהורמ\"ב שי'<br>\nמארגענשטערן</p>\n<p>שלום וברכה!</p>\n<p>שמחתי לשמוע כי יצא לאור ספר גליוני הש\"ס על סדרי נשים ונזיקין, ומודים אנו לכת\"ר ששלח לנו הספר שמצא מקום חשוב בספרי' שלנו.</p>\n<p>בחילוף בעד הספר הנ\"ל שולחים אנו לכת\"ר בחבילה מיוחדת <b>ספר המאמרים</b> לכ\"ק מו\"ח אדמו\"ר שליט\"א.</p>\n<p>ולקראת השנה החדשה הבע\"ל אשלח לו ברכתי לשנה טובה ומתוקה בכל מילי דמיטב.</p>\n<p><b>בשם הרב מנחם</b></p>\n<p><b>שניאורסאהן</b></p>\n<p>יושב ראש ועד הפועל</p>\n<p>מזכיר</p>\n<h4><i><b>ז'תתמה</b></i></h4>\n<p>מהעתק המזכירות.</p>"],[1200950091,"ז'תתמו\n\n<p><i>[כ\"ח אלול תש\"ט]</i></p>\n<p>ספטמבר 22 1949</p>\n<p>בבקשה לפרסם [לאנ\"ש] בכל הקיבוצים השמטה שבלקוטי מנהגים וצריך להיות אכילת התפוח בתחלת הסעודה.</p>\n<p>שנה טובה</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתמו</b></i></h4>\n<p>מהעתק המזכירות של המברק שנשלח לרח\"ה הבלין עבור אנ\"ש בארה\"ק ולמוהר\"נ נהמנוב עבור אנ\"ש בכל הקיבוצים (מחנות פליטים).</p>\n<p><b>בתחלת הסעודה:</b> ולא כהמנהג שהיה עד אז, לאכלו קודם נט\"י. ראה מ\"ש בזה בקובץ הערות וביאורים (אהלי תורה גליון תרמ ע' 16).</p>"],[1200950092,"ז'תתמז\n\n<p><i>[ב' ניסן תש\"י]</i></p>\n<p>... המכתב משני באדר קבלתי. ובטח מסר הרר\"י שי' דובאוו מה שאמרתי לו בזה בהיותו פה. והזכרתי את החתומים שם בהיותי על הציון ביום שנבה\"ע, הוא כ\"ה אדר.</p>\n<h4><i><b>ז'תתמז</b></i></h4>\n<p>מצילום כתי\"ק שבס' ימי בראשית ע' 104, והיא הוספה לארת תקעד דלעיל ח\"ג, בטופס הנשלח למו,ה אברהם סענדר נמצוב.</p>\n<p>אגרות נוספות אליו - לעיל חי\"ז ו'תנו, ובהנסמן בהערות שם.</p>\n<p><b>מסר... דובאוו:</b> ראה גם לעיל ח\"ג בשולי אגרת תקעה, שהיא הוספה בטופס הנשלח למוהר,י דובאוו.</p>\n<p><b>מה שאמרתי לו:</b> ראה \"ימי בראשית\" ע' 84.</p>"],[1200950093,"ז'תתמח\n\n<p>ב\"ה, יו\"ד ניסן, תש\"י</p><p>... קבלתי מכתבו מועש\"ק. ודבריו מבהילים. וכבר עניתי לא' שזהו ענין ד\"נ, וידוע כמה חקו\"ד צריך בד\"נ. וכולי האי ואולי כו'. והם כותבים ושונים כו'. ובל\"ס כוונתם רצוי', אבל כו'.</p>\n<p>ומה שהזכרתי את כולם בהיותי על הציון, ובל\"נ, אעשה כן גם מחר - הוא אלס גוטע פריינד, ונהגתי כן זה כמה שנים בהכנסי להיכל כ\"ק מו\"ח אדמו\"ר הכ\"מ. וראה ס\"ח סי' תתשכט: ופוטר את הרבים בקידוש בבגדים חמודות שהי' לובש.</p>\n<h4><i><b>ז'תתמח</b></i></h4>\n<p>מצילום כתי\"ק שב\"ימי מלך\" ח\"ג ע' 1152, והיא הוספה לאגרת תקפה דליעל ח\"ג.</p>\n<p><b>ודבריו מבהילים:</b> כתב התקשרות לכ\"ק אדמו\"ר שליט\"א.</p>\n<p><b>וכבר עניתי לא':</b> לעיל ח\"ג אגרת תקעו.</p>\n<p><b>ד\"נ:</b> דיני נפשות.</p>\n<p><b>ופוטר את הרבים:</b> ראה גם לקו\"ש ח\"ב ע' 511.</p>"],[1200950094,"ז'תתמט\n\n<p>ב\"ה, י\"ג ניסן, ה'תש\"י</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו:</p>\n<p>נהניתי מה ששומר מה שהורהו כ\"ק מו\"ח אדמו\"ר הכ\"מ בחזרת מאמרים. ומה טוב לספר לפני השומעים לאחר החזרה או לפני', לפי תנאי המקום, קטע משיחת כ\"ק מו\"ח אדמו\"ר הכ\"מ, המתאים לפי הזמן, פרשת השבוע, וכיו\"ב.</p>\n<p>בטח כשאין מתפללים בצבור - שומעים עכ\"פ קדיש ברכו וקדושה.</p>\n<p>מה שכותב אשר בעש\"ק אין לומדים כלל, - איני מבין כלל. ואולי כוונתו שאין לומדים בכתה.</p>\n<p>ומה ששואל בענין תקון - הנה, לפענ\"ד, יוסיף אומץ בעסק חנוך הנוער, ויסיח דעתו, לע\"ע, מכל הענין רוצה לתקנו, שישתדל שלא לחשוב עד\"ז כלל.</p>\n<p>מוסג\"פ הקונטרס לחה\"פ והעתקת מכתב שכתבתי לאחד.</p>\n<p>באיחול חה\"פ כשר והצלחה שיהי' יר\"ש חסיד ולמדן,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתמט</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950095,"ז'תתנ\n\n<p>ב\"ה, כ\"ז ניסן, ה'תש\"י</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ וכו' מוהר\"ש שי'</p>\n<p>שלום וברכה!</p>\n<p>מכתבו מי\"ג ניסן קבלתי, ולמרות האי-נימות שבדבר דברתי עם...שי', אמר לי שקבל מכ' ממרת... ג\"כ בענין זה.</p>\n<p>והנה שישלח הסכום המוזכר במכתבו אלי, כנראה שאינו בגדר האפשרי כלל וכלל, אבל ישתדל לשלוח איזה סכום וימסור לרשותם ג\"כ פדיון הסחורה שלו הנמצאת בפיטסבורג.</p>\n<p>ובודאי כת\"ר מצדו יראה גם כן לשכך הענין עד כמה שאפשר.</p>\n<p>מכתבי עם הקונטרס בטח הגיעו במועדם.</p>\n<p>באיחול כט\"ס,</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><p>בטח משתמש בנו מהר\"ל שי' בהזדמנות שהוא בפיטסבורג לפעול שם בענין תומ\"צ ודא\"ח. ויודיע בשו\"ט בזה.</p>\n<h4><i><b>ז'תתנ</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 88, מהעתק המזכירות.</p>\n<p>לתוכן האגרת ראה גם לקמן אגרת ז'תתנג.</p>\n<p><b>מהור\"ש שי':</b> פויזנר. אגרות נוספות אליו - לעיל ז'תשסז, ובהנסמן בהערות שם.</p>"],[1200950096,"ז'תתנא\n\n<p>ב\"ה, ב' אייר, ה'תש\"י</p><p>אל בני ובנות ישראל אשר בעיר ניו-יארק<br>\nרבתי וסביבותי',<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>זוהי השנה התשיעית מאז נוסדו מוסדות החינוך לנערות \"בית רבקה\" על ידי המרכז לעניני חנוך, על פי הוראת כ\"ק מו\"ח אדמו\"ר, זצוקללה\"ה נבג\"מ זי\"ע הכ\"מ.</p>\n<p>ותהלה לא-ל, גדלו המוסדות האלה בכמות ובאיכות, והתלמידות הלומדות שם מתחנכות בחנוך כשר על יסודות התורה ויראת שמים.</p>\n<p>מאד מאד החשיב כ\"ק מו\"ח אדמו\"ר הכ\"מ את המוסדות האלה, בתור הכרחיות לקיום בית ישראל, ומדי פעם בפעם ובפרט לרגלי החגיגות השנתיות, יצא בקריאה של חיבה בקשה ודרישה להעיר תשומת לב הציבור הרחב על גודל החובה והזכות של כל איש ואשה בישראל להחזיק את המוסדות \"בית רבקה\" אשר קיימות מכבר ולאפשר התפתחותם והרחבתם ויסוד סניפים חדשים.</p>\n<p>דברי צדיקים ומנהיגי ישראל קיימים לעד. וגם אחרי הסתלקות כ\"ק מו\"ח אדמו\"ר הכ\"מ עלינו לזכור תמיד את הוראותיו בכלל ועתה בפרט בענין שהזמן גרמא, להתעורר ולהתאמץ ביתר שאת בהחזקת המוסדות, שכל כך יקרו בעיניו.</p>\n<p>המתעסקים במסדות החנוך \"ארגון בית רבקה\", ובראשם הרה\"ח והרה\"ג עסקן חרוץ בהרבצת תורה וחינוך הכשר וו\"ח אי\"א מוהר\"ר ישראל שיחי' דזשייקאבסאן, מסדרים חגיגה שנתית אשר תתקיים אי\"ה ביום כ' אייר הבע\"ל.</p>\n<p>והנני פונה בקריאת התעוררות לכל איש ואשה בישראל אשר גורל בנות ישראל נוגע ללבם, להשתתף בחגיגה שנתית זו בגופם ובמאודם, להיות עושים ומעשים לטובת המיסדות האלה בכלל ולטובת החגיגה השנתית בפרט.</p>\n<p>ומובטחני אשר ברכות כ\"ק מו\"ח אדמו\"ר הכ\"מ אשר ברך את כל המשתתפים בהחזקת המוסדות \"בית רבקה\" - יקויימו בהם ובבני ביתם יחיו להתברך בכל טוב בגשמיות וברוחניות.</p>\n<p>החותם בכבוד וברכת כל טוב,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתנא</b></i></h4>\n<p>מצילום האגרת שנדפסה ב\"ימי בראשית\" ע' 144.</p>"],[1200950097,"ז'תתנב\n\n<p>ב\"ה ז' אייר, ה'תש\"י</p>\n<p>שלום וברכה!</p>\n<p>נמסר לי מכתבו, כי כתב שמי על המעטפה, אבל בפתחי אותו ראיתיו כתוב לבית חיינו, ואיני יודע כוונתו בכ\"ז, ולכן מסרתי מכתבו לאשת חבר כחבר, היא כבוד חמותי הרבנית תחי'.</p>\n<p>שמו ושמות בניו שיחיו שמזכיר במכתבו נזכרו על ציון כ\"ק מו\"ח אדמו\"ר הכ\"מ. וכן הזכרתים בהיכלו שבו נכנסים ליחידות ולנתינת פדיונות.</p>\n<p>ויהי רצון שיקויימו ברכות כ\"ק מו\"ח אדמו\"ר הכ\"מ, על מילואן בקרוב ממש.</p>\n<p>המאחל כ\"ט,</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><p>מוסג\"פ חוברת שהו\"ל היום, ובטח יזכה בה את הרבים.</p>\n<h4><i><b>ז'תתנב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 89, מהעתק המזכירות.</p>"],[1200950098,"ז'תתנג\n\n<p>ב\"ה, כ' סיון, ה'תש\"י</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ וכו' מהור\"ש שי'</p>\n<p>שלום וברכה!</p>\n<p>מכתבו מיום ה' בשבוע העבר קבלתי, כן מסר לי בנו התמים הרב שי' מה שדבר עמו ביום ועש\"ק העבר.</p>\n<p>ואף שכותב שאיני יכול לשער מה סובלים מהשותף שבמחנו, הנה פשיטא שלא אומר שהעגמ\"נ שלי הוא כמו העגמ\"נ שלו, אבל השערה יש לי במה שעובר עליהם, ובכל זה הנה מה תועלת ישנו במה שיתרגש ויוסיף ויתרגש הוא וזוגתו תי', מה יתוקן ע\"י זה?</p>\n<p>ובשלמא אם הי'... יכול ואינו רוצה, הי' מקום לומר שע\"י התרגשות ואיומים וכיו\"ב יסלק חובו במקצת עכ\"פ, אבל מכיון שהוא אינו יכול, מה בצע בכל הנ\"ל מלבד העגמ\"נ ויסורים. ונוסף על כל זה, הרי... אין לו עתה כל פרנסה אף על הוצאה היום יומית, ומה שיהי' במשך הזמן הנה מי יודע.</p>\n<p>וכדברים האלה צריכים היו להסביר באותיות המתאימות ובשטימונג וזמן המתאים גם להשותף שבמחנו.</p>\n<p>ולכאורה, לע\"ע אין מה לעשות עוד בזה.</p>\n<p>מוסג\"פ קבלה בשביל מר גאלד שי'.</p>\n<p>במקרה שימצא לנכון שמלבד קבלה צ\"ל ג\"כ איזה מכתב מועד המעמד, בטח יודיע.</p>\n<p>בברכה ובתקוה להתבשר ממנו ג\"כ בשו\"ט,</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><h4><i><b>ז'תתנג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 89, מהעתק המזכירות.</p>\n<p>לתוכנה ראה לעיל אגרת ד'תתנ.</p>\n<p><b>מהור\"ש שי':</b> פויזנר. אגרות נוספות אליו - לעיל ז'תשסז, ובהנסמן בהערות שם.</p>"],[1200950099,"ז'תתנד\n\n<p><i>[ג' תמוז]</i></p>\n<p>מכתבו - בלי הוראת זמן כתיבתו - קבלתי, איני יודע אם צדקו טענותיו, אבל מצד קבלת עול טאר מען אויך ניט נארען א אידען, ובפרט א רבים.</p>\n<h4><i><b>ז'תתנד</b></i></h4>\n<p>נדפסה ב\"ימי מלך\" ח\"ב ע' 1153, והיא אל מו\"ה אברהם פריז, במענכ להפצרתו שיאות כ\"ק אדמו\"ר שליט\"א לקבל את הנשיאות; בהמשך לאגרת תרטו דלעיל ח\"ג.</p>\n<p>אגרות נוספות אליו - לעיל חט\"ז ה'תתקלג, ובהנסמן בהערות שם. לקמן ז'תתקיג..</p>\n<p>ז'תתקנא. ח'כב. ח'לו. ח'עט. ח'קס.</p>"],[1200950100,"ז'תתנה\n\n<p>ב\"ה, ד' תמוז, ה'שי\"ת</p><p>הוו\"ח אי\"א נו\"מ מו\"מ באמונה וכו' מהור\"י<br>\nהכהן שי'</p>\n<p>שלום וברכה!</p>\n<p>אייער בריף פון ר\"ח תמוז מיט בייגעלייגטן שעק אויף נאמען פון מרכז לעניני חנוך ערהאלטן. לויט אייער רשות צו טיילן לדעתי, האב איך עס פארטיילט: מעשר אויף מעמד.</p>\n<p>האלב פון די איבערגעבליבענע - אויף <b>אפדרוקן</b> און <b>פאנאנדערשיקן</b> דעם קונטרס פון י\"ב -י\"ג תמוז הבע\"ל, ווען עס וווערט דעם רבי'ן זיבעציק יאר. און אויפגעשריבן אפן קונטרס אז דאס זאל פועלן מחזק זיין די התקשרות פון הרוצה בעילום שמו צום רבי'ן - (דורך דרוקן און פארשפרייטן זיין תורה <b>בכל קצווי תבל</b>).</p>\n<p>איך האב עס ספעציעל געטאן, ווייל <b>איך</b> ווייס ניט וואס עס טוט זיך מיט התקשרות (האט נאר קיין פאראיבל ניט פארן זאגן עס).</p>\n<p>איך זע כמה וכמה מופתים פון רבי'ן איצט, איז אויב איר זאגט, אז בא אייך איז \"ניטא קיין נייעס\" - מוז דאך עפעס זיין א סיבה אין דעם.</p>\n<p>זייער מעגליך, אז דער רבי האלט אז מ'דארף איצט ניט פארקויפן דעם בילדינג דערפאר איז ניטא קיין קונים וכיוצא בזה.</p>\n<p>און אפשר איז דאס מצד דער חלישות, ח\"ו, בהתקשרות. - (איך גלויב אבער אז איר האט אויך געהאט מופתים (מיט'ן שותף וכיוצא בזה) נאר איר באמערקט ניט אלע) - דערפאר האב איך פארנוצט א טייל פון אייערע געלד אף דער הפצה פון רבי'ס תורה - איינע פון די בעסטע עצות אוי[ף] התקשרות לנשיא ישראל בעל התורה.</p>\n<p>די צווייטע העלפט אריינגעטראגן אין דער לשכת חשאים פון וואנעט דער רבי פלעגט העלפן בחשאי צו אנשים נכבדים און וואס עס ווערט געטאן אויך ווייטער.</p>\n<p>דער קונטרס וועט זיין פארטיק אין אייניגע טעג ארום. דער כתר שם טוב בייגעלייגט.</p>\n<p>ביטע מודיע זיין אז איר וועט עס באקומען.</p>\n<p>המברכו בכל טוב ומחכה לבשורות טובות,</p>\n<p><b>הרב מ.ש.</b></p>\n<h4><i><b>ז'תתנה</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>מהור\"י:</b> כץ. אגרות נוספות אליו - לעיל חי\"ח ו'תרסו,ובהנסמן בהערות שם.</p>"],[1200950101,"ז'תתנו\n\n<p>ב\"ה, כ\"א תמוז, ה'שי\"ת</p>\n<p>שלום וברכה!</p>\n<p>היום בוקר נתקבל מכתבו מי\"ז תמוז שמודיע שהיום יסירו המאננדלען אצל בנו שי'.</p>\n<p>וע\"פ בקשתו הזכרתיו בהיכל כ\"ק מו\"ח אדמו\"ר הכ\"מ שבו נכנסים ליחידות ולנתינת פ\"נ, ובטח ישלח השי\"ת את ברכתו שיהי' הכל כשורה ויגדלו עם שאר ילדיו שי' לתורה חומע\"ט און [ווי] חסידים פארשטיין דאס.</p>\n<p>בודאי יודיע מאשר עבר הכל בשלום ובנו שי' שב לאיתנו.</p>\n<p>באיחול כ\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><p>פלא קצת שכותב ע\"ד גשמיות בנו שי' ואינו מזכיר מאומה ע\"ד הרוחניות, לימודו וכו'.</p>\n<h4><i><b>ז'תתנו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 109.</p>"],[1200950102,"ז'תתנז\n\n<p>ב\"ה, כ\"ו תמוז, השי\"ת</p><p>הרה\"ג הוו\"ח אי\"א נו\"מ בעל מדות עוסק<br>\nבצ\"צ וכו' וכו',<br>\nמוהר\"ל שי' רבינוביטש, הרב הראשי<br>\nלמדינות אפריקה<br>\nהדרומית</p>\n<p>שלום וברכה!</p>\n<p>נעם לי ביקורו בהיותו בניו-יארק, ושמחתי בהזדמנות לשוחח אתו. והנני מקוה כי הגיע לביתו לשלום.</p>\n<p>נושא שיחתנו ודאי עדיין בזכרונו. ובטח לא יארך הזמן וכת\"ר יתחיל להוציא לפועל את אשר דברנו - יסוד ישיבה במדינתו בעד אלה אשר אין ביכלתם או ברצונם לגלות למקום תורה, וגם יגש תיכף להתחיל בתעמולה ופעולה נמרצה להחזקת והרחבת חינוך הכשר בכלל במדינתו.</p>\n<p>כל איש ואישה בישראל יש להם חלק באחריות החינוך הכשר, וכת\"ר, בתור הרב הראשי במדינתו, בטח מכיר בגודל האפשריות המוטלת עליו בזה. ולולא אשר אין מזרזין אלא למזורזין הייתי אומר כי למותר לזרז לדכוותי', ברם הזריזות יפה לפעולה כזאת, ובטח יחוס על הזמן שלא ילך לאיבוד ויגש להוציא לפועל תכנית העבודה שדברנו עלי' בהקדם. והנני מאחל לו סייעתא דשמיא בהצלחה מרובה בגשמיות וברוחניות.</p>\n<p>מוסג\"פ קונטרס חדש שיצא לאור במקצוע החסידות - קונטרס י\"ב-י\"ג תמוז השי\"ת, ובטח ימצא בו ענין רב.</p>\n<p>והשי\"ת יהפך יומיא דפורעניתא אלין ליומיא דנחמתא בעגלא דידן, בזכות התורה והמאור שבה.</p>\n<p>באיחול כל טוב,</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><h4><i><b>ז'תתנז</b></i></h4>\n<p>מצילום האגרת שנדפסה ב\"ימי מלך\" ח\"ג ע' 1093.</p>\n<p><b>הרה\"ג... רבינוביטש:</b> אגרות נוספת אליו - לעיל ח\"ה א'רפט. וראה גם שם אגרת א'רחצ.</p>"],[1200950103,"ז'תתנח\n\n<p>ב\"ה, ו' מנ\"א, השי\"ת</p><p>הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"מ מהור\"י שי'<br>\nהלוי</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו משבוע העבר:</p>\n<p>מה שהובא בדא\"ח כמה פעמים הספר עה\"מ או עמה\"מ הכונה לעמק המלך דר' נפתלי הירץ נדפס באמשטרדאם שנת ה'זאת. וראה בלקו\"ת שה\"ש הביאור צאו\"ר שסומכין עליו אשר אף \"בע\"ח לא נזכר מזה כלל\".</p>\n<p>ומה שהעיר מלקו\"ת ס\"פ פנחס ד\"ה קדש ישראל רפ\"ד שכתב שם איזה פעמים קדש האדם, ותמה אצ\"ל ישראל.</p>\n<p>בטח דפוס ישן אצלו, וכבר נתקן בדפוסים שאח\"כ. וכנראה מפני יראת הצענזאר הדפיסו מתחילה האדם.</p>\n<p>וראה אור התורה להצ\"צ שמות ע' פ\"ו ובהערות שם.</p>\n<p>והשי\"ת יהפך ימים אלו לששון ולשמחה ויתגלה לעיני כל בשר אשר קדש ישראל לה' גו' כל אוכליו יאשמו בעגלא דידן.</p>\n<p>באיחולי כ\"ט.</p>\n<p><b>הרב מנחם שניאורסאהן</b></p><h4><i><b>ז'תתנח</b></i></h4>\n<p>מצילום הנדפס ב\"ימי מלך\" ח\"ג ע' 1113.</p>\n<p><b>מהור\"י:</b> הרוביץ. אגרות נוספות אליו - לעיל חי\"ב ד'קמג, ובהנסמן בהערות שם.</p>\n<p><b>ה'זאת:</b>ת\"ח.</p>"],[1200950104,"ז'תתנט\n\n<p>ב\"ה, ד' אלול, השי\"ת</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ וכו' מוהרש\"ז שי'</p>\n<p>שלום וברכה!</p>\n<p>מכתביו מח\"י תמוז ומכ\"א מנ\"א עם המוסג\"ב נתקבלו. וזה מכבר נשלחו לו הנדפסים אשר ביקש, בחבילה בפ\"ע - ובטח יאשר קבלתם - כן נתקבל מכתב כ\"ף דזכרונות שלו מכבר, ובהנ\"ל - מכתב כ\"א כ\"ב. ובטח ימשיך רשימותיו, וכרצון כ\"ק מו\"ח אדמו\"ר הכ\"מ. כן כתבתי לו שיקח להוצאות בית רבקה ויודיע מאיזה קופה לקח ויכניסו תמורתם. ומה שכותב בענין ההעתקה - הנה, לפי דעתי, נכון הדבר שיעתיקו למדינה שיעתיק חתנו וב\"ב שי', ומהוי' מצעדי גבר כוננו.</p>\n<p>בודאי ממשיך גם עתה בלימוד השיעורים ברבים ועריכת ההתועדות. ובפרט בחדש דא'ני ל'דודי ו'דודי ל'י, שצריך להיות א'יש ל'רעהו ו'מתנות ל'אביונים.</p>\n<p>כיון שאינו מזכיר ע\"ד בריאותו - בודאי שלום לו, ובכ\"ז ת\"ח אם יכתוב זה בפירוש.</p>\n<p>בברכת כתיבה וחתימה טובה לו ולכב\"ב ולכל החבורה שיחיו</p>\n<p><b>מ. שניאוסרהן</b></p>\n<h4><i><b>ז'תתנט</b></i></h4>\n<p>מצילום האגרת שב\"לשמע אוזן\" (הוצ' תש\"נ) ע' שכא. חלק נדפס לעיל ח\"ג אגרת תשד.</p>\n<p><b>מהורש\"ז:</b> דוכמן. אגרות נוספות אליו - לעיל חי\"ח ו'תקל, ובהנסמןב הערותש ם. לקמן ז'תתסו. ז'תתפג.</p>\n<p><b>חתנו:</b> מו\"ה אלי' עקיבא ליפסקר.</p>"],[1200950105,"ז'תתס\n\n<p><i>[ה' אלול תש\"י]</i></p>\n<p>מזל טוב להולדת בנם הצעתו לקראו בשם נשיאנו נכונה ויגדלוהו לתורה חופה ומעשים טובים,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתס</b></i></h4>\n<p>מצילום כתי\"ק ב\"ימי מלך\" ח\"ג 1094. והיא אל מו\"ה ברוך פריז. אגרות נוספות אליו - ללעיל חי\"ט ז'נא, ובהנסמן בהערות שם.</p>"],[1200950106,"ז'תתסא\n\n<p>ב\"ה, י\"ב אלול, השי\"ת</p><p>הרה\"ח הוו\"ח אי\"א וכו' מוה\"ר יונה שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו המודיע כי מתכוננים הם לעלות לארצה\"ק ת\"ו ומבקש ברכה,</p>\n<p>הנני לשלוח בזה ברכותי שתהי' הנסיעה בזמנה כשורה ובנקל, ויסתדר שם באופן המתאים בגשמיות וברוחניות.</p>\n<p>בטח ידוע לו פתגם כ\"ק מו\"ח אדמו\"ר הכ\"מ, אז מ'דארף מאכן פון ארץ ישראל ארץ הקדושה, ובאשר כלל הוא בקדושה שלפום גמלא שיחנא, בודאי גם הוא יתבונן בזה וישתדל למלא אחרי דברי הרב הוא נשיאנו כ\"ק מו\"ח אדמו\"ר הכ\"מ.</p>\n<p>בטח יש לו קביעת עתים בתורה בכלל, ובלימוד תורת כ\"ק מו\"ח אדמו\"ר הכ\"מ בפרט, נוסף על השיעורים השוים לכל נפש, כמבואר במורה שיעור.</p>\n<p>בברכת כתיבה וחתימה טובה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתסא</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>מוה\"ר יונה:</b> איידלקופ. אגרות נוספות אליו - לעיל חי\"ז ו'רסט, ובהנסמן בהערות שם.</p>\n<p><b>פתגם:</b> ראה גם לעילח\"ג אגורת תשיא. תשלו.</p>\n<p><b>השיעורים:</b> תח\"ת.</p>"],[1200950107,"ז'תתסב\n\n<p><i>[השלמה לאגרת י\"ד אלול דלעיל ח\"ג תשל]</i></p>\n<p>חתיכת מטפחת כ\"ק מו\"ח אדמו\"ר הכ\"מ בטח שמורה אצלו ויחזירנה לי, כמדובר.</p>\n<p>ות\"ח.</p>\n<p>מהנכון אשר יקבל את ילידו של מו\"ה כו'... להגן ילדים, כי בטח אין סיבות מנגדות לזה.</p>\n<h4><i><b>ז'תתסב</b></i></h4>\n<p>צילום כתי\"ק בס' זכרון תפארת משה יצחק 0אחרי ע' 124).</p>\n<p>האגרת היא למוהרמ\"י העכט. אגרות נוספות אליו - לעיל ז'תתמד. ובהנסמן בהערות שם.</p>"],[1200950108,"ז'תתסג\n\n<p>ב\"ה, כ\"ד אלול, השי\"ת</p><p>הרה\"ג והרה\"ח וו\"ח אי\"א נו\"מ וכו' מוהר\"ר<br>\nאפרים<br>\nאליעזר שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>בעונג קראתי מכתבו מח\"י אלול השי\"ת הכולל בתוכו זכרונות מחיי צדיקים קדושים וטהורים, וכידוע במעלת ספר בראשית הקודם לספר שמות וכו' כי הוא מלא סיפורי צדיקים, ועל שמו נקרא ספר הישר (ומדובר בזה בקובץ מכתבים ג' של כ\"ק מו\"ח אדמו\"ר הכ\"מ ע' יו\"ד ואילך).</p>\n<p>כנראה במכתבו כבר נמצא במחנו הט' ולכן הנני שולח מכתב זה ישר לעירו.</p>\n<p>מוסגר פה הקונטרס לראש השנה הבע\"ל עם העתקת מכתבים כלליים השייכים אליו, אשר בידעי יחס כת\"ר תקותי שימצא ענין בהם, והי' זה שכרי.</p>\n<p>החותם בברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות לכת\"ר ולכב\"ב שיחיו ולכל מושפעיו בתומ\"צ ודר\"ח - המברך ומתברך ומצפה לטוב,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתסג</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>מוהר\"ר אפרים אליעזר:</b> יאלעס. אגרות נוספות אליו - לעיל ח\"כ ז'תנה, ובהנסמן בהערות שם. לקמן ח'סב.</p>\n<p><b>בקובס מכתבים:</b> אג\"ק אדמור, מוהריי\"צ נ\"ע ח\"ו אגרת א'תריב (ע' עז).</p>\n<p><b>ודר\"ח:</b> ודרכי חסידות.</p>"],[1200950109,"ז'תתסד\n\n<p><i>[בין כסא לעשור תשי\"א]</i></p>\n<p>... ת\"ח ת\"ח על המאמרים והשיחות ששלח אלי, אשר כמה מהם לא היו אצלי ע\"ע.</p>\n<p>ובטח אם ימצאו עוד ישלחום ג\"כ, ורוב ת\"ח מראש.</p>\n<p>מה שהוקשה לו בשיחת שמח\"ת תרפ\"ו בגזירת הכובעים והרה\"ק \"הגאון החסיד\" (כך נזכר בלקו\"ת שה\"ש יח, ג) מבארדיטשוב, שאין השנים מתאימות - הנה שמעתי מעין זה, אבל על <b>ר\"ה מפאריטש</b> (וכנראה טעה המניח). ואז מובן ג\"כ מש\"כ בהר\"ד שאמר לתלמידיו, כי לא שמענו שהיתה ישיבה אצל הרלי\"צ מבראד'.</p>\n<p>ומש\"כ במכתבו בענין בכורים - יעויין בזה זח\"ג רנג, א ובמק\"מ שם. ד\"ה וביום הבכורים רנ\"ד.</p>\n<p>* * *</p>\n<p>... מבקש שיעוררו רחמים עליו, ובטח יודיע שהכין כלים ט' ורחבים לזה: קב\"ע בתורה, עבודה בעצמו ועם הזולת וכו'.</p>\n<p>* * *</p>\n<p>בנוגע לבנו ש\"ד שי' ששואל אם יסע לכאן ללמוד בתו\"ת - יעויין קונ' שמע\"צ ע' צדי\"ק דאנ\"ש דלונדון צריכים להמשיך אור ליוב' בלונדון און עס האלט דערביי.</p>\n<p>ומהנכון - שיארגנו קבוצת בחורי חמד ללימוד הדא\"ח, ובנו שי' יהי' ג\"כ מרוח החי' בהם.</p>\n<p>ואזי מאיר עיני כולם הוי'. וכאשר תהי' הקבוצה מבוססה - אז יש לדון בהשאלה אם יסע בנו שי' משם. - ות\"ח על בשו\"ט בזה.</p>\n<h4><i><b>ז'תתסד</b></i></h4>\n<p>שלשת הקטעים דלהלן נכתבו בשולי אגרת תשסה דלעיל ח\"ג, מכתב-כללי-פרטי שנשלח לכו,כ, ונעתקו מצילום האגרת.</p>\n<p>הקטע הראשון הוא למוהרמיא\"ל הכהן. אגרות נוספות אליו - לעיל ח\"כ ז'תעח, ובהנסמןב הערות שם. לקמן ח'יד. הקטע השני הוא למו\"ה אהרן יוסף שי' בליניצקי.</p>\n<p>הקטע השלישי הוא למו,ה יעקב יוסף שי' גוראקוו. אגרות נוספות אליו - לעיל חי\"ז ו'קעב, ובהנסמן בהערות שם.</p>\n<p><b>בשיחת שמח\"ת תרפ\"ו:</b> סה\"ש תר\"פ-תרפ\"ז ע' 96.</p>\n<p><b>לבנו ש\"ד שי':</b> ה\"ר שמועל דוד גורקאוו.</p>\n<p><b>קונ' שמע\"צ:</b> סה\"מ תשי\"א ע' 90.</p>\n<p><b>היום יום בשורה:</b> כן כינוהו <b>מן השמים</b> ליום ג' י\"ט כסלו - במענה להר,י מקורביל (מבעלי התוספות). ראה שו\"ת מן השמים ס\"ה. עיי\"ש.</p>\n<p><b>במכתבו מיו\"ד, כסלו:</b> נדפסה בקונטרס יט כסלו. [סה\"מ השי\"ת ע' 94].</p>\n<p><b>כמו במסחר:</b> לשון כ\"ק מו\"ח אדמו\"ר הכ\"מ סד\"ה אריב\"ל כו' כל העוסק בתורה תרפ\"ח.</p>\n<p>[סה\"מ תרפ\"ח ע' קיב].</p>"],[1200950110,"ז'תתסה\n\n<p>ב\"ה, יו\"ד כסלו, ה'תשי\"א</p><p>ברוקלין, נ.י.</p><p>אל אנ\"ש, ואל כל חובבי תורה<br>\nאשר בכל אתר ואתר<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>הולך וקרב היום יום בשורה, יום ג' תשעה עשר בכסלו, הוא היום אשר בו יצאה לאור צדקת כ\"ק אדמו\"ר הזקן - (בעל התניא והשו\"ע) - ואתו עמו צדקת תורת החסידות - תורת חסידות חב\"ד ותורת החסידות הכללית.</p>\n<p>כ\"ק מו\"ח אדמו\"ר הכ\"מ כותב - במכתבו מיו\"ד כסלו ה'תש\"י, שני חדשים לפני יום ההסתלקות - אשר \"לימוד תורת החסידות אינו ענין השייך רק לאיזה מפלגה שהיא, אלא חובת לימודה מוטלת על כללות בני ישראל יחיו בכלל, ועל בני תורה בפרט\".</p>\n<p>וחובה על אנ\"ש <b>ההתעסקות</b> בהפצת לימוד דא\"ח. והתעסקות - פירושה השתדלות שאינה פוסקת ובאופן שבכל עניניו - גם הצדדיים - מתכוון להשגת מטרה זו \"כמו במסחר ה\"ה עסוק כל היום בזה לאו דוקא בעת שהוא עסוק בגוף ועצם העסק, לפי שהענין נוגע לו ביותר. אז ער איז אנגעטאן אין דעם בכל שעה ובכל זמן,.</p>\n<p>ובמק\"א יבאר בארוכה, איך כי התנאי, אשר <b>יפוצו מעינותיך -</b> של כ\"ק הבעש\"ט <b>- חוצה</b> הוא הקדמה הכנה וכלי לביאת המשיח.</p>\n<p>תנאי זה, אשר על כל אחד מאתנו כולנו להשתדל בכל תוקף למלאותו, שלשה פרטים בו:</p>\n<p>(א) <b>יפוצו.</b> ללמד תורת הדא\"ח באופן של <b>הפצה -</b> פיזור במרחב רב, שיגיע הלימוד לכל חלקי המקום שבו מלמד תורה זו.</p>\n<p>(ב) <b>מעינותיך.</b> תורת הדא\"ח שמפיץ, צריך שיהיו נשמרים בה תכונות של מעין.</p>\n<p>ושתי תכונות עקריות במעין: א) מימיו חיים ונובעים הם בלי הפסק מן מקור המעין. ב) אין משגיחין כ\"כ על הכמות, כי המעין ממקורו נובע טפין טפין. וכן הוא גם התנאי בהפצת תורה זו. אין הכמות עיקר, ובלבד שיהי' לימוד חי בחיות נפשי והתלהבות פנימית, ונובע ממקורו - מפנימיות נפש מפיץ התורה, הקשור בפנימיות לבבו בנשיאי תורת הדא\"ח.</p>\n<p>(ג) <b>חוצה.</b> אל לנו להסתפק בלימוד בביהמ\"ד ובביהכ\"נ בלבד כי אם גם בלכתו בדרך בשבתו בחנות וכיו\"ב. וכן בנוגע למהות הלומדים אין להתצמצם במפלגות אחדות או בסוגי אנשים מיוחדים, כי גם על הפשוט שבפשוטים מוטלת חובת לימוד תורת הדא\"ח, כמו שאפילו הגדול שבגדולים אינו יכול להגיע עד תכליתה.</p>\n<p>וגם לאלו הנמצאים מחוץ לכל המחנות, גם במקום שהכתוב מעיד עליו שהוא <b>חוצה -</b> גם שם צריך להפיץ המעינות.</p>\n<p>וזכות ההשתדלות בהפצת המעינות חוצה תמשיך ותהי' כלי לקבל ברכות כ\"ק מו\"ח אדמו\"ר הכ\"מ אשר ברך את כל אחד מאתנו - לי\"ט כסלו אשר קודם ההסתלקות, ובטח מברך גם עתה לי\"ט כסלו דשנה זו, ובאמירה לנוכח: \"תתברכו מהשי\"ת בשנה טובה בלימוד והפצת החסידות, אתם ביתכם בניכם ובנותיכם יחיו בדרכי החסידות, ואתם וב\"ב וכל הנלוים אליכם תתברכו כולכם בכל הדרוש לכם בגשם וברוח\".</p>\n<p>בברכת הצלחה בעבודה וכל טוב,</p>\n<p><b>מ. שניאורסאהן</b></p><p>* * *</p>\n<p>זה עתה נתקבל מכ' מעש\"ק ויצא. וכבקשתו נשלחים הקונ' על כתובתו החדשה.</p>\n<p>צע\"ק מה, שלע\"ע, לא ענו על מש\"כ בסעיף כא-כב של הר\"ד דש\"פ בראשית.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתסה</b></i></h4>\n<p>נדפסה בשעתה במימיוגרף, ובראשה \"בבקשה לפרסם תוכןמכתב זה, ות\"ח מראש, מחנה ישראל\".</p>\n<p>טופס כזה נשלח לכו\"כ, ובאחד הטפסיםנוסף בשוה\"ג בכתי\"קג - כמועתק לקמן. צילומו ב,ימי בראשית\" ע' 306.</p>\n<p>נוסח דומה נשלח בשנת תשי,ב, ונדפס לעיל ח\"ה א'רסב.</p>\n<p><b>במכתבו:</b> אג\"ק שלו ח\"י אגרת ב'תרלו.</p>\n<p><b>ובמק\"א יבאר בארוכה:</b> בשיחת שמח\"ת תר\"ץ. [לקו\"ד כרך ב' רפו, ב ואילך].</p>\n<p><b>פיזור במרחב רב:</b> ראה רש\"י (משלי ה, טז) עה\"פ יפוצו \"הוראות <b>ברבים</b>\".</p>\n<p><b>תכונות עקריות:</b> להעיר מדין מעין שמטהר בזוחלין ובכל שהוא.</p>\n<p><b>חוצה:</b> ראה זח\"א קמא, ב. תו\"ח בתחילתו עה\"פ חכמותב חוץ. ועוד.</p>\n<p><b>תכונות של מעין:</b> ראה לעיל ח\"ד אגרות תתטו. תתיח.</p>\n<p><b>תתברכו.. וברוח:</b> במכ' דיו\"ד כסלו הנ\"ל.</p>\n<p><b>זה עתה:</b> קטע זה לא' מאנ\"ש השו\"ב ששהה אז באירלנד.</p>\n<p><b>על מש\"כ בסעיף כא-כב:</b> ע\"ד קירוב \"מנין\" אנשים.</p>"],[1200950111,"ז'תתסו\n\n<p>ב\"ה, מוצש\"ק טו\"ב כסלו, התשי\"א</p><p>הרה\"ח הוו\"ח אי\"א וכו' מו\"ה ש\"ז שי'</p>\n<p>... א בקשה פון א חסיד: שלא יתחלל, ח\"ו, ש\"ש על ידו! - דערמיט וועט מען אראפבריינגען משיח'ן?. ישתדל בהפצת מעינות דא\"ח חוצה, ובמילא הכל בכלל זה.</p>\n<h4><i><b>ז'תתסו</b></i></h4>\n<p>מצילום האגרת ב\"לשמע אוזן\" (הוצ' תש\"ג) ע' שכב. ונכתבה בשולי אגרת תתל, דלעיל ח\"ד.</p>\n<p>הטופס שלפנינו נכתב למוהרש,ז דוכמן. אגרות נוספות אליו - לעיל ז'תתנט, ובהנסמן בהערות שם.</p>"],[1200950112,"ז'תתסז\n\n<p>י\"ט כסלו, תשי\"א</p>\n<p>בקשתי מאנ\"ש להתועד ביט\"כ ובנר החמשי הבע\"ל בהשתדלות לצרף גם שלא מאנ\"ש ולסדר הפצת מעינות דא\"ח חוצה.</p>\n<p>בברכת הצלחה</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתסז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 68.</p>"],[1200950113,"ז'תתסח\n\n<p>ב\"ה, ט' טבת, תשי\"א</p><p>.. ומש\"כ אשר י\"א שאין נוגע כ\"כ למצוא מקור או מקום מחז\"ל או דין שהובא בדא\"ח כי זהו בעצמו המקור - אני לא כן הוא עמדי. ולא עוד, אלא כשרואים במקור הרי כמה וכמה פעמים נתוסף הבנה גם בהענין בדא\"ח. - ולכאורה הוא גם חסידישער, לומר אשר ישנו מקור ואני לא מצאתיו מלומר שאני יודע ברור שאין מקור והרבי חידש זה ע\"פ הוראה וכו' -. ובמוחש נראה בהגהות הצ\"צ בדא\"ח עד כמה נתיגע בזה.</p>\n<p>ואכ\"מ.</p>\n<h4><i><b>ז'תתסח</b></i></h4>\n<p>נדפסה בקובץ יגדיל תורה ירושלים גליום כ ע' 9.</p>\n<p><b>למצוא מקור:</b> נכתב בהמשך לאגרת דלעיל ח\"ג תקנו, עיי\"ש.</p>"],[1200950114,"ז'תתסט\n\n<p>ב\"ה, ג' שבט, ה'תשי\"א</p><p>הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"מ וכו' מו\"ה<br>\nמאיר שי'</p>\n<p>שלום וברכה!</p>\n<p>נצטערתי לשמוע אשר נפל רוחו עליו, וכן אצל ב\"ב שיחיו.</p>\n<p>ונכון יהי' לבו בטוח בהשי\"ת, הרופא כל בשר ומפליא לעשות, אשר יהי' הכל כשורה, וישלח לכת\"ר רפואה בקרוב.</p>\n<p>ונשיאנו כ\"ק מו\"ח אדמו\"ר הכ\"מ ימשיך עליו, ועל כל ב\"ב שיחיו, ברכה והצלחה, וכת\"ר, ביחד עם זוג' הרבנית תי', יראו רוב נחת בכל ילידיהם שיחיו שנים רבות טובות ונעימות.</p>\n<p>בברכה ופ\"ש ב\"ב שיחיו,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתסט</b></i></h4>\n<p>מצילום כתי\"ק ב\"ימי בראשית\" ע' 251.</p>\n<p><b>מו\"ה מאיר:</b> אשכנזי. אגרות נוספות אליו - לעיל ח\"ב רלט,ובהנסמןב הערות שם.</p>"],[1200950115,"ז'תתע\n\n<p><i>[תחלת שבט תשי\"א]</i></p>\n<p>... ת\"ח ת\"ח, מקול\"ע, על שהזכירני על הציונים באה\"ק ת\"ו.</p>\n<p>ואחתום בתודה על זה ובברכת בריאות הנכונה, ושיבשר בשו\"ט מכל ב\"ב שי' וגם הוא בכלל, כמובן.</p>\n<p><b>מ. שניאורסאהן</b></p><p>קראתי הפ\"נ על הציון בער\"ח שבט העבר.</p>\n<h4><i><b>ז'תתע</b></i></h4>\n<p>מצילום כתי\"ק ב\"זככרון שמואל\" ע' 77, בשולי אגרת תתל דלעיל ח\"ד, בטופס הנשלח אל מו\"ה שמואל זלמנוב. אגרות נוספות אליו - לקמן ז'תתקח. ח'נט.</p>"],[1200950116,"ז'תתעא\n\n<p>יו\"ד שבט תשי\"א</p>\n<p>ביום ההילולא אזלינן מיני' עשירי בשבט גדול ביותר זכות בעל ההילולא צדיק עליון להמשיך ישועות ברכות והצלחות לכל המתעסק[ים] במוסדותיו. בטח יתועדו לעורר רבים לתומ\"צ לחזק מוסדותיו ותקנותיו להתקשר באילנא דחיי ולהתברך בכל המצטרך בגשם וברוח.</p>\n<h4><i><b>ז'תתעא</b></i></h4>\n<p>נדפסה בסה\"מ באתי לגני ח\"א ע' שעא, והוא נוסח המברק ששלח כ\"ק אדמור, שליט\"א לכללות אנ\"ש במרחבי תבל.</p>"],[1200950117,"ז'תתעב\n\n<p>ב\"ה, ט\"ו בשבט ר\"ה לאילן ה'תשי\"א</p><p>ברוקלין, נ.י.</p>\n<p>שלום וברכה!</p>\n<p>נסתיימה שנת ההסתלקות של נשיאנו כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>מתגברים הגעגועים באשר כלה קייץ עובר חורף ואנחנו לא נושענו.</p>\n<p>אבל מצד השני ההרגל עושה את שלו. ויש מקום לחשש אשר יתיישן הדבר, ואור וחום ההתקשרות לנשיאנו, לתורתו ולהוראותיו - אשר כולא חד - ילך הלוך וחסור ח\"ו.</p>\n<p>אלה הדברים אשר דבר משה בנוגע לתורה: הדברים האלה אשר אנכי מצוך <b>היום,</b> ופירושו: כדיוטגמא (מכתב המלך) חדשה שהכל רצין לקראתה. ובנוגע למצות: מצותי אשר אנכי מצוה אתכם <b>היום,</b> ופירושו: שיהיו עליכם חדשים כאילו שמעתם בו ביום.</p>\n<h4><i><b>ז'תתעב</b></i></h4>\n<p>מצילום כתי\"ק. ונראה שהיא התחלה ממכתב כללי שלא נגמר בכתיבה.</p>"],[1200950118,"ז'תתעג\n\n<p>ב\"ה, כ\"ט שבט, ה'תשי\"א</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו המודיע ממצב בריאותו, אשר מרגיש תשישות הכוחות והרופא רוצה לעשות בדיקות וכו' ושואל דעתי-</p>\n<p>קאן ער אים נאכגעבן ולעשות הבדיקות. ובנוגע לתשישות הכחות - יהי זהיר בפת של שחרית, ומזמן לזמן ילמוד איזה לימוד, אם בנגלה אם בדא\"ח, וואס ער זאל פון עם הנאה האבן <b>גאר בפשטות.</b> ורפאות תהי לשרך ושיקוי לעצמותיך.</p>\n<p>בהיותי על הציון של כ\"ק מו\"ח אדמו\"ר אזכירו ואת זוגתו תי' לבריאות הנכונה.</p>\n<p>ותקותי שיבשרני בשורות טובות בזה.</p>\n<p>ולפלא שאינו מזכיר דבר ע\"ד בריאותו ברוחניות.</p>\n<p>ואולי שמע הסיפור של א' מבני אמריקא שבא לשאול עצת כ\"ק מו\"ח אדמו\"ר במסחר עצים שלו. ואחרי המענה בזה והמשיך כ\"ק מו\"ח אדמו\"ר להורותו בעניני תומ\"צ - אמר שהרי לא אודות זה שאל. וא\"ל כ\"ק מו\"ח אדמו\"ר: כלפי לייא. מסחר שאתה המומחה ואין זה שייך אלי - תשאל בעצתי. ובתומ\"צ שזהו מעניני העקרים ומעסק אבותי ואבות אבותי - בזה אין אתה שואל.</p>\n<p>כמובן אין הנדון דומה כלל - אבל, בכל אופן, יש לי שייכות יותר ללימוד גפ\"ת ודא\"ח מאשר לחכמת הרפואה. וא\"כ כלפי לייא?</p>\n<p>בברכת רפואה קרובה ובריאות הנכונה לו ולזוגתו יחיו.</p>\n<h4><i><b>ז'תתעג</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>הסיפור:</b> ראה גם לעיל ח\"ד אגרת א'לו.</p>"],[1200950119,"ז'תתעד\n\n<p>ב\"ה, ז' אדר שני, ה'תיש\"א</p><p>ברוקלין, נ.י.</p><p>... מכתבו בעתו נתקבל, כן מסר לי בשעתו מר...ש י' את ס'... ות\"ח ת\"ח על תשורתו זו. - ומהנכון, לעודד את רוח הנ\"ל, ולהסבירו שלא זו הדרך פירן א ברוגז מיט דער ועלט און מיטן כביכול, ח\"ו. וטוב <b>לעבוד,</b> כעבד, ולא כשר בעל שכל את השי\"ת ובשמחה, וסוף סוף ימשיך עי\"ז שמחה גם בנפשו... קאפ' ע\"א צ\"ל עד י\"ב תמוז.</p>\n<h4><i><b>ז'תתעד</b></i></h4>\n<p>מצילום כתי\"ק, בשולי אגרת תתקמא דלעיל ח\"ד.</p>\n<p><b>קאפ' עא:</b> כמניןש נות כ\"קג אדמור, מוהריי\"צ נ\"ע.</p>\n<p><b>עד י\"ב תמוז:</b> כשימלאו לכ\"ק אדמו\"ר מוהריי\"צ נ\"ע עא שנים. ראה גם לעיל ח\"ד אגרות תתנח. תתסג.</p>"],[1200950120,"ז'תתעה\n\n<p>ב\"ה, י\"ב אד\"ש, תשי\"א</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכ' מיום א' פקודי המודיע שאין כל כך שלום בית בינו ובין זוגתו תי' ושואל לדעתי מה לעשות:</p>\n<p>הנה כיון שכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ברך את נשואי[ה]ם בברכת מזל טוב, הרי דברי צדיקים קיימים לעד, וצריך לפייס את זוגתו תי' ולהסביר לה את הנ\"ל, ובודאי, אם נזקק לזה, יסייעו גם זקני אנ\"ש...להשכין השלום ביניהם, ועל ידי דברים שבנחת וענינים של קירוב, בטח ימצא הדרך ללבה ויהי' שלום ושלוה במעונם, ויתברכו בזרעא חייא וקיימא.</p>\n<p>הפ\"נ שלו בעד... נתקבל וקראתיו על ציון כ\"ק מו\"ח אדמו\"ר לעורר ר\"ר עליהם להמצטרך להם.</p>\n<p>בברכת פורים שמח,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתעה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ג ע' 44.</p>\n<p>לתוכנה ראה גם אגרת הבאה.</p>"],[1200950121,"ז'תתעו\n\n<p>ב\"ה, י\"ב אד\"ש, תשי\"א</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>צו מיין צער, האב איך געהערט, אז, צייטנווייז, איז בא אייך אין שטוב ניט גאנץ דער שלום בית. איך וויל האפן אז עס איז ניט ריכטיג, אדער ווייניגסטנס נאר אריבערגייענד, און איר וועט מיר שרייבן וועגן דעם (אין וועלכער שפראך אייך איז אודאבנער).</p>\n<p>בכל אופן, וויל איך אייך דערמאנען אז דער רבי, דער שווער זצוקללה\"ה נבג\"מ זי\"ע, האט געבענטשט אייער חתונה מיט אייר מאן שי' מיט א ברכת מזל טוב, דארפט איר מיט אייער מאן שיחיו זען זיין גוטע כלים אויף מקבל זיין די ברכה און האבן א ווארימע חסידישע הויז ובזרעא חייא וקיימא.</p>\n<p>אין ערווארטונג פון גוטע בשורות פון אייך,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתעו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ג ע' 45.</p>\n<p>לתוכנה ראה גם אגרת הקודמת.</p>\n<p><b>אודאבנער:</b> יותר נוח.</p>"],[1200950122,"ז'תתעז\n\n<p>פורים, תשי\"א</p>\n<p>בבקשה להתועד בפורים וגם בשבת בהתעוררות מיוחדת לעבודה בחינוך וביראת שמים.</p>\n<p>בברכת פורים שמח,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתעז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 68.</p>"],[1200950123,"ז'תתעח\n\n<p>ב\"ה, י\"א ניסן, ה' תיש\"א</p><p>ברוקלין, נ.י.</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ וכו' מוהרר\"נ שי'<br>\nהכהן</p>\n<p>שלום וברכה!</p>\n<p>... כל הפ\"נ והמכ' שלו נתקבלו בעתם. ובעת רצון קראתי הפ\"נ על הציון. ובטח יתמלאו לטובה ולברכה בגו\"ר, ויודיע עד\"ז בשו\"ט.</p>\n<p>- צדק בכתבו, שצריך אני לענות על כל המכ' והשאלות בהקדם. אבל מה עלי לעשות - והטרדות הולכות ורבות, גם הכללים וגם הפרטים. על כמה מהשאלות הנני עונה במכתבי הכללים המצורפים להקונ' או שבהקדמה לקונ', ועל השאר בודאי סו\"ס יעזור השי\"ת גם על זה.</p>\n<h4><i><b>ז'תתעח</b></i></h4>\n<p>מצילום האגרת, בשולי אגרת תתקעב דלעיל ח\"ד.</p>\n<p><b>מהורר\"נ שי' הכהן:</b> אגרות נוספות אליו - לעיל חי\"ט ז'שמט, ובהנסמן בהערות שם.</p>\n<p>לקמן ז'תתקא. ז'קתתקכב. ז'תתקלד. ז'תתקפג.</p>"],[1200950124,"ז'תתעט\n\n<p>ב\"ה, ט\"ז אייר, תשי\"א</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ באמונה<br>\nכו' וכו'<br>\nמו\"ה חיים זוסיא שי'</p>\n<p>שלום וברכה!</p>\n<p>זה זמן רב שלא שמעתי ממנו בעצמו, וגם אחרים לא הודיעוני מהנעשה אתו, וא\"ת אהי' לו אם יכתוב לי ממצבו עתה ומהשתתפותו בעסקנות 7הציבורית בכל, ובעניננו אנו, חב\"ד, בפרט.</p>\n<p>אתענין לדעת בנוגע השתדלותו ע\"ד שדוך המתאים בשבילו בגו\"ר.</p>\n<p>אינני יודע גם כתבתו הנכונה, ולכן הנני שולח מכתבי זה ע\"י הרה\"ח הוו\"ח אי\"א וכו' מוה\"ר, אברהם פאריז שי'.</p>\n<p>המחכה לבשו\"ט ממנו.</p>\n<p><b>מחנם שניאורסאהן</b></p>\n<p>מוסג\"פ החוברת לל\"ג בעומר ומכ' הכללי השייך אלי'.</p>\n<h4><i><b>ז'תתעט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 111, מצילום האגרת.</p>\n<p><b>מו\"ה חיים זוסיא:</b> ווילימובסקי. אגרות נוספות אליו - לעיל חי\"ט ז'ערה, ובהנסמן בהערות שם. לקמן ח'מה. חו' עז. ח'צב. ח'קכג. ח'קלב. ח'קלד. ח'קלז. ח'קלט. ח'ריד.</p>\n<p><b>וא\"ת:</b> ואסיר תודה.</p>"],[1200950125,"ז'תתפ\n\n<p>ב\"ה, כ\"ב אייר, תשי\"א</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>ע\"י הרה\"ח הוו\"ח אי\"א עוסק בצרכי צבור באמונה וכו' וכו' מוה\"ר שלמה זלמן שי' העכט קבלתי את שאלתו, אשר חפץ הוא לסדר אשר לאחר מאה ועשרים שנה יהי' בטוח באמירת קדיש ולימוד משניות:</p>\n<p>והנה אם רצונו הוא בזה, אפשר לסדר זה אשר לאחר מאה ועשרים שנה יאמרו קדיש וילמדו משניות באה\"ק ת\"ו (את המחיר אינני יודע בדיוק, אבל הוא בערך 300 -400 שקל ארצוה\"ב).</p>\n<p>אבל בעיקר הדבר, הנה ידוע הוא פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אז עס איז גלייכער צו טאן מיט לעבעדיקע זאכן ביים לעבן, ולכן הצעתי שיאריך ימים ושנים טובות וארוכות היינו ממולאים מתורה ומצות מתוך מנוחת הנפש ומנוחת הגוף,</p>\n<p>ויקח על עצמו הדפסת ספר משיחות כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וידפסו בראש הספר את שמו ושם זוגתו תחי' וכל שילמוד בספר הזה, הנה יהי' לו ולזוגתו תחי' השתתפות בלימודו, וזכות הרבים תלוי בהם להאריך ימיהם ושנותיהם בנעימים.</p>\n<p>מוסג\"פ החוברת שי\"ל לל\"ג בעומר בטח ילמוד בה ויתעמק בהפתגמים אשר בה.</p>\n<p>בברכת אריכות ימים ושנים טובות לו ולזוגתו יחיו מתוך מנוחה והרווחה.</p>\n<h4><i><b>ז'תתפ</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>ידוע הוא פתגם:</b> ראה אג\"ק אדמו\"ר מוהריי\"צ נ\"ע ח\"ח אגרות ב'קנו. ב'שלה.</p>"],[1200950126,"ז'תתפא\n\n<p>שבועות, תשי\"א</p>\n<p>למסור לאנ\"ש ברכת קבלת התורה בשמחה ובפנימיות ובטח יעריכו התועדות חסידותית.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתפא</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 68.</p>"],[1200950127,"ז'תתפב\n\n<p>ב\"ה, יום ראשון לסדר בהעלתך את הנרות, תיש\"א</p><p>ברוקלין, נ.י.</p><p>צו אלע איינטיילנעמער אויף דער היינטיקער התועדות פון<br>\n\"ארגון בית רבקה\"<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>א בשורה טובה איז געווען פאר מיר די ידיעה, אז דער \"ארגון בית רבקה\" - תחת השגחת המרכז לעיני חנוך - האט ערווארבן נאך א בנין אין א נייעם טייל פון שטאדט, מיט דעם ציעל צו עפענען דארטן נאך א \"בית רבקה\" סקול, און געבן דורכדעם די מעגליכקייט פאר א גרעסערער צאל פון אידישע טעכטער - כן ירבו - צו באקומען אן ערציאונג ברוח התורה והיהדות.</p>\n<p>דאס פארגרעסערונג און אויסברייטונג פון א וויכטיקן מוסד, איז בכלל צופרידנשטעלנד, שוין צוליב דעם ווואס עס באווייזט אויף דער לעבנסקראפט פון דעם אנשטאלט, נאך מער באגריסנסווערט איז די גרינדונג פון חנוך תורה מוסדות, אין מערער און מערער טיילן פון שטאדט, וואס דורכדעם וועט בעזרת השם יתברך געזיכערט דער גייסטיקער און פיזישער קיום פון כלל ישראל.</p>\n<p>באזונדער צו באגריסן איז די עפענונג פון נייע אפטיילונגען פון די \"בית רבקה\" שולעס, וואס באווייזט אויף דעם באוואוסטזיין פון זייערע עסקנים, אז מען טאר זיך ניט באפרידיקן מיט דעם וואס ס'איז שוין עררייכט געווארן אויף דער געביט, כל זמן עס איז נאך דא איין אידישע מיידעלע וועלכע באקומט ניט איר ערציאונג, צוליב מאנגל פון א געהעריקע צאל עכט אידישע שולעס.</p>\n<p>איך שיק מיין באגריסונג צו אלע אנטיילנעמער אויף דער חגיגה און צו אלע עסקנים פון \"ארגון בית רבקה\" בראש מיט הרה\"ח הוו\"ח אי\"א נו\"מ עסקן נמרץ ורב פעלים וכו' מהור\"י שי' דזשייקאבסאן, און רוף זיי אונערמידנד צו ארבעטן נאך מער און מער פאר דעם חנוך הבנות על טהרת הקדש, לויט דעם רצון וציווי פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>איך האף, אז יעדער באוואוסטזיניקער איד, מאן און פרוי, וועלן ערפילן זייער פליכט מיטצוהעלפן דעם קיום און אויסברייטונג פון די שוין עקזיסטירנדע בית רבקה שולעס און פאר דער ערעפנונג פון נייע בית רבקה שולעס.</p>\n<p>בא א באזוך פון חינוך עסקנים בא עם, האט כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע געזאגט:</p>\n<p><b>\"דער אויבערשטער בלייבט ניט קיין בעל חוב, און די אלע וואס טוען און העלפען</b> <b>אויפן געביט פון חינוך הכשר - באצאלט זיי דער אויבערשטער בהמצטרך להם,</b> <b>ובפרט אין אידישען נחת פון קינדער\".</b></p>\n<p>דברי צדיקים חיים וקיימים לעד.</p>\n<p>ובטח וועט השי\"ת בענשען אלע מיטהעלפער פון דער בית רבקה בעוועגונג, און די איינטיילנעמער פון דער צוזאמענקונפט בתוכם, בהמצטרך להם בגשמיות וברוחניות.</p>\n<p>בברכת טוב גשמי ורוחני,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתפב</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>געזאגט:</b> ראה גם לעיל ח\"ז אגת ב'קי, ובהנסמן בהערות שם. לקמן ז'תתקיז. ז'תתקסט.</p>"],[1200950128,"ז'תתפג\n\n<p>ב\"ה, כ\"ב סיון, תשי\"א</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר שניאור<br>\nזלמן שי'</p>\n<p>שלום וברכה!</p>\n<p>... מכ' מי\"ט אייר נתקבל. וכנראה רשם בחפזון, כי כמה פרטים אי מובנים.</p>\n<p>הסיפור דמשקפים של אדמו\"ר מהר\"ש - סיפרה כ\"ק מו\"ח אדמו\"ר בשם הר\"מ, מאנעסזאהן שבחן זה בעצמו - אבל <b>במאריענבד.</b></p>\n<h4><i><b>ז'תתפג</b></i></h4>\n<p>מצילום האגרת בלשמע אוזן 0הוצ' תש\"נ) ע' שכו.</p>\n<p><b>מוה\"ר שניאור זלמן:</b> דוכמן. אגרות נוספות אליו - לעיל ז'תתנט, ובהנסמן בהערותש ם.</p>\n<p><b>הסיפור דמשקפייםף</b> המסופר שם ע' פב.</p>"],[1200950129,"ז'תתפד\n\n<p>ב\"ה, כ\"ב סיון תשי\"א</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר אליעזר שי'</p>\n<p>שלום וברכה!</p>\n<p>... מצטער הנני, שהנהו מקצר בנוגע למצב בריאותו, אף שבכלל מכיון שאינו מזכיר, בודאי מרגיש א\"ע בטוב, והלואי שיהי' כן, אבל טוב יותר אם יכתוב זה בפירוש ולא לצאת במלים אחדים.</p>\n<p>וכן הנני להזכירו עוה\"פ במה שאמרתי לכת\"ר בהיותו כאן, שקביעות שיעור בלימוד הדא\"ח בעיון (במקום שלבו חפץ) תהי' זה אחת הרפואות היותר מועילות במצב בריאותו.</p>\n<p>... בברכת רפואה קרובה בריאות הנכונה והצלחה בכל עסקיו בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתפד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 122, מצילום האגרת. והיא השלמה לאגרת א'ס דלעיל ח\"ד.</p>\n<p><b>מוה\"ר אליעזר:</b> קרסיק. אגרות נוספות אליו - לעיל ז' תשפה, ובהנסמן בהערות שם.</p>"],[1200950130,"ז'תתפה\n\n<p>ב\"ה, ו' תמוז, תשי\"א</p><p>ברוקלין.</p><p>מר יוסף יהודא שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה למכתבו, בו כותב ראשי פרקים מתולדותיו, ואשר מורה הוא בעניני מוסיקה הן בבי\"ס והן לפרטים.</p>\n<p>ובודאי למותר להאריך בהסבר דבר המשנה, אני נבראתי לשמש את קוני, והוא ע\"י קיום רצון קונו, בלימוד התורה וקיום המצות, שמזה מובן שבאיזה מקצוע שיהי' שמתעסק האדם, ברור שגם בו אפשריות להפיץ היהדות האמיתית ועניני' בתוככי אלה שבא עמהם במגע ובקישור, ועאכו\"כ אם הקישור הוא [יחס] שלמורה ותלמיד, אשר תמיד כל תלמיד רגש של אהבה וכבוד אצלו להמורה, שזהו מכשירו ג\"כ - את התלמיד - לקבל דברי המורה אפילו שלא בשטח המקצוע, וכנראה כל זה במוחש, ובפרט שלפי כתבו תלמידיו למקצוע הם ברובם מהנוער, אשר כל שיפור ותיקון מצבם, הרי זהו תיקון ושיפור בעניניהם העתיד, ולכל לראש בבנין ביתם בישראל.</p>\n<p>ומהנ\"ל מובן, אשר כל יגיעה והשתדלות בזה כדאיות הן.</p>\n<p>במ\"ש אודות כניסה ללמוד בישיבת תומכי תמימים דלוד, ומפרט מניעות אחדות המונעות אותו מזה.</p>\n<p>הרי בכלל השאלה בפועל תעמוד על סדר היום בעוד כחודש ויותר, לאחרי ההפסק של הקיץ, שאז סדר מסודר בישיבה, והרי אפשר שבמשך זמן זה יסתדרו איז פרטים מאלה שמזכירם במכתבו.</p>\n<p>ובמ\"ש שישנם אצלו חובות ולכן גם לאחר שיכנס לישיבה צריך יהי' להמשיך עבודתו במקצוע בכדי לסלק החובות - הנה בטח יבוא בדברים בזה עם הנהלת הישיבה, והרי כמה אפשריות בסידור הנ\"ל באופן שיוכל לקיים כל סדרי הישיבה. וכבר נאמר ותשועה ברוב יועץ.</p>\n<p>ויהי רצון מבורא עולם ומנהיגו המשגיח על כאו\"א בהשגחה פרטית, אשר יעלה מחיל אל חיל בדרך התורה והמצוה, היא הדרך המובילה את האיש והאשה הישראלים לאשרם האמיתי הן בגשמיות והן ברוחניות, וינעם לי לקבל ממנו בשו\"ט בכל האמור.</p>\n<p>בברכה לבשו\"ט.</p>\n<h4><i><b>ז'תתפה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 82.</p>\n<p><b>מר יוסף יהודה שי':</b> מרטון. אגרות נוספות אליו - לעיל ח\"כ ז'תקסה, ובהנסמן בהערות שם.</p>"],[1200950131,"ז'תתפו\n\n<p>י\"ב תמוז, תשי\"א</p>\n<p>למסור לכל אנ\"ש: לחיים, לחיים ולברכה ולהתעוררות בהצלחה בהחזקת היהדות והרבצת תורה הנגלה והחסידות..</p>\n<p><b>מנחם שניאוסאהן</b></p>\n<h4><i><b>ז'תתפו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 68.</p>"],[1200950132,"ז'תתפז\n\n<p>ב\"ה, ט\"ו מנ\"א, תשי\"א</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>זה עתה שלחתי לו מברק: \"אתפלא במאד על נפילת רוחו. יעשה כהוראת שני רופאים מומחים ויתחזק בבטחונו בהשי\"ת אשר בודאי יחזירו לאיתנו. ואחכה לבשורות טובות. בברכת רפואה קרובה. חתימתי\".</p>\n<p>מ'לערנט, מ'לערנט - און אז עס קומט לפועל, וואו איז דער בטחון?</p>\n<p>ילמוד ג' או ד' פעמים שער הבטחון ב\"חובת הלבבות\". כמובן, שאין כוונתי שילמוד זה בפעם אחת, אלא במשך איזה שבועות..</p>\n<p>בברכת רפואה קרובה, המחכה לבשורות טובות בבריאותו בגשמיות ובבריאותו ברוחניות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתפז</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950133,"ז'תתפח\n\n<p>ב\"ה, כ\"ה מנ\"א, תשי\"א</p><p>ברוקלין.</p><p>1ש\"ב הרה\"צ הרה\"ח וו\"ח נו\"מ אי\"א בנש\"ק<br>\nגזע תרשישים<br>\nוכו' וכו' מוהר\"ר יוחנן שי'</p>\n<p>שלום וברכה!</p>\n<p>בנועם ובשעתו קבלתי מכתבו מח\"י מנ\"א, בו מודיע אשר ביום ד' אלול הבע\"ל תהי' חתונת בנו בכורו שליט\"א:</p>\n<p>והנני בזה להביע ברכותי מקול\"ע, ברכת מזל טוב מזל טוב, שתהי' החתונה בשעה טובה ומוצלחת ויעלה הזיווג ליפה ויבנו בנין עדי עד על יסודי התורה והמצוה כפי שנתבארו בתורת החסידות הוא תורת דא\"ח, ויראו המהם ומשאר ילידיהם שי' רוב נחת ועונג בגשמיות וברוחניות גם יחד.</p>\n<p>ידוע אשר ענין הזיווג הוא למעלה מסדר ההשתלשלות, וכמרז\"ל שדומה לקרי\"ס, דבעתיקא תליא מילתא, היינו שזהו המשכה מאור המקיף.</p>\n<p>וי\"ל שזהו שמצינו בענין הנשואין ענין המקיפים: א) מקיף ע\"ג הכלה לבד, שזהו ענין נתינת הטבעת,</p>\n<p>וכידוע, שאף שבמשנה ראי' נקנית בכסף, אבל כבר אמרו בתקו\"ז תיקון ה' בתחלתו ותיקון יו\"ד ותיקון כ\"א (נ\"ה ע\"ב): ובגינא איתמר לגבי כלה תהא לי מקודשת <b>בטבעת</b> זו, וכדאי' ג\"כ בכמה מקומות אשר בני ארץ ישראל מקדשים בטבעת (חילוף מנהגים שבין בני בבל לארץ ישראל, בים של שלמה, ובכ\"מ).</p>\n<p>אשר נתינת הטבעת הוא מקיף על (אצבע) הכלה ובא מהחתן.</p>\n<p>[(ב)] הכלה מסובבת את החתן ז' פעמים, שזהו מקיף על החתן הבא מהכלה. וע\"ד דלע\"ל נקבה תסובב גבר.</p>\n<p>ושני מקיפים אלו באים תחת החופה, שזהו מקיף כללי על החתן והכלה גם יחד, היינו מקיף בינה לזו\"נ, ומבואר הענין בלקו\"ת שה\"ש ד\"ה על כל כבוד חופה, ואין כאן מקום להאריך.</p>\n<p>החותם מעין הפתיחה בברכת מז\"ט מז\"ט, ש\"ב מכבדו ומוקירו.</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ\"ב: בתור דרשה געשאנק, מוסג\"פ סערטיפיקאט על חבילה. וענין השייכות דדרשה געשאנק למקיף יעויין לקו\"ת פ' נשא דכ\"ט ע\"ב.</p>\n<h4><i><b>ז'תתפח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 97, מצילום האגרת.</p>\n<p>מוהר\"ר יוחנן: טברסקי, האדמור, מרחמיטסרייוקא. אגרות נוספת אליו - לעילח\"ד א'רי.</p>\n<p><b>בנו בכורו שליט\"א:</b> מוה\"ר מרדכי טברסקי, האדמו\"ר מרחמיסטריווקא שליט\"א.</p>\n<p><b>מקול\"ע:</b> מקרב ולב עמוק.</p>"],[1200950134,"ז'תתפט\n\n<p>ב\"ה, ח' אלול, תשי\"א</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו מה' שופטים, שבו מתאר מצב בריאות.. תחי' ושואל חוו\"ד בנוגע למה שאמר לה הרופא:</p>\n<p>הנה לפ\"ד, בנוגע של הנתוח למרידין, אם זהו דעת שני רופאים מומחים במקצוע זה, תעשה זאת, ויתן השי\"ת שיה'י בהצלחה.</p>\n<p>ובנוגע לענין השני שמציע לה לעשות נתוח על האם, הנה בדבר זה צריכים לברר אצל הרופא מהו כוונתו בזה, אם הוא רוצה לעשות קלין אפ לגמרי, או שרק לחתוך את הטומאר, ואם הוא באופן הראשון אשר בד\"כ הרופאים דארצוה\"ב להוטים אח\"ז, אזי ישאל ג\"כ דעת עוד שני רופאים ורק אם שלשתם יחד יסכימו לעשות קלין אפ, יעשו כזה. והשי\"ת יתן בלב הרופאים דיעה הישרה לכווין אל האמת והטוב, וה' ישלח דברו וירפאה ע\"י רופא פלוני וסם פלוני.</p>\n<p>במ\"ש אודות... שי' ימלא כהוראת הרופאים, והעיקר בעניני אכילה ושתי' ומנוחה, און ער זאל זיין א סאלדאט להשי\"ת כמו שצ\"ל, וכמ\"ש הרמב\"ם הלכות דיעות רפ\"ד: היות הגוף בריא ושלם מדרכי השם הוא.</p>\n<p>מכתבי הכללי להתלמידים להתחלת זמן הלימודים, בטח הגיע אליו במועדו, ואקוה להתבשר ממנו טובות להתחלת הלימוד כדבעי למהוי, ובעיקר מהגדלת מספר התלמידים והתלמידות, וכפסק התורה מעלין בקדש.</p>\n<p>בברכת כוח\"ט לשנה טובה ומתוקה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ\"ב: הנני מתפלא על אשר נמשך הענין אצל מר...שי' כ\"כ, ואולי, כדאי הי' להציע לו, שלא יחכה עד שיעשה הדבר ויסדר את המכונות, כ\"א יסלק מה שחשב ליתן על הדפסה מראש. וכאשר מראים להשי\"ת הנהגה ב[ה]רחבה, מראים ג\"כ מלמעלה היד רחבה וכו'.</p>\n<h4><i><b>ז'תתפט</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950135,"ז'תתצ\n\n<p>ב\"ה, שלהי אלול, תיש\"א</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ וכו' מהו\"ר יעקב שי'</p>\n<p>שלום וברכה!</p>\n<p>המכ' והפ\"נ נתקבלו, ולקראת השנה החדשה, הבא עלינו על כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולב\"ב שיחיו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>מרז\"ל תוקפא דגופא דנשמתא [דנפשא] - ראה זח\"א קפ:, קמ:. הגירסא</p>\n<p>דנפשא - מפרטת יותר שמצב הגוף נוגע במדרי' הנשמה הסמוכה אליו דוקא והיא הנק' נפשא, וכידוע.</p>\n<h4><i><b>ז'תתצ</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מהו\"ר יעקב שי':</b> פלס. אגרות נוספות אליו - לעיל חי\"ח ו'תרצו, ובהנסמן בהערות שם.</p>\n<p>לקמן ח'קיז.</p>"],[1200950136,"ז'תתצא\n\n<p>ב\"ה שלהי תשרי ה'תשי\"ב</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מהו\"ר פנחס שי'</p>\n<p>שלום וברכה!</p>\n<p>בעתו קבלתי הפ\"נ ע\"י הרה\"ח הוו\"ח אי\"א נו\"מ עוסק בצ\"צ וכו' מהו\"ר מנחם זאב שי' גרינגלאס, אלא שמפני רוב טרדות החגים וימי התשרי נתעכב המענה עד עתה.</p>\n<p>וברכה בכל עת זמנה היא, ואברכו ואת זוגתו תחי' בשנה טובה ומתוקה בגשמיות וברוחניות גם יחד, שנת מילוי משאלות לבבם לטובה.</p>\n<p>יצייר לעצמו מזמן לזמן צורת רבו - בעהמ\"ס מנח\"א - וישתדל בפרנסת אחרים ברוחניות, והשי\"ת יפרנסו בהרחבה בגו\"ר.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסראהן</b></p>\n<h4><i><b>ז'תתצא</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מהו\"ר פנחס:</b> אסטרייכער.</p>"],[1200950137,"ז'תתצב\n\n<p>ב\"ה, ג' כסלו, תשי\"ב</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>... ומהנכון הי' שיעורר את חתנו שי' על קיום ההבטחה שלקח על עצמו מרצונו הטוב, להיטיב דרכיו בתורה ומצות, באם שיוטב מצב בריאותה, ולמה לו לחכות על אזהרות מלמעלה וכו'. וידוע אשר נתחנכנו כולנו בדרך התורה שכדרכי' דרכי נועם, וכפתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אז עס ווילט זיך ריידין נאר אין דער גוטער זייט, ויהי רצון שיוטב מצבו ברוחניות וגם בגשמיות וביחד עם זוגתו, היא בתו תחי', יראו רוב נחת מילידיהם שיחיו...</p>\n<p>בברכה לכת\"ר שי' להסתדרות הנכונה וגם כפשוטו ממש בדירה המתאימה</p>\n<p>ולבריאות טובה לו ולזוגתו תחי', המחכה לבשו\"ט בכל הנ\"ל,</p>\n<p><b>מ. שניאורסאהן</b></p><p>יו\"ד כסלו. נתעכב מכ' זה. וזה עתה הגיע הבשו\"ט שנחלמה נכדתו תי', אבל הנ\"ל - בתוקפו עומד.</p>\n<h4><i><b>ז'תתצב</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950138,"ז'תתצג\n\n<p>ב\"ה, ג' כסלו, תשי\"ב</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר מיכאל יהודה<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>מיט פרייד האב איך עהראלטן אייער בריף פון כ\"ג חשון, אז אייער געזונט צושטאנד איז בעסער יעצט ווי געווען, און אז דער ד\"ר גיט גוטע העפנונג אז עס וועט [ווערן] בעסער און בעסער.</p>\n<p>איך וועל בל\"נ ערפילן אייער בקשה און מזכיר זיין אייך לרפואה קרובה, ווען איך וועל זיין אויפן ציון פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, און האף אז איר וועט מיר קאנען אנזאגן אין קומענדן בריף אז איר פילט בעסער און בעסער.</p>\n<p>בכלל אין אזעלע זאכן, דארפמען פאלגן דעם ד\"ר, צו אויסהיטן זיך פון גיין אויף טרעפ וכו', אבער גלייכצייטיק זיין שטארק אין בטחון בהשם יתברך וואס ער איז דער רופא כל בשר ומפליא לעשות, אז אזוי וועט זיין אויך בפועל ממש אין אייער ענין, און וואס דער בטחון איז שטארקער אין דעם, איז דער געזונט פארבעסערונג און די רפואה אלס גיכער.</p>\n<p>איך האף אז פון צייט צו צייט באזוכן אייך אונזערע פרייד ובפרט מוה\"ר שניאור זלמן שי' בוטמאן.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתצג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 98, מהעתקה.</p>\n<p><b>מוה\"רמיכאל יהודה:</b> שווארצקאפ, פריז.</p>"],[1200950139,"ז'תתצד\n\n<p>ב\"ה, ה' כסלו, תשי\"ב</p><p>ברוקלין.</p><p>להאברכים מו\"ה אברהם יצחק שם-טוב<br>\nמו\"ה שלום<br>\nדובער פוטערפאס, ומו\"ה שמואל דוד<br>\nגורקאו,<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מזמן לזמן הנני מקבל ידיעות ע\"ד לימודם בישיבת מנשסתר. ואף כי באיזה פרטים הנני שבע רצון מהנהגתם, אבל אם גם הכל הי' כדבעי למהוי, הנה ידוע פתגם כ\"ק אדמו\"ר מוהר\"ש נ\"ע, שחזר עליו כמה פעמים כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע: \"אז גוט איז גוט, איז בעסער ניט בעסער:\". ובפרט שבאיזה פרטים כנראה, הנהגתם והתמדתם בלימוד צריכה עידוד וחיזוק.</p>\n<p>ובאתי בזה לעוררם, ע\"ד שם התואר שנתן כ\"ק אדמו\"ר (מוהרש\"ב) נ\"ע להתמימים, שהם צריכים להיות - נרות להאיר. ואם כן בפשטות הוא, שזהו צריך להיות בבני התמימים. ועל כל אחד ואחד מכם להיות חקוק בזכרונו, האחריות הגדולה המוטלת עליו, שהוא צריך לשמש מופת לכל שאר התלמידים הנמצאים בהישיבה, אשר ממנו יראו וכן יעשו, ולא לבד בלימוד החסידות ובעבודת התפלה, אלא ג\"כ בלימוד הנגלה בכלל, ובעניני דרך ארץ שבין אדם לחבירו.</p>\n<p>אקוה אשר דבריי אלה המועטים בכמות יספיקו לעוררם ולהעמידם על האמת, אשר בתכלית בואם לישיבת מנשסתר, הוא לא רק לתועלת עצמם אלא להשפיע ג\"כ על הסביבה שלהם, לשמש דוגמא איך שבן ישיבה צריך להיות בפנימיות וגם בחיצוניות.</p>\n<p>אחכה לבשורה טובה מהם מקבלת מכתבי זה, ואשר נגשו להביא את הענין בפועל ממש בכל הפרטים הנ\"ל.</p>\n<p>בברכת הצלחה בלימוד תורתה נגלה ותורת החסידות מתוך יראת שמים,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתצד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 56; ד ע' 85, מצילום האגרת.</p>\n<p><b>ידוע פתגם:</b> ראה גם לעיל אגרת ז'תשעז, ובהנסמן בהערות שם.</p>"],[1200950140,"ז'תתצה\n\n<p>ב\"ה, ה' כסלו, תשי\"ב</p><p>ברוקלין.</p><p>האברך מר אברהם יצחק שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו מבדר\"ח כסלו ובו פ\"נ בקשה להתקשרות ולהצלחה בלימוד וכו'.</p>\n<p>והנה כתבתי מכתב לו ולשני חבריו מר שלום דובער פוטערפאס ומר שמואל דוד גורקאוו שיחיו, ובטח יקראוהו בשימת לב הראוי' ולהביא לפועל את כל הענינים האמורים במכתבי, שזה התקשרות הנדרשת. ואחכה לבשו\"ט בזה.</p>\n<p>בברכת הצלחה בת\"ת ביר\"ש.</p>\n<h4><i><b>ז'תתצה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 86.</p>\n<p><b>אברהם יצחק שי':</b> שם טוב. אגרות נוספות אליו - לעיל ז'תתצד. לקמן ז'תתצח.</p>\n<p><b>כתבתי:</b> באגרת הקודמת.</p>"],[1200950141,"ז'תתצו\n\n<p>ב\"ה, י\"א כסלו, תשי\"ב</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"מ עסקן חרוץ ורב פעלים וכו'<br>\nוכו' מו\"ה<br>\nשמואל שי' ברוידע יו\"ר \"קרן ההצלה\"<br>\nשיקגו</p>\n<p>שלום וברכה!</p>\n<p>הרבנים הנכבדים הרה\"ג והרה\"ח וו\"ח, אי\"א נו\"מ וכו' וכו' מוהר\"ר שמואל שי' לויטין ומוהר\"ר אלי' שי' סימפסון סיפרו לי מביקורם אצל מע\"כ שי' ודברו בשבחו בעד יחסו הטוב שהראה לעבודת ליובאוויטש במקצוע ההצלה והחינוך והבטחתו להיות לנו לעזר על ידי \"קרן ההצלה\" דמחנו.</p>\n<p>בינתים בטח קבל מע\"כ שי' את מכתבי הרשמי לקרן ההצלה מיום ה' העבר.</p>\n<p>חושבני כי למותר הוא להרחיב הדיבור לדכוותי' על דבר ההכרח החיוני שבעבודתנו זו וגודל דרישת השעה לא רק להחזיק מעמד והיקפה הנוכחי אלא גם להרחיבה ולהגדילה, כי בנפש כמה וכמה מבני ובנות ישראל הוא.</p>\n<p>והנני כופל בקשתי לכ\"מ שי' ביחוד, אשר מכיר הוא בטיב עבודה זו בכמותה ואיכותה ולא רק מפי השמועה אלא גם מאשר ראה בעיניו, ובטוח אני אשר ישתדל בכל עוז אשר קרן ההצלה דמחנו תקציב עזר הגון הן בעד עבודתנו באירופה ובארה\"ק ת\"ו והן בעד עבודתנו בצפון אפריקה.</p>\n<p>וזכות כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, שסלל לנו הדרך בעבודת העזרה וההצלחה במסירות נפש, בטח תעמוד לו להמשיך ולהשפיע לו שפעת ברכה והצלחה בעבודתו הציבורית ובעניניו הפרטים בגשמיות וברוחניות.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתצו</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>קרן ההצלה:</b> ראה לעיל ח\"ד אגרות תתקצב. א'פט. ח\"ח ב'רצו.</p>"],[1200950142,"ז'תתצז\n\n<p>ב\"ה, י\"ט כסלו, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ וכו' מוה\"ר סעדי'<br>\nשי' שד\"ר</p>\n<p>שלום וברכה!</p>\n<p>בטח קיבל מכ' הכללי וכן הקונטרס לי\"ט כסלו שנשלח ע\"י הלשכה.</p>\n<p>ובמענה על שאלתו שמפני לימודו עם התלמידים אי אפשר לו להתפלל במתינות ושואל חוו\"ד אם ראוי לעזוב הלימוד,</p>\n<p>הנה לפ\"ד אם אפשר לו לשנות לימודו, שיהי' עם כתה כזו שיוכל להתפלל במתינות, כדאי לעשות כזה, אבל בכ\"א צריך הוא להמשיך הלימוד עם התלמידים, אשר זהו הקישור באילנא דחייא כפשוטו ממש. וכיון שזכה לזה אין לו לחשוב ע\"ד חיפוש איזה ענין אחר.</p>\n<p>בברכת הצלחה בעבודתו בקודש,</p>\n<p><b>מ. שניאורסאהן</b></p><p>בטח עוה\"פ ישתדל ע\"ד השגת ויזא למרוקו.</p>\n<h4><i><b>ז'תתצז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 86, מצילום האגרת.</p>\n<p><b>מוה\"ר סעדי':</b> ליברוב. אגרות נוספות אליו - לעיל חי\"ט ז'רכג, ובהנסמן בהערות שם.</p>\n<p>לקמן ז'תתקלז. ז'תתקנז. ז'תתקסג.</p>\n<p><b>השגת ויזא למרוקו:</b> ראה לקמן שם, ובהנסמן בהערות שם.</p>"],[1200950143,"ז'תתצח\n\n<p>ב\"ה, א' טבת, תשי\"ב</p><p>ברוקלין.</p><p>האברך מר אברהם יצחק שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו לחג החגים י\"ט כסלו ובו מבקש ברכה.</p>\n<p>והנה ידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר בברכה נאמר לשון גשמי ברכה, וכמו שגשם מועיל רק אם יורד הוא על שדה חרושה וזרועה, כך הוא גם בענין הברכה, שצ\"ל מצד מקבל הברכה חרישה וזריעה, אלא שאח\"ז הנה גם בזריעה הקטנה לפ\"ע, ממשכת הברכה הצלחה גדולה ומופלגה.</p>\n<p>ובנוגע לבני תורה ותלמידי הישיבות הנה החרישה היא שמירת סדרי הלימוד בדיוק בהישיבה, אף שלפעמים גורם זה מיעוט בשינה או באכילה ושתי', והעיקר היפך הרצון לעצלות ואי התמדה ואי שקידה. וזריעה היינו לימוד בשקידה והתמדה המתאימה. וכשישנה הכנה זו, אזי ממשכת הברכה הצלחה בהשכלה והבנה והשגה.</p>\n<p>כשאהי' על ציון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ, זי\"ע אזכירו להצלחה בתלמוד תורה ביראת שמים, ובודאי הוא מצדו יעשה כהנ\"ל.</p>\n<p>בטח אומר הוא תהלים בכל יום כפי שנחלק לימי החודש, וגם לומד בכל יום הפרשה מסדרת השבוע עם פרש\"י.</p>\n<p>בברכה לתלמוד תורה ביראת שמים בהצלחה ובהתמדה.</p>\n<p>* * *</p>\n<p>מה שמאריך בתפלה ועי\"ז חסר בלימוד כסדר הישיבה - הרי ימלא זה ובתוס' בשעות שאחרי הסדר.</p>\n<p>בנוגע לבריאותו - ישמור הוראות הרופא, ויסיח דעת ממח' במצב הבריאות.</p>\n<h4><i><b>ז'תתצח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 87.</p>\n<p><b>אברהם יצחק שי':</b> שם טוב. אגרות נוספות אליו - לעיל ד'תתצה, ובהנסמן בהערות שם.</p>\n<p>טופס נוסף למו,ה שלום דובער שי' גורקאוו, ובסופו נוסף בכתי\"ק \"מה שמאריך בתפלה...</p>\n<p>\" אגורת נוספות אליו - לקמן ח'כח.</p>\n<p><b>פתגם:</b> ראה גם לעילחי\"ד אגרת ה'רנב, ובהנסמן בהערות שם.</p>"],[1200950144,"ז'תתצט\n\n<p><i>[תחלת טבת תשי\"ב]</i></p>\n<p>במענה להזמנתם ובקשתם בטח תשימו מגמתכם למילוי התפקידים הקדושים של כל הנוער בארה\"ק ת\"ו להתמסר בכל נפשם לחנוך בני ובנות ישראל בתורה ויר\"ש בהתגברות על כל מניעות ועיכובים השי\"ת יצליחכם.</p>\n<h4><i><b>ז'תתצט</b></i></h4>\n<p>נדפסה ב\"דגלנו\" גליון ו(מח), שבט תשי\"ב. והיא אל היובל הי\"ג של צא\"י.</p>"],[1200950145,"ז'תתק\n\n<p>ב\"ה, ד' טבת, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"מ עוסק בצ\"צ באמונה<br>\nוכ'ו מוה\"ר<br>\nמנחם שמואל דוד שי' הלוי שד\"ר</p>\n<p>שלום וברכה!</p>\n<p>מוסג\"פ מכתבי המענה על הפ\"נ ששלח, ובטח במקומות הזקוקים לתוספת הסברה, הרי ימצא האותיות המתאימות, והוי' יהי' עם פיהו להצליח בזה.</p>\n<p>הזכרתיו על הציון בער\"ח טבת.</p>\n<p>אחכה לבשו\"ט ע\"ד התועדו[יו]ת די\"ט כסלו שנערכו. ועיין חוברת י\"ט כסלו ע' ד' הערה ג'.</p>\n<p>בברכת הצלחה בעבודתו בקדש ותומשך גם בעניניו הפרטים בגו\"ר,</p>\n<p><b>מ. שניאוסאהן</b></p>\n<p>נ.ב. בטח שומר בריאותו כדבעי, וע\"פ מה שנדברנו בהיותו כאן, ונא להודיעני גם עד\"ז <b>ובלי משוא פנים.</b></p>\n<p>רצונו להיות כאן ביו\"ד שבט, אם יהי' בהסכמת זוג' תי', נכון הוא.</p>\n<h4><i><b>ז'תתק</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 57.</p>\n<p>מוה\"ר מנחם שמואל דוד שי': רייטשיק. ארות נוספות אליו - לעיל חי\"א ג'תקעה, ובהנסמן בהערות שם. לקמן ז'תתקל. ז'תתקצ.</p>\n<p><b>ועיין חוברת... ג':</b> שם הועתקה האגרת שנדפסה באג\"ק אדמור, מהוריי:\"צ נ\"ע ח\"ה אגרת א'שמח.</p>"],[1200950146,"ז'תתקא\n\n<p>ב\"ה, ט' טבת, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר רפאל<br>\nנחמן שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי מכתביו מנר ב' דחנוכה ונר ז' דחנוכה, בו מודיע אשר שכר דירה בקירוב למקום דירת בנותיו שיחיו ומול הישיבה, ויה\"ר שיהי' בהצלחה וידורו בדירתם במנוחה, מנוחת הנפש ומנוחת הגוף, ויתעסק בעבודתו עבודת הקדש כדבעי, מבלי בלבולים מענינים צדדיים, ובבריאות הנכונה שלו ושל זוגתו וכל ב\"ב שיחיו.</p>\n<p>ת\"ח ת\"ח על תשורתו היקרה, והיא הפתקא של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וכן על כתבו פרשת הדברים בסדר השתל' של הפתקא, וכן על צרפו ג\"כ קטעים ממכתבי כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ב) בנוגע ל... הנה טבח לא ייעף ולא ייגע מלדבר עמהם עוד הפעם ועוה\"פ. והעיקר שיהיו דברים שבנחת, ויקויים יעוד הכתוב דברי חכמים (כשהם) בנחת נשמעים, ויה\"ר שיבשר בשו\"ט בכל הנ\"ל, כמו שמבשר במכתבו בשו\"ט מאופן התועדות חג החגים י\"ט כסלו, ובהתאם לזה מוסג\"פ, העתק מכתבי הכללי בענין זה.</p>\n<p>מה שמקטין בענין הנחת התפלין שהי' רק ג\"פ - יעוין תניא פכ\"ה שלמע' הוא <b>נצחי, לעולם ועד.</b></p>\n<p>החותם בברכת מזל טוב לכניסתו של נכדו שניאור זלמן שי' לבריתו של אאע\"ה, ויזכו אביו ואמו וכן אבותיו זקניו שיחיו לראות ממנו ומשאר יו\"ח שיחיו אידישן נחת חסידישן נחת בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקא</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>הרה\"ח... הכהן:</b> אגרות נוספות אליו - לעיל ז'תתעח, ובהנסמן בהערות שם.</p>\n<p><b>הפתקה... פרשת הדברים:</b> ראה שמועות וסיפורים ח,א ע' קצ.</p>"],[1200950147,"ז'תתקב\n\n<p>ב\"ה, ט\"ו שבט תשי\"ב</p><p>ברוקלין.</p>\n<p>ברכה ושלום!</p>\n<p>איך האב ערהאלטען אייער פדיון נפש דורך הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר יעקב יהודא שי' העכט, אין וועלכן ער שרייבט מיר אויך דאס וואס איר האט עם דערציילט פון אייער פארגאנגענהייט... און אויך שרייבען א ספר תורה אין אייער נאמען, און שיקען די ספר תורה אין ארץ ישראל, און פרעגט מיין מיינונג אין דעם.</p>\n<p>זיכער איז איבעריג צו אונטערשטרייכן די הייליקייט און גרויסקייט פון א ספר תורה, אבער עס איז פראן דאס וואס איז נאך מער הייליקער ווי א ספר תורה, און דאס זיינען די אידען וועלכע לערנען די תורה, און גראדע אין ארץ ישראל בא דם יעצטיגען מאמענט, וואס עס זיינען אנגעקומען טויזענטער אידישע קינדער וועלכע נויטיגען זיך אין א תורה ומצות ערציהונג, אז זיי זאלען וויסען וואס אידישקייט איז, שמירת שבת כשר א.א.וו. ליידער זיינען די צאל עקזיסטירענדע ישיבות און חדרים צו קליין אויף צו ארייננעמען די אלע אנגעקומענע אידישע קינדער. און טאג טעגליך קומען אן פון דארטן הארץ רייסענדע בריף וועגען דעם. וואס מיט א קליינע סומע בערך וואלט מען געקענט ראטעווען טויזענטער אידישע קינדער וועלכע זאלען ניט אפגעריסען ווערן ח\"ו פון אידישן פאלק, און זאלן אויף שטענדיג בלייבן תורה טרייע אידען.</p>\n<p>און דאס זעלבע איז אויך אין צפון אפריקא, וואס מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ, זי\"ע האט א קורצע צייט פאר זיין הסתלקות באפעהלט צו איינארדנען דארטן חדרים און שיבות צו לערנען די דארטיקע אידישע קינדער תורה ויראת שמים, און עס איז נויטיג געלט מיטלען אויף דעם.</p>\n<p>איז מיין עצה דעריבער, וויבאלד קיין ספרי תורה פעלט ניט יעצט אין ארץ ישראל (זיי זיינען געבראכט געווארן פון יוראפישע לענדער), דאגעגען געלט אויף אויצוהאלטען מלמדים, און צו קויפען סידורים חומשים או ענליכעס ספרים, איז זייער נויטיג סיי אין ארץ ישראל און סיי אין צפון אפריקה, און דערפאר איז מיין מיינונג, אז וויבאלד איר האט דעם גוטען ווילען צו שרייבען א ספר תורה, אבער האט נאך <b>ניט</b> באשלאסן און פרעגט מיין מיינונג, זאלט איר זיך נאכפרעגען וויפיל וואלט קאסטען אט אזא ספר תורה צו שרייבען. און דעם סכום מיט א צוגאב פון איין דאללאר אוועקגעבען פאר גרינדען נאך א חדר אדער א תלמוד תורה אין ארץ ישראל און אין צפון אפריקה און אויך שיקען צו זיי סידורים, און אויף די סידורים ועט אנגעפרינטעט ווערען אז די וואס וועלען יוזען די סידורים זאלען מתפלל זיין און דערמאנען צום גוטען די מנדבים - אייך און אייער מאן שיחיו.</p>\n<p>די גרויסקייט פון דעם זכות וואס איר וועט האבען דורך דעם איז שווער איבערצוגעבען אין ווערטער און בפרט אין א בריף, אבער איך האף אז איר וועט באגרייפען פון מיין שרייבען די וויכטיגקייט פון דעם, און השי\"ת זאל אייך העלפען איר זאלט פארריכטען אינגאנצען אייער פארגאנגענהייט און פון היינט אן און ווייטער זאל זיין בא אייך א גוטער אידישער לעבען על פי התורה והמצוה.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקב</b></i></h4>\n<p>מהעתק המזכירות.</p>"],[1200950148,"ז'תתקג\n\n<p>ב\"ה, א' אדר, תשי\"ב</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו מכ\"ב שבט, ובהשגחה פרטית הנה נתקבל בער\"ח אדר איזה שעות לפני נסעי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, וקראתי מכ' על הציון הק' ובטח יעורר כ\"ק מו\"ח אדמו\"ר ר\"ר עליו על הענינים שמזכיר במכתבו אודותם, וצדיק גוזר והקב\"ה מקיים ובפרט צדיקא דאתפטר דאיתא ע\"ז בזהר דאשתכח בכולהו עלמין יתיר מבחיוהי, וביחוד כיון שכ' זכה לקבל ברכה מכ\"ק מו\"ח אדמו\"ר.</p>\n<p>מובן ופשוט אשר לקבלת והחזקת ברכות השי\"ת הנותן ברכתו בחפץ ומידו המלאה והרחבה, צריך האדם לעשות כלים רחבים מתאימים לזה, אשר לכן בטח גם כבודו יעשה כזה, היינו שיקיים אחרי הוראות כ\"ק מו\"ח אדמו\"ר - אם קיבל הוראות כאלו, וכן ישתדל בקיום השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר והם א) שיעור תהלים (כפי שנחלק לימי החדש) בכל יום אחרי תפלת שחרית, ב) לימוד פרשה חומש עם פירוש רש\"י מהסדרה של השבוע, ג) שיעור תניא כפי שנחלק לימי השנה.</p>\n<p>וכיון שמתעסק הוא בעניני בנין, ובעניניא דיומא נודע מרז\"ל (סוף תענית) משנכנס אדר מרבין בשמחה, ויעוין שם בסוגיא המדובר בבנינים של שמחה, ויה\"ר אשר ג\"כ בניניו ימשיכו שמחה במעונו בגשמיות וברוחניות.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקג</b></i></h4>\n<p>מהעתק המזכירות.</p>"],[1200950149,"ז'תתקד\n\n<p>ב\"ה, ו' אדר ה'תשי\"ב</p><p>גאזאול;63636#&amp;י דמסןהטם . כ;63637#&amp;עעאףח שי'</p>\n<p>;63635#&amp; ןמכףקטכ ארו ןטס;63637#&amp;למ מע םגאנ . ;63630#&amp;;63636#&amp;כ מקום;63637#&amp; המגמכום ןנמקוסע;63637#&amp; ג םול.</p>\n<p>קעמ ;63636#&amp; ףסענמטכטס;63637#&amp; ג אפנט - ;63625#&amp;אבאה. ט ףגונום. קעמ ;63636#&amp; בףהועו המגמכ;63637#&amp;ם;63636#&amp; מבסעאםמגךמי ט ;8206#&amp;עמ ןנטםוסוע אל ףהאקף. ךאך ג למנאכ;63637#&amp;םמל עאך ט ג לאעונטאכ;63637#&amp;םמל מעםמרוםטט.</p>\n<p>מסמבוםםמקעט. גסןמלטםא ארודמ מעצא. ךמעמנמדמ ץמנמרמ חםאכ.</p>\n<p>ףגונום ג עמל. קעמ בףהףקט ג מבקעאםמגךו פאנ-;63625#&amp;אבאה. ;8206#&amp;עמ בףהוע סממעגעסגמגאע;63637#&amp; ודמ זוכאםט;8207#&amp; ט עאךזו ךאקוסעגאל ארודמ ץאנאךנעונא.</p>\n<p>ךמעמנ;63636#&amp;י ;63636#&amp; םאגונםמ ףםאסכוהמגאכט מע םודמ.</p>\n<p>;63636#&amp; לםו גסודהא למזועו ןטסאע;63637#&amp; ט םא עאךמל ח;63636#&amp;ךו םא ךמעמנמל אל ףהמבםוו.</p>\n<p>עאך ךאך ח;63636#&amp;ך םו מסמבוםםמ ;63636#&amp;אזום. טבמ דכא;63636#&amp;םמו חםאקוםטו חעמ קמהונזאםטו ןטס;63637#&amp;לא. א םו ודמ ;63636#&amp;םורם מבמכמקךא.</p>\n<p>;63635#&amp; םאהו;8207#&amp;ס;63637#&amp;. קעמ ג סכוהף;8207#&amp;שול ןטס;63637#&amp;לו ;63636#&amp; לםו ןמהנמבםוי םאןטרטעו מעומסטעוכ;63637#&amp;םמ נאסןמנ הךא ארודמ הם . ךאך ג מעםמרוםטט נאבמע;63636#&amp;. עאך ט ג מעםמרוטט ףקוב;63636#&amp;.</p>\n<p>וכא;8207#&amp; אל ץמנמרודמ ףסענמיסעגא - לאעונטאכ;63637#&amp;םמ ט למנאכ;63637#&amp;םמ - ט ףהאקט ג ;8206#&amp;עמל.</p>\n<p><b>. ;63628#&amp;םוונסמם</b></p>\n<p>[תרגום חפשי]</p>\n<p>מר ז. אלטהויז הנכבד שי'</p>\n<p>מכתבך מה-27 בינואר נתקבל. מאד שמחתי לקרא בו כי הסתדרת ב,ספריא חב\"ד, ובטוחני שתהיה מרוצה והדבר יביא לך הצלחה הן ברוחניות והן בגשמיות.</p>\n<p>בטוחני - במיוחד כשאני נזכר באביך ע\"ה שהכרתיו היטב - שמצבך כיום, שהנך גר בכפר-חב\"ד, מתאים לכוונתו ולרצונו של אביך וגם לתכונות הנפש שירשת ממנו.</p>\n<p>הנך יכול לכתוב לי תמיד בשפה הניחה לך יותר, כי החשיבות היא לא בשפה שבה כותבים אלא בתוכנו של המכתב - כי השפה הינה העטיפה החיצונית בלבד.</p>\n<p>אני מקוה שבמכתב הבא שלך תכתוב לי בפרטיות יתר אודות סדר יומך, הן באשר לעבודתך והן בקשר לשיעורי-תורה ולימוד.</p>\n<p>המאחל לך הסתדרות טובה בגשמיות ורוחניות והצלחה בהם.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקד</b></i></h4>\n<p>צילום האגרת ותרגומה נדפסו ב\"כפר חב\"ד\" גליון 566 (ג ניסן ה'תשנ\"ג).</p>\n<p><b>מר ז. אלטהויז:</b> מו,ה זעליג ב\"ר מנשה. אגרות נוספות אליו - לקמן ח'יט. ח'ריז.</p>"],[1200950150,"ז'תתקה\n\n<p>ב\"ה, ב' ניסן, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר [שלמה<br>\nחיים] שי'</p>\n<p>שלום וברכה!</p>\n<p>א) קבלתי הפ\"נ שלו, וכשהייתי בער\"ח ניסן על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע קראתיו, ובטח יעורר ר\"ר על כל הנזכרים בכתבו זה בהמצטרך להם.</p>\n<p>ב) בטח קבל כבר הקונטרס לב' ניסן ע\"י הרה\"ח הוו\"ח אי\"א נו\"נ וכו'... ביחד עם הפ\"ש וכו', ואחכה לבשו\"ט ממנו בכל הענינים.</p>\n<p>ג) מוסג\"פ העתק מכתבי כללי לחגה\"פ הבע\"ל אשר בטח יפרסמו באופן המתאים.</p>\n<p>ד) אחרון אחרון עיקר בקשתי כפולה ומשולשת, אשר כהד\"ג שי' יסדר עניניו הכללים והפרטים באופן כזה שיוכל לנסוע לישיבת תורת אמת בירושלים ת\"ו אחת לשבוע או לשבועיים כדי לדבר וללמוד דא\"ח באופן המתאים עם האברכים והבחורים ולבחנם מזמן לזמן וכן להתועד אתם - כמובן לא בכל עת בואו לשם, אלא אחת לחודש לערך.</p>\n<p>כתבתי עד\"ז ג\"כ לישיבת תורת אמת, ותקותי חזקה שיסכימו ע\"ז.</p>\n<p>ואל בינת כת\"ר אשען שיסדר הדבר באופן כזה שלא יגרום נפילת רוח דמשפיע דא\"ח דתו\"א או לנמיכות הפרעסטיזש דהנ\"ל בעיני האברכים והבחורים כו' וכו'. בטח יוכל להסביר, אשר כיון שהוא פנים חדשות, הרי לפעמים תכופות חידושא איידי דחביבא פועל יותר כו' וכו'.</p>\n<p>דברתי עד\"ז עם הרה\"ח וכו'... שי' בהיותו כאן, ועל כת\"ר והרה\"ח... הנני סומך שיסדרו הדברים באופן כזה שלא תהי' מניעה בזה ג\"כ מהנהלת ישיבת לוד.</p>\n<p>וכל הנ\"ל מתאים ג\"כ להצעתי זה מכבר, אשר לאחר שגמרו התלמידים (אם באפשר לומר גמר בלימוד התורה), שאיפתם צריכה להיות בנוגע ללימוד דא\"ח, לשגשג בלימוד זה ע\"י הכנסתם להישיבה דלוד, ולכן בתור הכנה לזה יהי' ג\"כ בקורו של כת\"ר מפרק לפרק בישיבת תורת אמת.</p>\n<p>ואחכה לבשו\"ט מסידור ענין זה, והעיקר שיהי' בדרך השלום ובאופן דשבת אחים גם יחד.</p>\n<p>בברכת הצלחה בהשפעת רוח דיראת שמים בזמן דמיכלא ד[מ]הימנותא ומיכלא דאסוותא לכל המושפעים שלו.</p>\n<h4><i><b>ז'תתקה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 90.</p>\n<p><b>מוה\"ר שלמה חיים:</b> קסלמן. אגרות נוספות אליו - לעיל ז'תתטז, ובהנסמן בהערות שם.</p>"],[1200950151,"ז'תתקו\n\n<p>ב\"ה, ד' חוה\"מ פסח, תשי\"ב</p><p>ברוקלין.</p><p>הנהלת אגודת חב\"ד באה\"ק ת\"ו</p>\n<p>שלום וברכה!</p>\n<p>בטח ידוע להם ומכירים את ידידנו הכי נעלה הוו\"ח אי\"א נו\"נ מו\"מ באמונה ותומך מוסדותינו הק' משנים קדמוניות עד היום, מוה\"ר יעקב שי' כהן כ\"ץ משיקאגא, והיות אביו של הנ\"ל נמצא כעת באה\"ק ת\"ו, וצריך לדירה לדור בה, הנני מבקשם להשתדל למצוא עבורו דירה מתאימה בהקדם, ויתדברו עמדו, אולי יש לו כבר מראה מקום לדירה, במקום שלבו חפץ, וכמדומה שהוא בבני ברק, ובמשך הזמן בודאי ישלם אביו ההוצאות הכרוכות בזה, לאט לאט, ועד שישלם סכום הוצאה שתעלה השגת הדירה, הנה הצעתי אשר יקחו את הדירה ע\"ש אגודת חסידי חב\"ד באה\"ק ת\"ו.</p>\n<p>אקווה שלא ימשיכו את ההשתדלות בהשגת הדירה עבורו, כי לפי הידיעות נמצא הנ\"ל בתנאים אי נוחים, ות\"ח על טרחתם בזה, ואחכה לידיעה טובה מהם מה שפעלו לטובה בענין זה בהקדם האפשרי.</p>\n<p>בברכת הצלחה בעבודתם בקודש וחג פסח כשר ושמח.</p>\n<p>מפני קדושת המועד לא בא כ\"ק אדמו\"ר שליט\"א בעצמו על החתום, והנני חותם בשמו,</p>\n<p>א. קווינט</p>\n<p>מזכיר</p>\n<h4><i><b>ז'תתקו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 114, מצילום האגרת.</p>\n<p><b>אביו... לדירה:</b> ראה לקמן אגרת ז'תתקיב.</p>"],[1200950152,"ז'תתקז\n\n<p>ב\"ה, ד' חוהמ\"פ, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר אליעזר שי'</p>\n<p>שלום וברכה!</p>\n<p>מצו\"פ מכתבי להנהלת אגו\"ח באה\"ק ת\"ו, ובקשה אשר כת\"ר שי' מצדו יזרז את הענין להביאו לפועל טוב, ות\"ח על ההודעה בזה בהקדם, אשר הענין נגמר בכי טוב, והוא בהמשך למה ששוחח עמדו הרמ\"ג שי'.</p>\n<p>בברכת החג.</p>\n<p>מפני קדושת המועד לא בא כ\"ק אדמו\"ר שליט\"א על החתום, והנני חותם בשמו,</p>\n<p>המזכיר</p>\n<p>א. קווינט</p>\n<h4><i><b>ז'תתקז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 115, מצילום האגרת.</p>\n<p><b>מוה\"ר אליעזר:</b> קרסיק. אגרות נוספות אליו - לעיל ז'תשפה, ובהנסמן בהערות שם.</p>\n<p><b>הרמ\"ג:</b> ה\"ר משה גורארי'.</p>"],[1200950153,"ז'תתקח\n\n<p>ב\"ה, כ\"ז ניסן, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר שמואל<br>\nשי' שו\"ב</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו, אשר מפני כמה סיבות נתאחרה התשובה עד עתה:</p>\n<p>א) מתאר מצבו בענין השחיטה שבזמן האחרון הולך ופוחת ועובד עתה בתור נסיון כמזכיר באגו\"ח בתל אביב, ושואל חוו\"ד אם לקבל העבודה או לחכות עד שיזדמן לפניו דבר יותר קל,</p>\n<p>הנה לדעתי אין כדאי לחכות, כי חבל על הזמן ההולך בהעדר עבודה ופעולה, ואם מצאו אנ\"ש שמתאים הוא לעבודה הנ\"ל הרי אדרבה צ\"ל בזה, כמו שהורו אותנו רז\"ל בענינים כמו אלו: חטוף ואכול חטוף ושתה, ז\"א אדרבה לעבוד בזה בזריזות ולמלאות חלקו בארגון אנ\"ש, שסוכ\"[ס] הנה נפוצים עי\"ז המעיינות חוצה, אשר בטח ישמש זה ג\"כ כלי להגדלת והמשכת הצלחה בעניניו הפרטים.</p>\n<p>ב) כותב ע\"ד בנו יחיאל יהודא שי' שסידרו אותו ברבנות הצבאית ושואל חוו\"ד, אם כדאי שיתענין בענין נכבדות.</p>\n<p>הנה נכון הדבר במאד. ויה\"ר שיהי' בהצלחה. ובטח משתמש הוא בהשפעתו על בנו שי' להגדיל את אור דנר ה' נשמת אדם הנמצא בתוכו, ובפרט שעי\"ז יוכל ג\"כ לראות פירות בהמושפעים שלו בתוך הצבא, אשר שם נחוצה ביותר וביותר ההשפעה דיר\"ש במרץ גדול ובדברים היוצאים מן הלב, וכמ\"ש והי' מחנך קדוש וכדמובא מענין דאשת יפ\"ת וכו'.</p>\n<p>ומטובו לפרוש בשלום בנו יחיאל יהודא שי' ולמסור לו ברכתי, אשר יזכהו השי\"ת להשתמש בהכחת הצפונים בו, מורשת אבות דגזע אנ\"ש, להביאם אל הפועל ולהשפיע על כל סביבתו בנר מצוה ותורה אור ומאור שבתורה זוהי תורת החסידות.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקח</b></i></h4>\n<p>צילום האגרת ב\"זכרון שמואל\" ע'78.</p>\n<p><b>מוה\"ר שמואל:</b> זלמנוב. אגרות נוספות אליו - לעיל ז'תתע, ובהנסמן בהערות שם.</p>\n<p>1) סוטה יא, ב (ע\"פ גירסת ילקוט שמעוני תהלים רמז תשצה).</p>\n<p>2) בפה ובתופים - וראה לקוטי תורה ברכה צח, ג.</p>\n<p>3) זהר ח\"ב ט, א.</p>\n<p>4) שם בתחלת העמוד.</p>"],[1200950154,"ז'תתקט\n\n<p><i>[ב' אייר תש\"ב]</i></p>\n<p>ב\"ה,</p><p>אמרו רבותינו ז\"ל: 1בזכות נשים צדקניות שהיו באותו הדור (של יציאת מצרים) נגאלו ישראל מצרים. ומבארים ומספרים בארוכה, איך אשר למרות עול הגלות, קושי השעבוד והגזירות הקימו עדרים עדרים של בני ובנות ישראל, הקימו דור אשר הכריז בשמחה בשירה 8ובזמרה: זה א-לי ואנוהו אלקי אביו ארוממנהו.</p>\n<p>הבטיחנו הקב\"ה: כימי צאתך מארץ מצרים אראנו נפלאות, בגאולה העתידה לבוא במהרה בימינו על ידי משיח צדקנו, \"כל 3אתין ונסין וגבוראן דעבד קוב\"ה במצרים יעביד לון לישראל\" \"4ובזכות ינוקי דבי רב יתתקף חילי לאתגברא\", של מלך המשיח.</p>\n<p>וכאז כן עתה, תלוי זה בנשי ישראל, וכמבואר בהשיחה, אשר בידן הוא גורל הבנים והבנות.</p>\n<p>תפקידן חובתן וזכותן של נשי ישראל הוא, אשר מבלי חת מחושך הגלות, קושי השעבוד והגזירות אשר רוצים לשקעות, הי' לא תהי', את נפש בנינו ובנותינו בבנינים זרים לרוח ישראל סבא, מנגדים לאמונת הוי' אחד, הנותן, לשון הוה, תורה אחת לישראל גוי אחד בארץ,</p>\n<p>הנה יעשו את ביתן <b>בית קדושה</b> לשמו ית', ויבססו את חינוך בניהן ובנותיהן על יסודי התורה והמצוה.</p>\n<p>ואז \"3אימא 5עילאה יתערת.. ומלכא משיחא <b>שארי</b> ויכנוש גלותא מסיפי עלמא עד סייפי עלמא\".</p>\n<p><b>מנחם שניאורסאהן</b></p><p>תפארת שבתפארת, ה'תשי\"ב. ברוקלין, נ.י.</p>\n<h4><i><b>ז'תתקט</b></i></h4>\n<p>נדפסה כהקדמה לקונ' שיחת כ\"ק אדמו\"ר מוהריי\"צ נ\"ע (לקבוצת נשי ישראל בעת ביקורו בעיר ריגא יב-כ אדר תרצ\"ד), שנדפסה באייר תשי\"ב. והיא השיחה הנזכרת לקמן.</p>\n<p>5) ראה פרי עץ חיים שער חהמ\"צ פ\"ו בד\"ה מהר\"י ז\"ל.</p>"],[1200950155,"ז'תתקי\n\n<p>ב\"ה, ג' אייר, תשי\"ב</p><p>ברוקלין.</p><p>הנהלת ועד כפר חב\"ד,<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבם מכ\"ה ניסן שמחתי לקרות בו אשר עלתה בידם ההשתדלות לפעול שישארו במקומם עתה ובמילא יהיו כולם ביחד, ובטח אף שאין כותבים עד\"ז בפירוש, שיה'י להם כל הזכיות שהבטיחו להם בעת שהתיישבו בכפר חב\"ד.</p>\n<p>ב) כבר באה העת להשתדל להרבות מספר המתיישבים בהכפר מבין שאר אנ\"ש והקרובים לאנ\"ש ברוח, הנמצאים באה\"ק ת\"ו, ובפרט מהצעירים הנשואים, וגם מבני הנוער אשר מפני סיבות אינם שייכים ללמוד כל היום בישיבת תומכי תמימים, אבל אפשר לחייב אותם ולזכותם בלימוד איזה שעות ובחיים של סביבה חסידותית חבדי\"ת כל היום כולו לרבות הלילה, ובקשר עם הדוחק בדירות השורר באה\"ק ת\"ו יש לקוות שהברירה תהי' בידם לבחור עידית מבין אלו שירצו להתיישב בהכפר...</p>\n<p>ה)... אם ברצוננו או שלא ברצוננו הנה אנחנו ממלאים מקומם של חסידי חב\"ד בדורות שלפנינו ולפני פנינו עד הדור דיעה של חסידי כ\"ק רבינו הזקן מיסד תורת חב\"ד ודור אחר דור סללו בשבילנו את הדרך ולא נשאר לנו אלא להשלים ה\"פכים קטנים\".</p>\n<p>ומאידך גיסא הנה עלינו ועל דורנו מוטלת החובה לסיים את הבירורים דעקבתא דמשיחא ולהמשיך גילוי המשיח למטה מעשרה טפחים בעוה\"ז הגשמי.</p>\n<p>ואפילו בהתבוננות שעה קלה בענינים אלו הרי צריך לאחוז חיל ורעדה אשר כל ענינים הנוראים האמורים בדברי רז\"ל בענינים דמשיח והגילוים שאז ובפרט כפי המבואר בדא\"ח הנה כ\"ז תלוי בעבודתינו אנו..</p>\n<p>בברכת הצלחה בעבודתם בקדש ויזכם השי\"ת זיי זאלן דערפילען לא רק בהנפה\"א כ\"א גם בשכל האנושי אשר זיכם השי\"ת להיות מהמסייעים בעבודתם של כ\"ק מו\"ח אדמו\"ר בבנין היכל חב\"ד באה\"ק ת\"ו.</p>\n<p>המחכה לבשו\"ט ומשמחות.</p>\n<h4><i><b>ז'תתקי</b></i></h4>\n<p>נדפסה בקונ' צדי\"ק למלך\" א ע' 57.</p>\n<p><b>שישארו במקומם:</b> ראה בזה לעיל ח\"ו אגרת א'תקסו, ובהנסמן בהערות שם.</p>"],[1200950156,"ז'תתקיא\n\n<p>ב\"ה, י\"א אייר, ה'תשי\"ב</p><p>ברוקלין, נ.י.</p><p>הנהלת הישיבת בלוד<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>זה עתה קבלתי ידיעה אשר חלוקת ה -100,000 (f או $) נעשית באופן כזה:...</p>\n<p>נבהלתי לידיעה הנ\"ל, אשר לא די מה שלכתחילה הקציבו סכום מצער של 5000 הנה עוד הפחיתו ממנו עד כדי 4000!.</p>\n<p>יש אומרים שהטענה היא כי מספר ילדי תימן קטן הוא בלוד. ושלשה ענינים בזה:</p>\n<p>הא' - הנני נבהל ונשתומם אשר למרות שדפקתי על לבם זה כמה פעמים לקלוט יותר ויותר מילדי תימן, כנראה הי' זה קול במדבר.</p>\n<p>הב' - איני יודע גודל הקליטה מבני תימן במוסדות האחרים שהקציבו להם סכומים גדולים שלא בערך.</p>\n<p>הג' - והוא העיקר, הסכומים הנ\"ל הוקצבו לא רק בעד הילדים אשר כבר ישנם במוסדות, אלא בעיקר לאפשר קליטתם להבא. במילא הנה הטענה לכתחילה שלא במקומה.</p>\n<p>ולמעשה בטח ינקטו תיכף בכל האמצעים הדרושים לתקן הדבר ויעשו זה במרץ המתאים ובלי בטלנות ורשלנות...</p>\n<p>המחכה לבשורות טובות</p>\n<h4><i><b>ז'תתקיא</b></i></h4>\n<p>מהעתקה.</p>\n<p><b>עד כדי 4000:</b> ראה לקמן אגרת ז'תתקטו.</p>"],[1200950157,"ז'תתקיב\n\n<p>ב\"ה, כ' אייר תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר אליעזר שי'</p>\n<p>שלום וברכה!</p>\n<p>בת\"ח קבלתי מכתביו מי\"ג וט\"ו אייר, ובנוגע להזרם הבלתי זרמי, הנה מסרתי בע\"פ ע\"י גיסו הרה\"ח וכו' הרמ\"ג שי'</p>\n<p>... נהניתי לקרות במכ' אשר הזקן ר' זלמן שי' כ\"ץ כבר נכנס לדירתו, והשי\"ת יזכהו לבשר טובות תכה\"י.</p>\n<p>שלחתי לכת\"ר שי' היום, מברק ע\"ד ההלוי', ואחכה למכתב מפורט מהנעשה בזה, והשי\"ת יעזור לנו, אז מיר זאלן אויסניצן אחד את חברו אויף גוטע פרייליכע זאכן תכה\"י.</p>\n<p>בהיותי אתמול על הציון של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, הזכרתי אותו ואת זוגתו שיחיו לבריאות הנכונה ולכל טוב בגו\"ר, ואחכה ממנו לבשו\"ט בזה. וכן מהנעשה עם חתנו הרה\"ח מוה\"ר נתן שי' שהנני דואג במקצת, שאחר המכתב שכתב לי זה איזה שבועות, לא הגיעני כל ידיעה ממנו. ויה\"ר שיהי' הכל טוב בטוב הנראה ונגלה.</p>\n<p>בברכה לבריאות הנכונה לו ולזוג' שיחיו המחכה לבשו\"ט.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקיב</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר אליעזר:</b> קריסק. אגרות נוספות אליו - לעיל ז'תשפה, ובהנסמן בהערות שם.</p>\n<p><b>הזקן... לדירתו:</b> ראה לעיל אגרת ז'תתקו.</p>\n<p><b>הלוי':</b> של מוה' ישראל ארי' ליב - אחי כ\"ק אדמו\"ר, שליט\"א. ראה לעיל ח\"ו בנסמן בשוה\"ג לאגרת א'תקסו.</p>"],[1200950158,"ז'תתקיג\n\n<p>ב\"ה, כ\"ד אייר תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר אברהם שי'</p>\n<p>שלום וברכה!</p>\n<p>מכתביו בעתם מתקבלים ות\"ח על כתבו עד עתה ובקשה על להבא להמשיך בזה, ולא [ל]קצר במקום שצריך ונחוץ להאריך, והמענה שזהו אפשר... הנה בענינים כמו אלו הטענה היא פון דעם קלוגינקען וכפתגם כ\"ק אדמו\"ר נ\"ע שיכול הוא להתלבש גם ב, זיידענע קאפאטא', ואחכה למכתביו המפורטים בכל הענינים וכל המאריך בזה ה\"ז משובח.</p>\n<p>... ולקראת חג השבועות הבע\"ל הנני בזה לברכו ואת כל ב\"ב שיחיו וכנוסח כ\"ק מו\"ח אדמו\"ר לקבלת התורה בשמחה ובפנימיות.</p>\n<p>ויה\"ר.. מען זאל ניט פארנאכלעסיגען די מעגליכקייטן שניתנו עתה לחסידים באה\"ק ת\"ו, ולהפיץ המעיינות, בהצלחה מופלגה.</p>\n<p>והשי\"ת יזכנו לגאולה האמיתית והשלימה ע\"י משיח צדקנו.</p>\n<p>בברכת החג.</p>\n<h4><i><b>ז'תתקיג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 58.</p>\n<p><b>מוה\"ר אברהם:</b> פריז. אגרות נוספות אליו - לעיל ז'תתנד, ובהנסמן בהערות שם.</p>"],[1200950159,"ז'תתקיד\n\n<p>ב\"ה, ג' סיון, תשי\"ב</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר שמחה מאיר שי'</p>\n<p>שלום וברכה!</p>\n<p>עס האט מיך געפרייט צו ערהאלטען אייער בריף פון מוש\"ק בה\"ב, אין וועלכען איר שרייבט אז דורך הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר מאיר שי' בליזינסקי, האט איר זיך באקאנט מיט חסידות חב\"ד, און האט אנגעהויבן צו לערנען תורת החסידות, און בעט צו פאררעכנען אייך צום קהל חסידי חב\"ד:</p>\n<p>עס האט מיר געפרייט דאס אלעס אויבען געזאגטע, און אויף דעם שטייט געשריבן אין די ספרים הקדושים, אז א איד וויל זיך פירן אין גוטען וועג אוף א אמת, העלפט עם השי\"ת, ובפרט א ענין וועלכער איז פארבונדן מיט תורה וואס אויף דעם איז געזאגט געווארען יגעתי ומצאתי תאמין, און בפרט תורת החסידות, וואס אין אונזערע יעצטיקע צייטען פון דעם גלות כפול ומכופל זיינען זייער נויטיק ענינים וועלכע בריינגען צו אהבת השם ויראת ה' און צו עבדו את ה ' בשמחה, וואס די אלע זיינען די יסודות פון תורת החסידות.</p>\n<p>איך האף אז לויט די אנווייזונג פון רז\"ל וואס זיי האבען געזאגט אז מעלין בקדש כו' וכל המוסיף מוסיפין לו, וועט איר אויך מוסיף זיין אין די שיעורים פון תורה בכלל און בתורת החסידות בפרט, און וועט זעהן אויך צו באטייליגען זיך אין די חסידישע צוזאמענקונפטן סיי א צוזאמענקונפט פון לערנען און סיי א פארבריינגען פון חסידים וועלכע זאל פארשטארקן אהבת ישראל אהבת התורה ואהבת השי\"ת, וואס דאס אלעס וועט אייך געבען א צוגאב חיות אין תורה עבודה וגמילות חסדים,</p>\n<p>זיכער ווייסט איר וועגן די דריי שיעורים וועלכע מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע האט מתקן געווען פאר אלע אידען, וואס דאס איז די שיעורים פון חומש תהילים ותניא אלע טאג, און האלט זיי אן.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות.</p>\n<h4><i><b>ז'תתקיד</b></i></h4>\n<p>מצילום האגרת.</p>\n<p>מוה\"ר שמחה מאיר: וויינמן, רמת גן.</p>"],[1200950160,"ז'תתקטו\n\n<p>ב\"ה, ג' סיון, תשי\"ב</p><p>ברוקלין.</p><p>הנהלת ישיבת תומכי תמימים בלוד,<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>נתקבל מכתבם מכ\"א אייר. ואף שלדעתי אפשר הי' להכנס בדו\"ד עם מר קול בנוגע לתמיכה הפעוטה שניתנה להם, וגם זה בתור הלואה, בסכום של ד' אלפים לא\"י, אבל כנראה שעתה אין נפ\"מ כי כבר נחלק הסכום, אבל עכ\"פ בנוגע להבא בטח יעמדו על המשמר להודע בעוד מועד בנוגע להם ולתמיכתם, כדי שאפשר יהי' לקדם פני' ולקבל מהם תמיכה המתאימה.</p>\n<p>ב) בהתאם לזה הנה עוד הפעם באתי בהערה להזדרז בענין הבי\"ס למלאכה ככל האפשרי, וחבל שאין אצלי ידיעות נוספות בזה, כי הד\"ר שפירא, שכנראה דעתו תהי' מכרעת בענין זה, נמצא עתה בארצה\"ב ובעוד כשבוע או שבועיים יחזור לצרפת, ובמשך היותו כאן, אפשר הי' להשפיע עליו, אם הי' לי ידיעות נוספות בזה.</p>\n<p>ג) שמחתי במאד למה שמודיעים במקצת עכ\"פ בענין הנסיעה למירון בל\"ג בעומר, ובטח ימלאו הנוסעים - במכתבים מפורטים.</p>\n<p>בברכה לקבלת התורה בשמחה ובפנימיות ולהצלחה בעבודתם בקודש, להגדיל תורה ולהאדירה, וכדרישת כ\"ק רבוה\"ק זצוקללה\"ה נבג\"מ זי\"ע לחבר תורה דלמע' בהקב\"ה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקטו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ג ע' ^</p>\n<p>45, מצילום האגרת.</p>\n<p><b>לתמיכה... ד' אלפים:</b> כדלעיל אגרת ז'תתקיא.</p>\n<p><b>הד\"ר שפירא:</b> ראה גם לעיל ח\"ו אגרות א'תרחצ. א'תתמ.</p>"],[1200950161,"ז'תתקטז\n\n<p>ב\"ה, ט\"ז [סיון], תשי\"ב</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר מאיר שי'</p>\n<p>שלום וברכה!</p>\n<p>... בטח משתדל הוא להשפיע גם על סביבתו לקרבם לדרכי החסידות ומנהגי', וידוע מה שסיפר כ\"ק מו\"ח אדמו\"ר מאמר רבינו הזקן בגודל הנח\"ר למעלה כשמשתדלים בטובת רעהו,וא\"כ הוא כשמשתדלים בטובת רעהו בגשמיות, הרי עאכו\"כ כשמשתדלים בטובת רעהו ברוחניות, שעי\"ז מביאו לחיי העוה\"ז והעוה\"ב, כי באיש הישראלי הרי מקושרים הם זה בזה ומאוחדים זה בזה עד שנעשו כדבר אחד.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקטז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 116.</p>\n<p><b>שסיפר:</b> ראה אג\"ק אדמו\"ר מוהריי\"צ נ\"ע ח\"ג אגרת תשפד.</p>"],[1200950162,"ז'תתקיז\n\n<p>ב\"ה, ט\"ז סיון תשי\"ב</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו' מוהר\"ר<br>\nאברהם שי'</p>\n<p>שלום וברכה!</p>\n<p>עס פרייט מיך צו הערן פון צייט צו צייט גערוסן פון אייך, און פון אייער ארבעט פאר די ענינים פון תורה ומצות בכלל און פאר דער ישיבה תומכי תמימים אין מאנטרעאל בפרט, און עס איז באוואוסט דער אויסשפראך פון מיין שווער כ\"ק מו\"ח אדמו\"ר אין נאמען פון זיין פאטער \"אז הקב\"ה בלייבט ניט קיין בע\"ח\", און די וועלכע זיינען זיך משתדל און גיבען אריין אין אידישע קינדער - וואס אלע אידן זיינען השי\"ת בן יחיד - חיות בגשמיות וברוחניות, דורך דעם וואס מען גיט זיי די מעגליכקייטן צו לערנען תורת השי\"ת, גיט זיי השי\"ת א צוגאב חיות, גאר בפשטות אין גוטן געזונט און הצלחה אין זייערע ענינים, די כללות'דיקע און פרטית'דיקע, און עס ווערט מקויים בא זיי, דאס וואס רבנו הזקן האט געזאגט, ווי מיר האבן פילע מאל געהערט פון כ\"ק מו\"ח אדמ\"ר, אז השי\"ת גיט אידן גשמיות און זיי מאכן פון גשמיות רוחניות.</p>\n<p>השי\"ת זאל אייך העלפן מיט אריכות ימים ושנים טובות, גוטע אין אלע אופנים, און זאלט קענען פארזעצן אייער ארבעט, און נאך אין א גרעסערע מאס, פאר דער ישיבה תומכי תמימים אין מאנטרעאל בפרט ולהרמת קרן ישראל בכלל.</p>\n<p>בברכה,</p>\n<h4><i><b>ז'תתקיז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 117.</p>\n<p><b>אויסשפראך:</b> ראה גם לעיל אגרת ז'תתפב, ובהנסמן בהערות שם.</p>"],[1200950163,"ז'תתקיח\n\n<p>ב\"ה, י\"ט סיון תשי\"ב</p><p>ברוקלין.</p><p>הנהלת....<br>\nד' עליהםיחיו</p>\n<p>שלום וברכה!</p>\n<p>... מאחרי ההסתלקות נראה בעלל איך שכל הענינים המתנהלים ברוחו, מצליחים הם בדרך למעלה מן הטבע......</p>\n<p>אכפול את דבריי, שאין כוונתי כלל לפעול נפילת ונמיכת הרוח, ורק שעכ\"פ מכאן ולהבא יהי' מוח שליט על הלב אפילו על התרגשות והתפעלות דקדושה, ויעויין ג\"כ במאמר של הצ\"צ הנדפס לחנוכה תשי\"א בההקדמה שם.</p>\n<p>ואחכ לבשו\"ט מאתם, שנתיישבו האורות בכלים, אף שכלפי חוץ אין צ\"ל ניכר זה, כי בימינו אלה ובפרט במקומות שם הם נמצאים, הרי צריך להראות אורות רבים כדי לבקע את החושך כפול ומכופל.</p>\n<p>ואקוה למכתבם מבשר טוב אשר מתנהלת העבודה בסדר מסודר, ובפרטיות ע\"ד התפתחות המוסדות.</p>\n<p>בברכת הצלחה בעבודתם בקודש.</p>\n<h4><i><b>ז'תתקיח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 117.</p>\n<p><b>במאמר... בההקדמה שם:</b> ד\"ה ברוך שעשה נסים, קה\"ת תשי\"א. נדפסה גם באוה\"ת בראשית כרך ה תתקנז, ב. ההקדמה - שם ע' תתריד, א-ב.</p>"],[1200950164,"ז'תתקיט\n\n<p>ב\"ה, כ\"ג סיון ה'תשי\"ב</p><p>ברוקלין, נ.י.</p><p>הנהלת אגודת חב\"ד באה\"ק ת\"ו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בקרוב יבוא לאה\"ק ת\"ו הרה\"ג והרה\"ח וו\"ח אי\"א נו\"נ וכו מוה\"ר שלום שי' חסקינד, אשר ברצוני שיבקר בכל המוסדות, מחנות ומעברות וכו'. ושתי כוונות לי בזה: הא) שישתמשו בביקורו לענין הרמת הרוח, כיון שבא מאה\"ב ומדבר אנגלית וכו', וג\"כ להפחדה במקום שצריך להפחדה. אשר במילא כדאי לסדר שיבקרו עמו כל המוסדות המתאימים (ולאו דוקא משלנו) וכן אצל הרבנים הראשיים וכו'. ובטח יעשו ג\"כ פרסום המתאים בעתונים, ומכש\"כ וק\"ו מהקטע המוסג\"פ.</p>\n<p>ב. קבלתי ידיעה שישנה מקוה בחיפה מיסודו של הרמ\"מ קופרשטאק ע\"ה, ונמצאת עתה ברשות יוצאי חלציו שי', אלא שמפני כמה סיבות ישנם קישויים בהשתמשות בה, ותלוי זה בהשפעה על בני הרב הנ\"ל, ואם לאו יש מקום לחשש דחילול שם ליובאוויטש.</p>\n<p>אינני יודע פרטי הדבר, ובטח אין נ\"מ כל כך, כי להם על אתר ודאי ידוע המצב בזה. ואם יש רק אפשרות מהנכון שידברו עם בני הרב ע\"ד הנ\"ל וישתדלו בתיקון הדבר בכל האפשרות.</p>\n<p>ג. הגיעתני בקשה שבונים מקוה ברמת הדר נצח ישראל רמתיים, ואלו שמות המתעסקים בזה [...],וחסר הסיום לגמר בסך של לערך מאתים ל\"י, והמקום מקום מושב יהודים חרדים, אשר בטח ישתמשו בהמקוה כשתוגמר. ואם כל הנ\"ל, אמת הוא, נכון במאד שיתנו להם סך הנ\"ל, כמובן שישתמשו בו באופן היותר מתאים, ובודאי מנחם בהרב מיקטרינוסלב יקח זה על עצמו, אלא שאין כדיא לחכות, ובלבד שיודיעוהו אח\"כ שעשו כנ\"ל.</p>\n<p>ד. קבלתי בקשה מש\"ב ר' אברהם דוד שי' ינובסקי אשר מצב בריאות זוג' שתחי' דורש עפ\"י הוראת הרופאים דירה נוחה יותר, וחסרים להם האמצעים על זה, ונראה לי אשר מנחם הנ\"ל, יקח גם זה על עצמו עד סכום של אלף ל\"י אם הרא\"ד ימצא דירה מתאימה.</p>\n<p>ה. אאשר בזה קבלת מכתביהם מי\"ז אייר והפרטי-כל מהאסיפות ט', כ\"ה, כ\"ז אייר וט' סיון.</p>\n<p>ו. בטח מקבלים הי\"ב אלף ל\"י לבנין מהסוכנות. ואתענין לדעת מה עושים בהם.</p>\n<p>ז. מהו סוף דבר מפעל השביעית?</p>\n<p>ח. הרב גולדמן הציע לייסד בי\"ס בפרוזדור ירות\"ו. מה נעשה בזה?</p>\n<p>בברכת הצלחה בעבה\"ק.</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקיט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 60.</p>\n<p><b>בקרוב... חסקינד:</b> ראה גם לעיל ח\"ו אגרת א'תרנ.</p>\n<p><b>להפחדה:</b> ראה לעיל ח\"ד אגרת תתסה. ח\"ו א'תרצ.</p>\n<p><b>מקוה בחיפה:</b> ראה לעיל ח\"ו אגרת א'תתנ.</p>\n<p><b>מנחם בהרב מיקטירנוסלב:</b> כ\"ק אדמו\"ר שליט\"א.</p>"],[1200950165,"ז'תתקכ\n\n<p>ב\"ה, ז' תמוז, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר מיכאל<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מבדר\"ח תמוז עם רשימת התלמידים המוסג\"ב וכן מכתביו הקודמים ובלי נדר אזכירם בעת רצון על הציון של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ומ\"ש במכתבו על ענין המקואות שנעשו שם ע\"י מי ברזא, וכנראה ממכ', כוונתו כפשוטו, שמשתמשים במים הבאים מ'וואדאפראוואד!!</p>\n<p>הנה מבלי לעשות רעש בזה, יש לשנותם מעט מעט - אם למקוה דמי גשמים, ואם אין גשמים במקומם, אולי אפשר להשיג קרח מלאכותי (איסקוסטוענע), או ע\"י המשכה ממעין.</p>\n<p>הקונטרס לחג הגאולה י\"ב וי\"ג דתמוז הבע\"ל, בטח כבר הגיע לידו, ויסדר את החגיגה בפרסום המתאים, ובהשתתפות גם מבני העיר, וינצל את זה בענינים של פועל, דעשי' לעילא.</p>\n<p>בברכת הצלחה בענינים הכללים ובענינים הפרטיים ובברכת חג הגאולה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקכ</b></i></h4>\n<p>צילום האגרת נדפס ב\"עשרים שנה עבודת הקודש במרוקו\".</p>\n<p><b>מוה\"ר מיכאל:</b> ליפסקר. אגרות נוספות אליו- לעיל ז'תתיד, ובהנסמן בהערות שם.</p>\n<p><b>מ'וואדאפראוואד:</b> מי צינוןר.</p>\n<p>קרח מלאכותי: ראה גם לעיל ח\"ז אגרת ב'סג.</p>"],[1200950166,"ז'תתקכא\n\n<p>י\"ב תמוז, תשי\"ב</p>\n<p>למסור לכל הקיבוצים: התועדות בהתעוררות בימי גאולה וסגולה הבע\"ל ובהשתדלות בהפצת תקנות בעל השמחה.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתקכא</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 70.</p>"],[1200950167,"ז'תתקכב\n\n<p>ב\"ה, כ\"א תמוז תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוהר\"ר רפאל נחמן שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי מכתבו מט\"ז תמוז בבשורה טוב ע\"ד הטבת בריאות חתנו מוה\"ר יצחק שי' ואשר כבר בא לביתו וכן בנוגע לבריאותו הוא, ות\"ח ת\"ח ביחוד בעד הכתיבה, עכ\"פ בקיצור, מהנעשה בימי חג הגאולה והסגולה י\"ב וי\"ג תמוז, ובעד הרשימה שבסוף מכתבו, כן יזכהו השי\"ת בעתיד לבשר אך טוב תכה\"י בענינים הכללים והפרטיים.</p>\n<p>מצערני במקצת, שלא בא במכ' זכרון פעולות צעירי אגו\"ח אשר כנראה לא נצלו ההזדמנות דחגיגה הנ\"ל וחבל על זה.</p>\n<p>לאות הכרת תודה על הקורת רוח שגרם לי, הנה מצוה גוררת מצוה, ומוסג\"פ הרשימה שהו\"ל לימי י\"ב וי\"ג תמוז, והוא לזכות בה את הרבים וזכות הרבים תלוי בו.</p>\n<p>בברכה לבריאות הנכונה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקכב</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>הרה\"ח... הכהן:</b> אגרות נוספות אליו- לעיל ז'תתעח, ובהנסמן בהערות שם.</p>\n<p><b>מוה\"ר יצחק שי':</b> גנזבורג.</p>"],[1200950168,"ז'תתקכג\n\n<p>ב\"ה, ז' אלול, תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוה\"ר נפתלי<br>\nשי' שו\"ב</p>\n<p>שלום וברכה!</p>\n<p>קלתי מכתבו מא' ראה והקודם לו, ואתו הסליחה אשר מפני רוב הטרדה לא אשרתי קבלתם עד עתה....</p>\n<p>נהניתי מההתענינות שלו במצב ענין השו\"ב במחנו, אף שנצטערתי במאד, על המאורעות והענינים שלא כדבעי, שמזכירים במכתב. וכנראה שכוונתו בזה הוא לשו\"ע.</p>\n<p>ובטח ימים אלו תהי' הזדמנות לדבר עם עוד אחדים מאנ\"ש אשר יכולים להתערב בז, ותקותי שיעלה סו\"ס לתקן את המצב לאט לאט. ומובן מעצמו שלא אזכיר שההודעה הראשונה באה מכת\"ר שי'. והשי\"ת יזכהו להצליח בלימוד ובמלאכת הקדש בלי שום מכשול ח\"ו, וידוע ג\"כ הפירוש במרז\"ל אין ושחט אלא ומשך, שהוא, כמו שע\"פ פשוט, ענין השחיטה היא להכשיר את בשר הבהמה, והעוף להעלותם ממדריגת חי' למדריגת מדבר (כיון שנעשה דם ובשר של האדם) הרי יעשה ג\"כ ענין זה ברוחניות, להמשיך ולהעלות את הנפש הבהמית למדריגת אד שהוא מל' אדמה לעליון, וכמ\"ש בשל\"ה דף ז' ע\"ב והוא בס' עשרה מאמרות, מאמר אם כל חי חלק ב' סימן ל\"ג.</p>\n<p>בברכת כתיבה וחימה טובה לו ולכל ב\"ב שי',</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקכג</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר נפתלי:</b> יוניק. אגרות נוספות אליו - לעיל ח\"כ ז'תערב, ובהנסמן בהערות שם.</p>"],[1200950169,"ז'תתקכד\n\n<p>ב\"ה, כ\"ב אלול תשי\"ב</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר ניסן שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתו מט\"ו אלול, לפלא שלא קבל את הר\"ד דש\"ק מברכים ח' אלול, ומוסג\"פ עוד העתקה, וכן קטע משיחת ח\"י אלול בנוגע ביחוד לישיבות...</p>\n<p>לשנה הבע\"ל הנה ילמדו בהישיבה כאן המסכתות יבמות...ואם אפשר בקל - כדאי שגם בישיבת תו\"ת בפריז ילמדו איזה ממסכ' אלו.</p>\n<p>בברכת כתיבה וחתימה טובה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקכד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 118.</p>\n<p><b>מוה\"ר ניסן:</b> נמנוב. אגרות נוספות אליו - לעיל ז'תתט, ובהנסמן בהערות שם.</p>"],[1200950170,"ז'תתקכה\n\n<p>ר\"ה תשי\"ג:</p>\n<p>כתיבה וחתימה טובה. הצעתי להתועד והקהילו האנשים הנשים והטף ללמוד ליראה את השם.</p>\n<p>בברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתקכה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 70.02</p>"],[1200950171,"ז'תתקכו\n\n<p>ב\"ה, ד' מ\"ח, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'</p>\n<p>מוה\"ר ישראל נח שי'</p>\n<p>... בנוגע לתוכן מכתבו, אשר ברצונם לשלוח שד\"ר לטובת הישיבה ללונדון, הנה ימים אלו יהי' כאן הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו' מוהרב\"צ שי' שם טוב שד\"ר, ואדבר עמדו ע\"ד הענין והפרטים בזה למען לסדר את הענין באופן היותר טוב ומועיל, ויקבל עוד ידיעות בזה.</p>\n<p>בברכת הצלחה בעבודתו בקודש ולבריאות הנכונה ואריכות ימים ושנים טובות עם כל הפירושים.</p>\n<p><b>מ. שניאורסאהן</b></p>\n<h4><i><b>ז'תתקכו</b></i></h4>\n<p><b>נדפסה בקונטרס \"צדי\"ק למלך\" ב ע' </b>8 מוה\"ר ישראל נח: בליניצקי. אגרות נוספות אליו - לעיל חט\"ו ה'תתא, ובהסמן בהערות שם. לקמן ז'תתקלב. ז'תתקמו. ח'נב</p>"],[1200950172,"ז'תתקכז\n\n<p>ב\"ה, כ\"ג מ\"ח, תשי\"ג</p><p>ברוקלין.</p><p>מחות' וו\"ח אי\"א נו\"נ וכו' מוה\"ר שניאור<br>\nזלמן שי' הלוי</p>\n<p>שלום וברכה!</p>\n<p>זה עתה נתקבלו שני מכתביו מט\"ו וי\"ט חשון וכותב ע\"ד מחשבותיו השונות בענין הסתדרותו, אם באה\"ק ת\"ו או בקנדה, אשר כמה קישויים ומעלות בזה על זה.</p>\n<p>הנה כנראה ממכתביו, גם בעיניו עדיין אין הענין ברור, בענין היכולת שיש בידו וכן עד ב\"ב שיחיו בדבר העתקה ממקומם עתה לאה\"ק ת\"ו או לקנדה, ולכן דעתי שיושיב שם שלשה אנשים מידידיו מזקני אנ\"ש אשר במקומו עתה, ויציע לפניהם את כל הענין כפי שיהי' ידוע לו ביום ההוא, והשי\"ת יתן להם את הרעיון הנכון איך לייעצו, לטוב לפניו ולפני ב\"ב שיחיו בגשמיות וברוחניות, וכהוראתם יעשה ויהי' להצלחה.</p>\n<p>בברכה להסתדרות בנקל - ומתאימה בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקכז</b></i></h4>\n<p><b>נדפסה בקונ \"צדי\"ק למלך\" א ע' 61, מצילום האגרת.</b> מוה\"ר שניאור זלמן: בוטמן (והוספת הלוי נכתבה להסוואה). אגרות נוספות אליו - לעיל ז'תתיב, ובהנסמן בהערות שם.</p>\n<p>שיושיב שלשה אנשים: ראה גם לעיל חי\"ז אגרת ו'קפח, ובהנסמן בהערות שם. חי\"ח ו'תרמג.</p>"],[1200950173,"ז'תתקכח\n\n<p>ב\"ה, אדר\"ח כסלו, תשי\"ג</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר שמואל זאנוויל<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>איך האב באקומען אייער בריף פון ב' חיי שרה אין וועלכען איר בעט א ברכה צו דעם וואס אייך איז שווער צו איינשלאפען און שרעקט זיך, און איר פרעגט מיי מיינונג אין דעם:</p>\n<p>לויט מיין מיינונג דאפט איר אינגאנצען מסיח דעת זיין פון דעם, און זעהען וואס פריער צו בודק זיין די תפילין, ציצית און אויך די מזוזות אין אייער דירה, צי זיי זיינען כשר'ה ווי דער דין איז, און אויך זאלט איר נעמען אויף זיך בלי נדר- צו אפהיטען די תקנה פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, צו זאגען יעדער טאג נאך דאוונען אין דער פריה א שיעור תהלים - ווי דער תהלים איז פאנאנדערגעטיילט אויף די טעג פון חדש - און יעדער וואכען טאג פארן דאוונען אין דער פריה צו געבען א פראנק אויף צדקה, און אויך זעהען אז עס זאל ניט דורכגיין א טאג אין וועלכען איר זאלט ניט לערנען לכל הפחות אטליכע פסוקים חומש פון דער סדרה פון דער וואך און עפעס א לימוד פון תורה שבעל פה, וועלכעס עס איז אייך געשמאקער, און איך האף אז איר וועט זיך צונויפריידין מיט אנ\"ש דליובאוויטש וועלען זיי אייך געבען א גוטע עצה אין דעם.</p>\n<p>מען מוז קענען אויף אויסוויינינג עפעס פון תורה און לכל הפחות א פאר קאפיטלעך תהלים או משניות, און ועון עס דאכט זיך אייך עפעס א שרעק אדער ניט קיין פרייליכע מחשבה זאלט איר דענסטמאל איבערטראכטען א קאפיטל תהלים אדער א משניות וואס איר ווייסט אויף אויסוויינינג, און זיכער ועוט איר דענסטמאל פילן זיך גוט און וועט מיר אנזאגען גוטע בשורות אין דעם.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמ\"ר שליט\"א,</p>\n<p>מזכיר</p>\n<h4><i><b>ז'תתקכח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א 62.</p>\n<p><b>מוה\"ר שמואל זאנוויל:</b> נוסבאום.</p>"],[1200950174,"ז'תתקכט\n\n<p>י\"ט כסלו תשי\"ג:</p>\n<p>גוט יום טוב. התועדיות בחיות פעילות ושמחות.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתקכט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 70.</p>"],[1200950175,"ז'תתקל\n\n<p>ב\"ה, כ' כסלו, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר מנחם שמואל דוד שי' הלוי שד\"ר</p>\n<p>שלום וברכה!</p>\n<p>נתקבל מכתבו מי\"ב כסלו וכן מכבתו הקודם עם הפ\"נ, אשר קראתים ביום הבהיר, הוא יום חג גאולתינו ופדות נפשנו י\"ט כסלו, על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, ובודאי יעורר ר\"ר על כאו\"א מאלו ששלחו הפ\"נ - להמצטרך להם.</p>\n<p>... ת\"ח ת\"ח על הודעתו אודות בריאות הרה\"ח הוו\"ח אי\"א נו\"נ וכו' מוהרש\"ז שי' בעזפאלאוו, אשר זה זמן רב שלא קבלתי ממנו כל ידיעה, ובמכתו זה הרגיעני במקצת עכ\"פ, כן יזכהו השי\"ת להודיעני טובות תכה\"י.</p>\n<p>בנוגע לחיפוש דירה בשכונה טובה ומתאמת, הרי בטח יעשה בזה במרץ המתאים.</p>\n<p>והשי\"ת יצליחו.</p>\n<p>ובמה שמודיע שביום א' כ\"ו כסלו הבע\"ל, יתמלאו לבנם... שי' שלש שנים, הנה יה\"ר מהשי\"ת שיגדלו ביחד עם זוגתו שיחיו לתורה לחופה ולמעשים טובים מתוך הרחבה ומנוחה בגשמיות וברוחניות. והשי\"ת ימלא הריונה של זוגתו תחי' כשורה ובנקל ותלד זחו\"ק כשורה ובנקל.</p>\n<p>בברכה - המחכה לבשו\"ט.</p>\n<p>מ. שניאורסאהןנ.ב. מנהגים מיוחדים ליום הגזיזה, לא שמעתי. ומועתק פה קטע ממכתב כ\"ק מו\"ח אדמו\"ר בנוגע לזה:</p>\n<p>... ובדבר גזיזת השערות- אפשערענעס - הוא דבר גדול במנהגי ישראל, ועיקרו הוא בהחינוך דהשארת פיאות הראש. ומיום הגזיזה והנחת הפיאות של הראש נהגו להדר להרגיל את התינוק בענין נשיאת ט\"ק וברכות השחר וברכות המזון וק\"ש שעל המטה.</p>\n<p>והשי\"ת יהי' בעזרם שיגדלוהו לתורה לחופה ומעש\"ט מתוך פרנסה בהרחבה ובמנוחת הדעת בגשמיות וברוחניות.</p>\n<h4><i><b>ז'תתקל</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 63.</p>\n<p><b>מוה\"ר מנחם שמואל דוד שי':</b> רייטשי'. אגרות נוספות אליו - לעיל ז'תתק, ובהנסמן בהערות שם.</p>"],[1200950176,"ז'תתקלא\n\n<p>ב\"ה, כ\"ו כסלו, תשי\"ג</p><p>ברוקלין.</p><p>הרב הגאון והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nסדרן ופלפלן<br>\nמוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>... ד) אחרון אחרון חביב, אשר נתקבל ספרו היקר אישים ושיטות, וכן הכרך הרביעי של האנציקלופדי' תלמודית, ות\"ח ת\"ח על תשורתו טובה ויפה זו.</p>\n<p>ה) בטח נודע לו אשר יש כאן קבוצת אנשים ובראשם - הרב טייץ, מאספים שו\"ת הרגצובי, שעדיין לא ראו אור הדפוס, ע\"מ להו\"ל.</p>\n<p>ו) בטח נתקבלו המאמרים וקונט' כ\"ק אדמור, (מוהרש\"ב) נ\"ע, והוא עומד עליהם, בזמנם.</p>\n<p>בכבוד ובברכה להצלחה בעבודתו בקודש, מתוך בריאות הנכונה והרחבת הדעת.</p>\n<p><b>מ. שניאורסאהן</b></p><p><i>ז'תתקלא</i></p>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 119, מצילום האגרת.</p>\n<p><b>מהורש\"י:</b> זוין. אגרות נוספות אליו - לעיל ח\"ג ד'תעו, ובהנסמן בהערות שם. לקמן ז'דתתקמא. ז'תתקנה. ז'תתקנט. ז'תתקסט. ז'תתקפב. ח'יז* ח'רט.</p>\n<p><b>והוא עומד עליהם:</b> תרס\"ג (קה\"ת תשי\"ג) נדפסה אח\"כ בסה\"מ תרס\"ג ע' נ.</p>"],[1200950177,"ז'תתקלב\n\n<p>ב\"ה, כ\"ז כסלו, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nישראל נח שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו מה' וישלח, במה שרוצים לעשות מגבית במדינת אנגליא, הנה כתבתי היום עוה\"פ בזה להרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוהרב\"צ שי' שד\"ר, ויכלו לבוא עמו בקישור מכתבים תיכף.</p>\n<p>בודאי ערכו התועדות בי\"ט כסלו וכן בימי חנוכה באופן המתאים, ובטח לא ימנע הטוב מלהודיעני עד\"ז בפרטיות. וידוע עד כמה השתדל כ\"ק מו\"ח אדמו\"ר לצרף לענינים כמו אלו גם מאנשים הנמצאים לע\"ע בחוצה. וה\"ז ג\"כ בדיוק מענת המשיח: יפוצו מעינותיך חוצה.</p>\n<p>בברכה לבריאות הנכונה, המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקלב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' ^</p>\n<p>0.</p>\n<p><b>מוה\"ר ישראל נחף</b> בלינצקי. אגרות נוספות עליו - לעיל ז'תתקכו, ובהנסמן בהערות שם (וראה שם לתוכן האגרת שלפנינו).</p>\n<p><b>מוהרב\"צ:</b> שם טוב.</p>"],[1200950178,"ז'תתקלג\n\n<p>ב\"ה, כ\"ז כסלו, תשי\"ג</p><p>ברוקלין.</p><p>... יהי רצון מהשי\"ת שתגדלהו היא ובעלה שיחיו לתורה לחופה ולמעשים טובים מתוך הרחבה.</p>\n<p>ואל יהי הדבר רחוק בעיניו או בעיני', וכמ\"ש לא נפלאת היא ולא רחוק גו' כי קרוב אליך הדבר מאד בפיך ובלבבך לעשותו אלא שצריך להיות פתיחה עכ\"פ כחודה של מחט.</p>\n<p>ועליו לעורר את אחותו וגיסו שיחיו מזמן לזמן וסו\"ס הנה אבנים שחקו מים.</p>\n<p>בברכת מזל טוב על הנ\"ל, והשי\"ת יזכהו לבשר טובה תכה\"י.</p>\n<h4><i><b>ז'תתקלג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 93.</p>"],[1200950179,"ז'תתקלד\n\n<p>ב\"ה, כ\"ח כסלו, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר רפאל שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>ת\"ח ת\"ח על תשורתו רשימות זכרונות מקיץ עזר\"ת. ובטח אם יזכור עוד פרטים, מהאסיפה הנ\"ל בכלל ובנוגע לאבי אאמו\"ר זצ\"ל בפרט, בודאי ימלא במכתביו הבאים, וכן ימשיך ברשימת זכרונות גם מזמנים אחרים, ות\"ח מראש.</p>\n<p>מסרו לי, אשר דואג הוא על אי קבלת מכתבים מבנו שי', אבל תקותי שמכאן ולהבא יסודר זה,</p>\n<p>בודאי כמנהגו הטוב יודיע בפרטיות ע\"ד התועדיות דחדש כסלו הוא חדש הגאולה - כן מאלו אשר נוכח בעצמו, וגם במקומות אלו הידועם לו מפי אלו שהשתתפו שם.</p>\n<p>אצטער ואדאג במאד, להעדר הסתדרות המתאימה בהישיבה דתל אביב, למרות השקו\"ט והחליפות מכתבים שהיו מהכא להתם ומהתם להכא. ואיני יודע באיזה אמצעים לאחוז בכדי שמוסד כ\"ק מו\"ח אדמו\"ר יהי' מתאים לרצונו, היינו שכל המשתתפים בו והם - ההנלה, הר\"מ והר\"י, התלמידים - יבינו שהם שלוחים מהמייסד, להאיר חלקם בעולם ע\"י מוסד זה. והאריכות אך למותר.</p>\n<p>בברכה לבריאת הנכונה ולרוב נחת חסידותי מכל יו\"ח - ביחד עם זוגתו שיחיו.</p>\n<p><b>מ. שניאורסאהן</b></p><p>עתה נתקבלו מכ' מט\"ז וכ' כסלו, עם הפ\"נ, שאקראם על הציון הק'. - ת\"ח על רשימתו, בקיצור עכ\"פ, ע\"ד יט\"כ. - כדאי לחפש בניחותא, אחרי משרה קלה יותר בשבילו.</p>\n<h4><i><b>ז'תתקלד</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר... הכהן:</b> אגרות נוספות אליו - לעיל ז'תתעח, ובהנסמןב הערות שם.</p>\n<p><b>מהאסיפה הנ\"ל:</b> אודותה באג\"ק אדמו\"ר מוהרש\"ב נ\"ע ח\"ב אגרת תצא, ובהנסמן בהערות שם.</p>\n<p><b>בנו:</b> הרב יואל שי'.</p>"],[1200950180,"ז'תתקלה\n\n<p>ב\"ה, נר חמישי דחנוכה, ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>אל כל עדת ישורון חובבי ומחזיקי תורה<br>\nומצוה, אשר<br>\nבכל אתר ואתר,<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>\"מרכז הישיבות תומכי תמימים-ליובאוויטש\", אשר עבודתו והתפתחותו בארצות הברית התחילה על ידי כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ובפקודתו - תיכף להתישבותו באמריקה בשנת ה'ש\"ת, הנה</p>\n<p>ת\"ל, ובזכות הוד כ\"ק אבותינו נשיאנו הק' זצוקללה\"ה נבג\"מ זי\"ע, עשה פרי בהצלחה אלקית מופלגה, וכהיום הרי הרבה מאות תלמידים - כן ירבו - מישיבות אלו מכהנים פאר בתור רבנים, ראשי מתיבתות וראשי ישיבות, שובי\"ם ושאר משרות קודש בקהלות חשובות בישראל. גם אלו מהתלמידים ומחונכי ישיבות תומכי-תמימים המתפרנסים באופן אחר - הנה על משמרתם במשמרת הקודש הם עומדים, לעבוד, כל אחד לפי מעמדו, ומצבו, בשדה הרבצת תורה ויראת שמים ולקחת חלק בראש בהעסקנות של חיזוק היהדות בכל מושבותיהם.</p>\n<p>יחד הם הגדלת והפרחת המוסד גדלו ג\"כ ההוצאות הכרוכות בכלכלתו לכל סעיפיו, עד כי בעת האחרונה נתרבו החובות ועלו למעלה ראש ומזעזעים את קיומו של המוסד ומכבידים במאד את הנהלתו והתפתחותו</p>\n<p>עזרה ממשית נחוצה בהקדם האפשרי.</p>\n<p>והנני פונה בזה לכל חובבי ומוקירי תורה ומצוה בבקשה ודרישה כפולה וכופלת לבוא לעזרת מרכז הישיבות תומכי תמימים - ליובאוויטש, ולתרום תרומת הקדש בלב נדיב וביד פתוחה, ולהשפיע גם על ידידיהם ומכיריהם בכיוון זה, בכדי להקל, על כל פנים במדה ידועה, את עול החובות ולתת את האפשריות לנהל עבודת המוסד להבא, בעזה\"י.</p>\n<p>ומובטחים אנו מחז\"ל אשר גדולה זכות החזקת לומדי תורת חיים, דברי אלקים חיים, מקור חיים - להגן על כל העושים והמעשים ושיתברכו בכל מילי דמיטב, בבני חיי ומזוני רוויחי.</p>\n<p>באיחול ובברכה אשר בעגלא דידן נזכה כולנו לראות בהרמת קרן התורה וקרן ישראל סבא ומלאה הארץ דעה את הוי'.</p>\n<p>הדו\"ש בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקלה</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950181,"ז'תתקלו\n\n<p>ב\"ה, ה' טבת, תשי\"ג</p><p>ברוקלין.</p><p>למרנן ורבנן הרבנים הגאונים יושבי על מדין<br>\nאיש איש<br>\nבמחנו וקהלתו. עסקני הצבור בהרמת קרן<br>\nהתורה והיהדות<br>\nברוח ישראל סבא. וכלל אחב\"י חובבי תורה<br>\nומצוה, די בכל אתר ואתר,<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>בזה הנני ממלא את ידו של הרה\"ג והרה\"ח הוו\"ח אי\"א נו\"מ עוסק בצרכי צבור באמונה ונאמן בית וכו' מוהר\"ר אלי' שי' סימפסאן, אשר יבקר את מושבות אחב\"י יחיו, למסור להם פרישת ודרישת שלום בשמי ולהביא מהם פ\"ש, להודע על מצב היהדות ומעמד מוסדות התורה והחינוך במחנם הט', ולעורר על דבר הדורש תיקון וחיזוק מתאים לרוח ישראל סבא, וכן לבאר מצב מוסדותינו במדינה זו, בארצנו הקדושה ת\"ו, באירופא ואפריקא.</p>\n<p>ונשען על הכתוב אני ישנה ולבי ער, ועל פי דרז\"ל אשר אף בגלותא לב ישראל ער הוא לכל דבר טוב, ואין טוב אלא תורה מצות ומעשים טובים, הנה בודאי יסייעו בידו למלאות דבר השליחות פועל, וכן בהנוגע לחיזוק מוסדותינו במקומות הנ\"ל.</p>\n<p>והשי\"ת יזכה את כל אחד מאתנו כולנו, למלאות תפקידו בעלמא דין על ידי שיאיר את סביבתו וחלקו בעולם באור ומאור אהבת השם אהבת התורה ואהבת ישראל.</p>\n<p>בכבוד ובברכת טוב גשמי ורוחני,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקלו</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950182,"ז'תתקלז\n\n<p>ב\"ה, ט\"ו טבת, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר סעדי' שי' שד\"ר</p>\n<p>שלום וברכה!</p>\n<p>בעתו קבלתי מכתבו עם הרשימות. ובטח כבר קבל הקבלות מהמשרד. ועתה קבלתי הודעתו שכבר נמצאת הוויזה אצלו - למרוקה.</p>\n<p>ובמענה על שאלתו באופן הנסיעה והפרטים אשר בזה, הנה יתדבר עם הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ וכו' מוהרב\"א שי' גאראדעצקי. ואם יש אפשריות לתקן בבקורו במדריד דרך נסיעתו בהנוגע להכשרות של הסטודענטין שם, אז אפשר כדאי שיסע דרך שם, אבל אם ענין זה אינו נוגע למעשה, הרי יכול לנסוע אם באוירון, בהסכם דעת הרופא שיבקר מצב בריאותו, או באני'.</p>\n<p>בנוגע להמקום בו יסדר עבודתו וכן תנאי עבודתו, הרי ידוע עד כמה דייקו נשיאינו בכלל וכ\"ק מו\"ח אדמו\"ר בפרט בענין הסדר בכל דבר ודבר. ולכן יתדבר בפאריז עם הרה\"ג והרה\"ח כו' הרבא\"ג שי' העומד בקישור הן עם ב\"כ הדזוינט והן עם אנ\"ש שי' הנמצאים כבר על אתר, לסדר את כל הדברים באופן היותר מועיל להעבודה שהוא במילא ג\"כ באופן היותר טוב בשביל כאו\"א מהעובדים. והשי\"ת יזכה את כאו\"א מאתנו למלאות תפקידו מתוך הרווחה והרחבה אמיתית.</p>\n<p>בברכת הצלחה בעבודתו בקדש - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקלז</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר סעדי':</b> ליברוב. אגרות נוספות אליו - לעיל ז'תתצז, ובהנסמןב הערות שם.</p>\n<p><b>הויזה אצלו - למרוקה:</b> ראה לעיל ח\"ד אגרות תתעד. תתקב. א'קס. ח\"ה א'תיח. ח\"ו א'תתב. לעיל ז'תתצז. לקמן ז'תתקנז. ז'תתקסג. וכך לאחר השתדלות של שנתיים הצליח לקבל רשיון כניסה לשליחותו במרוקו.</p>\n<p><b>במדריד... להכשרות:</b> ראה גם לעיל ח\"ז אגרות א' תתקעב. ב'קיג.</p>"],[1200950183,"ז'תתקלח\n\n<p>ב\"ה, י\"ז טבת, תשי\"ג</p><p>ברוקלן.<br>\nהנהלת צעירי אגו\"ח באה\"ק ת\"ו<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>זה עתה נתקבל מכתבם עם דו\"ח קצר עכ\"פ מהפעולות דחודש כסלו, ות\"ח ע\"ז.</p>\n<p>ובטח משתדלים ג\"כ שהמחרישה והזריעה שלהם תהי' אח\"כ קצירה ורושם קיים גם לאחר זמן, אשר בודאי זה דורש שימת לב גם אחר חודש כסלו וקישור, אם במכתבים או בראי' פא\"פ מזמן לזמן בכל מקום ומושב לפי ענינו.</p>\n<p>ב) נתקבל המברק אודות הצעתם להדפיס ולהפיץ רשימת המאסר שנדפסה בתמוז, ליום ההילולא דיו\"ד שבט הבע\"ל. והנה בכלל יש להתבונן בזה כיון שזהו רק חלק מהרשימה. ובכ\"ז אם לאחר ההתבוננות יחליטו להדפיסה ולהפיצה, הרי כיון שחלק חשוב מאלו שתבוא אליהם הם מהתימנים והספרדים יש לצרף העתק המלים שבאו בהרשימה באידיש או ברוסית...</p>\n<p>ה) הבטחון, לע\"ע צ\"ל ע\"ד הקובץ ולא ע\"ד \"התמים\".</p>\n<p>ו) בודאי מכאן ולהבא יכתבו לעתים קרובות יותר, והשי\"ת יזכם, אז עס זאל זיין אודות מה לכתוב און וועגען לעבעדיקע פרייליכע זאכען.</p>\n<p>מוג\"פ הקונ' שהו\"ל.</p>\n<p>בברכת הצלחה בעבודתם בקודש.</p>\n<h4><i><b>ז'תתקלח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 65.</p>\n<p><b>שמהחרישה... קצירה:</b> ראה גם לקמן אגרות ז'תתקפ. ח'קעט. ח'קצו.</p>\n<p><b>הבטאון:</b> חב\"ד.</p>\n<p><b>הקובץ:</b> ליובאוויטש.</p>"],[1200950184,"ז'תתקלט\n\n<p>ב\"ה, י\"ח טבת, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר שלום שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתביו מיו\"ד וי\"ג טבת:</p>\n<p>א) ת\"ח על הבשו\"ט מהטבת בריאות מר ישראל שי' הענקין ותקותי שלעת קבלת מכתבי זה מצבו עוד השתפר, ויודיע בשו\"ט בזה. כן אם יודע חוו\"ד הרופאים ואופני הרפואה - בטח יודיע.</p>\n<p>ב) במ\"ש ע\"ד הסברא להשתדל להגדיל איכות ישיבת א\"ת בפיטסבורג בכדי שיתאים גם בשביל התלמידים פייגינסאן וגארבער שיחיו שבאו עתה מצרפת. הנה כמדומה, שבין הת' דעתה והת' שבאו מצרפת עדיין חסרים איזה כתות בינתים, ולכן קשה הדבר שיהי' בהמשך אחד. ובעיקר איני רואה שיוכל למצוא משפיעים בחסידות וראשי ישיבה המתאימים להתלמידים דצרפת, ובפרט שאינם אלא אחדים. אם יש אצלו תקוה (א אויסקוק) שאפשר להשיג משפיעים ור\"י ע\"ד הנ\"ל, עכ\"פ במשך הזמן, אולי כדאי הי' להתענין אם דבר אפשרי הוא מצד ההוצאות שבדבר והן מצד האישים, ואז לא מופרך הדבר שלשנה הבע\"ל יהי' מקום לחשוב עד\"ז, כיון שלזמן ההוא הרי גם תגדל הכתה המסיימת שבהישיבה עתה, אבל להתחיל בזה באמצע הזמן, לכאורה, אין כדאי.</p>\n<p>ג) אתענין לדעת בפרטיות, עד כמה שידוע לו, מצבם הגשמי דמר..</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקלט</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר שלום שי':</b> פויזנר. אגרות נוספות אליו - לעיל ז'תשסז, ובהנסמן בהערות שם.</p>\n<p><b>להגדיל איכות הישיבה:</b> ראה גם לקמן אגרת ז'תתקעג.</p>\n<p><b>א\"ת:</b> אחי תמימים.</p>\n<p><b>בשנים בשבט:</b> בשנים בשבט יום טוב (מגלת תענית פרק יא).</p>\n<p><b>דורך מנהג:</b> ראהפסחים קיט, א ובחדא\"ג שם. הראב\"ע ומצו\"ד לתהלים קיח, כו. מדרש תהלים שם.</p>\n<p><b>ברוך:</b> ראשי תיבות: ראש ומקור כל ברכות (ת\"ז ת\"ע קך, ב).</p>"],[1200950185,"ז'תתקמ\n\n<p>ב\"ה, בשנים בשבט, ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>צו אלע פארזאמלטע און אנטיילנעמער אין דער דרייצנטער<br>\nיערלעכער ארצות-הברית-חגיגה פון מרכז הישיבות תומכי-<br>\nתמימים ליובאוויטש,<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>איך באגריס הערצלעך אלע פארזאמלטע און אנטיילנעמער אין דער היינטיקער יערלעכער חגיגה פון מרכז הישיבות תומכי-תמימים ליובאוויטש, און ווענדע מיך צו יעדערן פון זיי מיט דעם דורך-מנהג-ישראל-תורה-הוא-געהייליקטן ברכה-אויסדרוק:</p>\n<p><b>ברוך הבא בשם ה'!</b></p>\n<p>אמעריקאנער אידן דארפן אפגעבן א שבח והודי' צום אויבערשטן וואס זיי האבן זוכה געווען, אז הוד כ\"ק מו\"ח אדמו\"ר, זצוקללה\"ה\"ה נבג\"מ זי\"ע האט בא זיין אנקומען אהער מיט דרייצן יאר צוריק גלייך פארפלאנצט דעם אייגנארטיקן ג-טלעכן וויינגארטן, כרם ה' צבאות, די ישיבות תומכי-תמימים ליובאוויטש אויך אויפן אמעריקאנער באדן.</p>\n<p>בא היינטיקן טאג, אונטערציענדיק א סך-הכל פון די דרייצען יאר אונערמידלעכער מסירות-נפש'דיקער ארבעט פון די ישיבות תומכי-תמימים דא אין לאנד, זיינען איבערצייגט, די אלע וועלכע זעען און שאצן אפ זאכן לויט זייער ריטיקן אמת'ן אינהאלט און ווערט, אין דער גרויסער ג-טלעכער ברכה וואס די ישיבות תומכי-תמימים ליובאוויטש, מיט זייערע פילע הונדערטער תלמידים יראים ושלמים מסורים ונתונים לה' ולתורתו הק', האבן איריינגעבראכט אין דעם אידישן לעבן באמעריקא. דער מוסטער פון מסירות-נפש פון די תלמידים ומחונכים און זייער טיפגרייכנדער איינפלוס אויפן אידישן געזעלשאפטלעכן און אויך פרטיות'דיקן לעבן איז אן איבעראל אנערקענטער פאקט.</p>\n<p>מיר אלע זעען באשיינפערלעך, ווי פאר אונזערע אויגן ווערט פארווירקלעכט, מיט יעדן טאג אלץ מער און מער, די גרויסע הייליקע אויפגאבע וואס הוד כ\"ק מו\"חא אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע האט זיך געשטעלט בא זיין אנקומען אין אמעריקע, און האט וועגן דעם מערערע מאל מודיע געווען בא פרשידענע געלעגנהייטן; דאס איז:</p>\n<p><b>מאכן אמעריקע פאר א מקום תורה ביראת שמים!</b></p>\n<p>און די ישיבות תומכי-תמימים ליובאוויטש האבן א גרויסן און חשובן חלק אין דער אויספירונג און דערנעענטערונג צו דער מטרה.</p>\n<p>און דעריבער, אין דער צייט ווען דער מרכז הישיבות תומכי-תמימים ליובאוויטש, לעבט איבער א העכסט ערנסטן פינאנציעלן קריזיס, וואס שטעלט אין געפאר די שוין עקזיסטירנדע מוסדות און, זעלבסטפארשטענדלעך, באשווערט די אומבאדינגט נויטיקע אויסברייטערונגען און פארגרעסערונג פון דער צאל ישיבות,</p>\n<p>מוזן אמעריקאנער אידן, און בפרט די אלע פארזאמלטע, דורכגעדרונגען ווערן מיט דעם באוואוסטזיין, אז דאס איז זייער חוב קדוש צו מאכן די גרעסטע אנשטרענגונגען אויף צו געבן דעם מאקסימום הילף צו די ישיבות תומכי-תמימים ליובאוויטש, בכדי צו דעקן זייער גרויסן דעפיציט און געבן די מעגלעכקייט ווייטער אנצוגיין מיט דער ארבעט פון הרבצת תורה ביראת שמים, און מאכן אמעריקא פאר א מקום תורה ויראת שמים.</p>\n<p>איך האף, אז די אלע פארזאמלטע, און יעדערער פון זיי, וועט באם היינטיקן צוזאמענקונפט זיך אנשטרענגען צו באשטייערן אליין די מאקסימאלע סומע, און אויך מיטהעלפן אז עס זאל גלייך געשאפן ווערן דער נויטיקער סכום וואס די הנהלת מרכז הישיבות תומכי-תמימים ליובאוויטש ערווארט.</p>\n<p>און דער זכות פון צדקה בכלל, און בפרט צדקה וואס איז פארבונדן מיט חינוך הכשר, שטארקונג פון אידישקייט, תורה ויראת שמים,</p>\n<p>וועט ממשיך זיין און ברעגען צו די אנטיילנעמער, הם ביתם ובני ביתם שיחיו, ברכה והצלחה בהמצטרך להם - בבני, חיי ומזוני רויחי.</p>\n<p>בכבוד ובברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתקמ</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950186,"ז'תתקמא\n\n<p>ב\"ה, ג' שבט ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הרב הגאון הרה\"ח וו\"ח אי\"א נו\"נ חו\"ב<br>\nעוסק בצרכי<br>\nציבור וכו' מוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>תוהה אני במקצת אשר זה זמן ארוך שלא קבלתי כל ידיעות מכת\"ר שי', והנני תולה זה בטרדתו בתורה ובעניני ציבור, ובפרט אשר ראיתי בעתונות שבקרוב יופיע כרך ה' של האנציקלופדי'. והשי\"ת יצליחו בהנ\"ל, ויצליחו ג\"כ בזמן - שיוכל להוציא הכל לפועל טוב...</p>\n<p>ימים אלה הוצאנו לאור המאמר אין הקב\"ה בא בטרוניא ומוסג\"פ.</p>\n<p>בכבוד ובברכת הצלחה ובריאות הנכונה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>ראיתי שגם בס' אישים ע' פב עמד עדמש\"כ בקונ' הנ\"ל ע' ז' בהערה.</p>\n<p><i>ז'תתקמא</i></p>\n<p>מצילום האגרת.</p>\n<p><b>מהורש\"י:</b> זוין. אגרות נוספות עליו - לעיל ז'תתקלא, ובהנסמןב הערות שם.</p>\n<p><b>בקונ' הנ\"ל ע' ז':</b> סה\"מ קונטרסים ח\"ג ע' קכב, וסה\"מ תרפ\"ה ע' רס, בהערה ד\"ה אינו כן.</p>"],[1200950187,"ז'תתקמב\n\n<p>ב\"ה, ו' שבט, תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>זה לא כבר מסר לי הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו' מוהרחמ\"א שי' חדקוב ע\"ד שאלתו בענין הטעסטען. וידוע מאמר ששמענו כ\"פ מכ\"ק מו\"ח אדמו\"ר ווי מען פרעגט אזוי ענטפערט מען.</p>\n<p>אף שבאמת נפלא הדבר שאחרי שראו נפלאות השי\"ת וגם בעיני בשר, הנה מפעם לפעם נופלים אצלם סברות חדשות אפשר לעשות טעסטען, ואולי למסור את בתם תחי' לעוד רופא שיתלמד את מלאכתו וחכמתו וכו', אבל כיון ששאלה זו גופא מורה על חלישות הבטחון, הרי אפשר שהדרך בנוגע לבתם תחי' צריך להיות בהליכה בשאלה ברופאים, כי אין אתנו יודע נפלאות תמים דעים יתברך ויתעלה.</p>\n<p>ויה\"ר מהשי\"ת שאיך שיחליטו - יהי' להצלחה ולחיזוק בריאות בתם...תחי', ויגדלוה לתורה ולחופה ולמעשים טובים מתוך הרחבת הדעת.</p>\n<p>והשי\"ת יעזר לכאו\"א מאתנו שלא נהי' כחולמים, אפילו כפי המבואר בתו\"א שבשעת ההתקשרות היא התקשרות אמיתי[ת], ואצ\"ל כפי המבואר בהמאמר אין הקב\"ה בא בטרוניא כו' במדריגה פחותה מזה.</p>\n<p>מאשר הנני קבלת מכתביו, ה' י\"ז טבת וד' שבט, עם חוו\"ד ע\"ד התלמידים, ות\"ח ת\"ח ע\"ז, אף שאין דעתי נוחה ממה שלא שלח חוו\"ד בענין הת'... כיון שכנראה שבמקרה זה, גם העדר השילוח, חוו\"ד הוא. ולא הי' צריך להיות באופן כזה - מתאים להוראת נשיאנו בהענין דאהבת ישראל, ואשר השני כמו אספקלריא, ובמילא אם רואה בו חסרון הרי קרוב הדבר לאמר אז עס שפיגלט זיך אפ דער אייגענער חסרון.</p>\n<p>להנ\"ל הנני כותב בפ\"ע און - שארפער, ולכן תקותי שלא יקפיד על מכתבי זה.</p>\n<p>בברכה לחיזוק ההתקשרות ובפרט ליום ההילולא הבע\"ל ובברכת הצלחה בעבודתו בקודש ובעניניהם הפרטים,</p>\n<p><b>מ.שניאורסאהן</b></p>\n<p>נ\"ב: מוסג\"פ הקונטרס שהו\"ל זה לא כבר. וכן נשלח לו בפ\"ע ספר מאמרים ה'תש\"ג.</p>\n<h4><i><b>ז'תתקמב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 94, מצילום האגרת.</p>\n<p><b>וידוע מאמר:</b> רא גם לעילח\"ז אגרות ב'נב.</p>\n<p><b>בתו\"א:</b> וישב כח, ג.</p>"],[1200950188,"ז'תתקמג\n\n<p>ב,ה, ו' שבט, תשי\"ג</p>\n<p>ברוקלין.</p>\n<p>הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו' מוה\"ר... שי'</p>\n<p>שלום וברכה!</p>\n<p>מיט צופרידענהייט און פרייד האב איך באקומען אייער בריף וועלכן איר האט אנגעהויבן שרייבען י\"ט טבת, און אין וועלכן איר באשרייבט ווי עס איז אדורך דער חודש תשרי און נאך דעם.</p>\n<p>איך בין העכסט צופרידען צו זען, אז איר האט זיך אליין איבערצייגט אין דעם אויפטו וועגן די ס\"ח, און איך בין זיכער אז דאס וועט אייך דינען אלעס א מוסר השכל אז יעדער איד איז א שליח פון הקב\"ה און ווען אפילו עס דאכט זיך עם אז ער איז שוואך אין זיינע כחות בגשמיות אדער אין רוחניות, איז דאס נאר וויילע ער פארגעסט לשעה אז ער איז א שליח פון הקב\"ה וואס זיינע כחות זינען אין סוף ובלי גבול, אבער ווען ער געדיינקט אז ער איז א שליח פון הקב\"ה איז דאס בריינגט עם הצלחה און בריינגט אויך געזונט כפשוטו בגשמיות.</p>\n<p>און השי\"ת זאל אייך מזכה זיין מיט נאך גוטע שליחות'ן לאריכות ימים ושנים און זאלט דאס אויפירן מתוך שמחה און בעסערען געזונט-צושטאנד, און זאלט קענען אנזאגן גוטע בשורות וועגן דעם צושטאנד פון אייער פרוי תחי'.</p>\n<p>נאך שבת - מאנטאג יו\"ד שבט, איז דער יארצייט טאג פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, און לויט אייער בקשה וועל איך מזכיר-זיין אייך און אייער פרוי תחי', און בייגעלייגט איז דא א קורצע ביאגראפיע אין אידיש וועלכע איז די טעג ארויס פון דרוק, און וועלכע וועט אייך נוצען אויך אין אייער השפעה צווישן אייער סביבה.</p>\n<p>בברכה לרפואה קרובה לו ולזוגתו שיחיו ולבריאות הנכונה.</p>\n<p>המחכה לבשו\"ט.</p>\n<h4><i><b>ז'תתקמג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 67.</p>"],[1200950189,"ז'תתקמד\n\n<p>ב\"ה, ט' שבט, תשי\"ג</p>\n<p>שלום וברכה!</p>\n<p>זה עתה קבלתי מכתבו מכ\"ז טבת, ושמחתי לקרות בו שמתקדם דבר הנישואין של...</p>\n<p>נהניתי ממ\"ש במכתבו ע\"ד השתתפות מאנ\"ש שי', וכידוע שכשעושים מצות הרי גם זה שגרם לאותה מצוה, ובפרט בענינים דמשפיע ומקבל - הן ברוחניות והן בגשמיות - הרי המקבל עושה יותר עם הנותן ממה שעושה הנותן עם המקבל.</p>\n<p>ובטח קרא ג\"כ בס' הזכרונות מכ\"ק מו\"ח אדמו\"ר, איך שנערים התרגלו לתת גמ\"ח אחד לרעהו כדי לזכות הנותן במצוה דגמ\"ח והמקבל במצוה דפרעון חוב. ובפרט בענין דנישואין, שידוע עד כמה שהפליגו חז\"ל בכל הפרטים הקשורים בזה.</p>\n<p>ובהמשך לזה, ארשה לעצמי גם אני, להשתתף בהוצאות הנישואין ע\"י הסקריפ המצו\"פ...</p>\n<p>בברכת מזל טוב.</p>\n<h4><i><b>ז'תתקמד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 69.</p>"],[1200950190,"ז'תתקמה\n\n<p>יו\"ד שבט, תשי\"ג:</p>\n<p>ביום ההילולא לחזק ההתקשרות ובעשי' בפועל דנשיאנו אשתכח גם בעולם הזה יתיר מבחיוהי.</p>\n<p>בברכה,</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ז'תתקמה</b></i></h4>\n<p>נדפסה בסה\"מ באתי לגני ח,א ע' שעא.</p>"],[1200950191,"ז'תתקמו\n\n<p>ב\"ה, י\"ג שבט, תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nישראל נח שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתו מע\"ש וארא, והיום נתקבל ג\"כ הפ\"נ מדיירי פרימא, שאקראהו בל\"נ בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>בנוגע למ\"ש בענין הנסיעה לאה\"ק ת\"ו ומבקש תשובה בהקדם אלא שמתחיל במכתבו, שלדעתי שסברא נכונה היא שיסע לאה\"ק ת\"ו,</p>\n<p>הנה כמדומה, שבמכתבי הנ\"ל כתבתי ג\"כ שעליו לקחת בחשבון שבמקומו עתה הנה לוקח הוא חלק <b>פעיל</b> במוסד כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע צי\"ע נשיא ישראל, משא\"כ באה\"ק ת\"ו וכו' וכו', ושכפי הידיעות שמתקבלים משם עתה, הנה עוד יותר מאשר מלפנים - שבדרך הטבע אין נראה שתהי' לו שם אפשריות כזו. ולפלא שבמכתבו זה אינו מזכיר דבר בהנוגע לנקודה עיקרית ופנימית זו.</p>\n<p>ובנוגע לשאלתו אם יסע בחדש אדר או לאחר כך - הנה ע\"פ הנ\"ל מובן, שכל העכבה לטובה. והשי\"ת יתן לו הרעיון הנכון להחליט ולעשות באופן היותר טוב לפניו, ובמילא גם לפני זוגתו תחי' אשר כגופו דמיא, והטוב - בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקמו</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר ישראל נח:</b> בליניצקי. אגרות נוספות אליו - לעיל ז'תתקכו, ובהנסמן בהערות שם.</p>"],[1200950192,"ז'תתקמז\n\n<p>ב\"ה ט\"ז שבט, תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הרבנית מרת חנה תחי'</p>\n<p>ברכה ושלום!</p>\n<p>...וועגען דעם וואס איר שרייבט אין אייער בריף אז איר זייט דיסאפאינטעט און דעריבער האט איר געסטאפט צו טאן אין דעם ענין פון טהרת המשפחה, איז זיכער דאס ניט א גענוגענדער טעם. אז השי\"ת שטייט אן צו האבן צו טאן מיט יעדערן פון אונז פילע מאל און ווערט ח\"ו ניט דיסאפאינטעט, במילא דארף דאס דינען פאר א מוסר השכל אויף ניט צו איינגעמאטערט ווערן פון צו מקרב זיין אידען, סיי מענער סיי פרויען יונג אדער אלט, צו תורה ומצות דורך אלע מעגליכע וועגען, און מיר זיינען פארזיכערט, אז אויב מען טוט נאר מיט א ערנסטקייט און מיט א אמת'ן ווילען, איז, סוף כל סוף, אביסל פריער אדער אביסל שפעטער, איז מען מצליח.</p>\n<p>בנוגע אייער שרייבען וועגען דער מקוה בא אייך אי שטאט, איז מיר א וואונדער וואס אלע יונגע לייט וועלכע זיינען בא מיר געווען אויך אייער מאן איינגעשלאסען, האט מיר קיינער ניט געזאגט וועגן דעם. איך וועל זעהן בא ערשטער געלעגנהייט צו אויסגעפינען דעם צושטאנד אין דעם.</p>\n<p>בברכה לנחת חסידותי מכל ילידיהם ביחד עם בעלה- שיחיו,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקמז</b></i></h4>\n<p>מצילום האגרת.</p>\n<p>מרת חנה תחי': גולדשטיין. אגרות נוספות אליה - לעיל ח\"ד תתי. לקמן ז'תתקעז.</p>"],[1200950193,"ז'תתקמח\n\n<p>ב\"ה, ט\"ז שבט, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח י\"א נו\"נ וכו' מוה\"ר יהודה שי'</p>\n<p>שלום וברכה!</p>\n<p>... זה מכבר נשלח לו סעט שדי חמד, ועתה נשלח לו עוד סעט.</p>\n<p>בכלל עלו הוצאות הדפסה של השדי חמד לסכום עצום שלא שיערתי מראש. ומובן, אשר לולי עזרת הנדבות ביחוד לתכלית זו לא הי' נדפסים הכרכים שעד עתה, וכן הכרך האחרון הנמצא עתה בדפוס, כי ההכנסה ממכירת הספרים פעוטה היא למאד, וגם - זה קשור עם הוצאות נוספות, ובטח יצליח השי\"ת.</p>\n<p>בברכה לבריאות הנכונה לו ולכב\"ב שי' ופרנסה בהרחבה,</p>\n<p><b>מ. שניאורסאהן</b></p><p><i>ז'תתקמח</i></p>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר יהודה:</b> שמוטקין. אגרות נוספות אליו - לעיל ח\"כ זקתרא, ובהנסמן בהערות שם.</p>"],[1200950194,"ז'תתקמט\n\n<p><i>[ח\"י שבט תשי\"ג]</i></p>\n<p>ההתעסקות בישיבת אחי תמימים בניו הייווען הוא מילוי שליחותו בעלמא דין.</p>\n<p>ובמילא הרי\"ז הצינור שדרכ[ו] הקב\"ה נתן, נותן ויתן ברכה והצלחה בכל המצטרך לו ולבני ביתו שיחו בגשמיות וברוחניות. ולמותר להאריך בזה שהרי אפילו בהתבוננות קלה בהמופתים הגלויים שאירעו לו בשנתיים האחרונות הן בעניניו הפרטיים והן בעניניו הכללים, מבינים ורואים זאת.</p>\n<h4><i><b>ז'תתקמט</b></i></h4>\n<p>נדפסה בס' זכרון תפארת משה יצחק (אחרי ע' 124).האגרת היא אל מוהרמ\"י העכט.</p>\n<p>אגרות נוספות אליו - לעיל ז'תתמד, ובהנסמן בהערות שם.</p>"],[1200950195,"ז'תתקנ\n\n<p><i>[כ' שבט תשי\"ג]</i></p>\n<p>זה עתה נתקבל מכתבו מט\"ז שבט. ויה\"ר מהשי\"ת אשר יקבל את כל הרשיונות והניירות הנחוצים לנסיעתו, והנסיעה תהי' בעתה ובזמנה בשעה טובה ומוצלחת ובקל.</p>\n<p>ובטח למותר להעירו, אשר טרם נסעו יבקר בכל המוסדות דחב\"ד באה\"ק ת\"ו. ומה טוב שמיום צאתו להנסיעה הנה, בלי נדר יפריש בכל יום מימות החול פרוטה לצדקה וכן יוסיף קאפיטל אחד של תהלים על השיעור היומי. והשי\"ת יצליחו בכל.</p>\n<p>בברכת הצלחה.</p>\n<h4><i><b>ז'תתקנ</b></i></h4>\n<p>נדפסה בכפ\"כח גליון 558 (וש בט תשנ\"ג) ע' 24.</p>\n<p>האגרת היא אל מו,ה יחיאל מיכל יהודה ליב זלמנוב. אגרות נוספות אליו - לעיל חט\"ו ה'תטז, ובהנסמן בהערות שם. לקמן ח'ג. ח'כט. ח'צא.</p>\n<p><b>לנסיעתו:</b> אחרי שזכה בהגרלה לנסוע אל כ\"ק אדמו\"ר שליט\"א. ראה כפ,ח שם. לקמן אגרת ח'ג.</p>"],[1200950196,"ז'תתקנא\n\n<p>ב\"ה, כ\"ה שבט, תשי\"ג</p><p>ברוקלין</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר אברהם שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתביו מי\"ט טבת וט' שבט וכן רשימת התלמידים דתו\"א שקבלו דמי חנוכה, וג\"כ הפ\"נ דיו\"ד שבט.</p>\n<p>... ג) לאחר כל המכתבים המתקבלים, ווייס איך ניט קיין טאלק, מה נעשה בענין ההשתדלות אודות הילדים שמפתים אותם המיסיאן, שכנרא, לע\"ע נשאר זה בין קבוצה אחת מאנ\"ש להשני' ובמילא אין כל אחד מתעסק בזה. כי, מהטעמים שכתבתי, אי אפשר שיהי' באופן רשמי נקשר עם הרשת ופשיטא שלא עם ישיבת לוד. אבל, לאידך גיסא, כיון שהבטיחו לי כמעט אופיציעל שאם יהי' באופן המתאים, הבנין והפעדאגאגיא, יתנו אז כמעט את כל ההוצאה, חבל שלא להשתמש בהזדמנות זו. וביאור בגדול ענין זה ברוחניות - אין להעריך ואין לשער.</p>\n<p>... ה) בנוגע להחלקאות דהכפר, הנה גם זה מצער, שכפי השמועה ישנם שם כאלו שאינם שייכים וגם אינם חושבים ע\"ד חקלאות, ובכ\"ז נרשמו ברשימת החקלאים פן ואולי יזכו עי\"ז בדבר מה, שאף שיגרום נזק להחקלאים באמת...</p>\n<p>בברכה לנחת חסידותי מכל יו\"ח, ומעצמו - לא כש\"כ, לבריאות הנכונה ולהזכות היותר גדול לבשר אך טוב תכה\"י...</p>\n<p>בנוגע לההוצאה לאור דהמאמרים והנדבר בהתועדות, הנה כל זה תלוי בחוסר הפנאי.</p>\n<h4><i><b>ז'תתקנא</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ס ע' 121.</p>\n<p><b>מוה\"ר אברהם:</b> פריז. אגרות נוספות אליו - לעיל ז'תתנד, ובהנסמן בהערות שם.</p>\n<p><b>אודות הילדים:</b> ומשתדלים לארגנם בבתי הספר למלאכה בכפ\"ח. ראהלעיל אגרת ז'תתקיג.</p>"],[1200950197,"ז'תתקנב\n\n<p>ב\"ה, כ\"ה שבט, תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"א שבט, בו כותב ע\"ד הנכבדות שמציעים לבתו..תחי' עם האברך מר.. שי':</p>\n<p>הנה אם מבין התמימים ואנ\"ש לא נמצא ענין המתאים בשבילה, וכן אין ביניהם חילוק בשנים יותר מדאי, וגם בתו מסכמת מרצונה הטוב על הצעה זו, אזי כדאי לקרב הדבר.</p>\n<p>והשי\"ת ינחם בדרך הטוב לפני בתו תחי' בגשמיות וברוחניות גם יחד.</p>\n<p>בברכה,</p>\n<p><b>מ.שניאורסאהן</b></p>\n<h4><i><b>ז'תתקנב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 96.</p>"],[1200950198,"ז'תתקנג\n\n<p>ב\"ה, כ\"ה שבט, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמהור\"ש שי'</p>\n<p>שלום וברכה!</p>\n<p>מפני הסדר הנני מאשר עוה\"פ קבלת מכתביו מיום ר\"ח טבת, יו\"ד, כ\"ב, כ\"ט טבת.</p>\n<p>ז', יו\"ד ט\"ז וכ' שבט עם המצורפים אליהם, ות\"ח על הכתיבה לפ\"ע בפרטיות. כן נתקבלו חבילות הספרים שנשלחו על ידו ששי וט\"ו בטבת.</p>\n<p>ב) בנוגע לחלוקת דמי חנוכה, הנה כמדומה שכבר כתבתי שאין כדאי להחמיר בזה, היינו שאם רק יש ספק - לתת, ולו יהא ע\"ש העתיד. ואולי זה גופא יסייע שיתקרבו בהקדם.</p>\n<p>ג) בנוגע למ\"ש ע\"ד העבודה בכפרים ובעיירות הגדולות וכו'. הנה דעתי מכבר, שאף שיש לעבוד בהכפרים כי מצילים שם פשוט מטמיעה, אבל בכ\"ז נוגע ביותר לחנך מורים ומדריכים מבין המרוקנים גופא, ושלאידך גיסא יהיו ג\"כ קשורים וברוח ליובאוויטש עד שיהיו טופח ע\"מ להטפיח. ולכל היותר יצטרכו רק אפ פרישען זיך מזמן לזמן (אשר לזה מהראוי - בימי החופש מלימוד - לערוך בשבילם מעין לימודים מיוחדים ביותר אויף דער ארום ובעניני חינוך. ונוסף על עצם הלימודים - הרי יהיה בזה ענין של קירוב הדעת בשבילם, ואולי כדאי לתת פרסים להמצטיינים בזה. כמדומה לי, שזמני החופש הם ניסן תשרי ובאמצע הקיץ. ובטח יודיעני אודות זה).</p>\n<p>ד) במ\"ש ע\"ד הלעז דעניני איסור סקילה ר\"ל אשר יש סברא להכאה.הנה פשיטא, שבכותלי הישיבה דבר זה מופרך לגמרי, כי מלבד שהענין עצמו - התוכחה ע\"י הכאה - הוא יותר שלילי מאשר חיובי, הנה בטח יתפרסם הן העונש והעיקר הסיבה, בין ההורים, ובפרסום יותר בין התלמידים, ואז יש מקום לחשש שגם אלו שאין יודעים ע\"ד כללות הדבר יתענינו. וידוע מענין חטא עה\"ד שהענינים הנמשכים בידיעה פועלים בדרך פנימי וכו'. ויש לחפש דרכי עונש אחרים, וכמו ריחוק מביה\"ס למשך איזה זמן, או כולו.</p>\n<p>או ע\"ד המובא בשיחות כ\"ק מו\"ח אדמו\"ר שלא להרשות להם להיות נוכח בעת סיפורי צדיקים וכיו\"ב ענינים שלבם חפץ. והעולה על כולנה - השגחה נוספת על התלמידים, שיש לקוות שבד\"מ ילך הלוך ויתמעט הענין עד שיופסק לגמרי.</p>\n<p>ה) בטח יודיע מהלך הענינים בנוגע לאוצר התורה וכו' - במשך הזמן שעבר מעת כתבו.</p>\n<p>ו) כבר העירותי מאז ע\"ד חיפוש הדרכים בכדי שיוכלו להדפיס במכ\"ע המופיעים במדינתם, מזמן לזמן, ע\"ד חב\"ד בכלל ופעולותיהם על אתר בפרט. ובשפה הצרפתית אין כלל אחריות - כיון שמבינים הם אותה. ואפילו בשפה הערבית - בטח יוכלו למצוא מי שהוא נאמן שיעיד שההעתקה מתאמת להכוונה.</p>\n<p>ז) בעינן הסידורי תפלה, כמדומה כבר כתבתי שכדאי לתתם לאליאנס - באופן המתאים שלא יפרשו זה כהסכם על שיטתם.</p>\n<p>ח) במכתבו מז' שבט אינו כותב פרטים ע\"ד בריאותו. ובטח לעת קבלת מכתבי זה כבר הוטב. ולמותר להעיר, אשר צריך למלאות כהוראות הרופאים. וידוע פסק הרמב\"ם אשר היות הגוף בריא ושלם מדרכי השם הוא. וה\"ה להאברך יונתן בן מרים שי' הלוי - שגם אודותו מצורף פ\"נ. ובטח יבשר טובות גם עד\"ז.</p>\n<p>ט) נהניתי במאד ממ\"ש שאחד מהמלמדים דאהלי\"י הכריז שיבדקו התפילין והמזוזות ותיקן הענין. ומה טוב שגם בשארי המקומות יהיו מתענינים בזה. וכדאי שיתדבר עם הרה\"ג והרה\"ח כו' הרבא\"ג שי' ע\"ד תקציב מיוחד לתועלת זו. וכדאי ההוצאות והטרחה בשביל גודל הענין. ונוסף ע\"ז שבודאי יפעול ג\"כ על החינוך. ומענינא דיומא - הנה כדאי להתענין במנהגם על אתר בנוגע לפסח ובפרט בענין שמורה.</p>\n<p>וכמדומה שגם בשנה שעברה נתנו לאחדים. ואם אין בזה חילוק דמערבאי ומדינחאי, היינו אשכנז וספרד - אולי כדאי ליתן בתור תשורה להעומדים בראש באהלי\"י והתחילו לנהוג במנהגי חב\"ד - מצות שמורה לאפיקומן עכ\"פ. ובטח גם בזה יתדבר עם הרה\"ג והרה\"ח כו' מוהרבא\"ג, שי'...</p>\n<p>יא) נהניתי במאד ממה שיצא לפועל שילוח התלמידים לבתי הכנסיות. ובודאי יתן השי\"ת הצלחה הן בהשפעת התלמידים על השומעים, והן בפעולת הדבור על התלמידים בעצמם.</p>\n<p>יב) גרמה לי שמחה מיוחדת ביאת מהר\"ן שי' פינסאן (שבטח יגרום זה ג\"כ להרמת רוחו הוא)... והשי\"ת יזכהו לבשר בשו\"ט ולעתים תכופות - בעניני הכלל וכן בעניניו הפרטים.</p>\n<p>יג) הגיעתני ידיעה משיקאגא ששלחו מביהכ\"נ דשם על שמו עוד עשר חבילות בגדים, ויש מן המוכן עוד לערך עשרה.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובשאר ענינו ובפ\"ש כל המשתתפים אתו עמו,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקנג</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוהרש\"ב שי':</b> מטוסוב. אגרות נוספות אליו - לעיל חי\"ט ז'רלח, ובהנסמן בהערות שם.</p>\n<p>לקמן ז'תתקעב*. ח'טז.</p>\n<p><b>שכבר כתבתי:</b> ראע לעילח\"ה אגרת א'שמא.</p>\n<p><b>וידוע מענין חטא עה\"ד:</b> ראה סה\"מ עזר\"ת ע' פט ואילך.</p>\n<p><b>המובא בשיחות:</b> ראה סה\"ש קייץ ה'ש\"ת ע' 161.</p>\n<p><b>אין כלל אחריות:</b> ר\"ל, שבדיעבד יש להסתפק גם בזה.</p>"],[1200950199,"ז'תתקנד\n\n<p>ב,ה, כ\"ו שבט, תשי\"ג</p>\n<p>ברוקלין.</p>\n<p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר אברהם אליעזר</p>\n<p>שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו - באיחור זמן קצת - בו כותב על דבר מצבו ושואל חוות דעתי, אם יסע עתה לאה\"ק ת\"ו ע\"י משיח צדקנו.</p>\n<p>והנה לדעתי כיון שנמצא במדינה אשר בזמן האחרון באו שם כמה אנשים יראי ד' נוסף על אלו שהיו דרים שם מקודם, וכיון שאין איש אתנו יודע על ברור הכוונה העליונה במה שנמצא הוא במקום פלוני כי רק מד' מצעדי גבר כוננו, הרי יקיים בעצמו מקומך על תנח וישפיע על סביבתו באופן המתאים לחזקם בתורה ומצוה און אנווארימען מיט אידישע ווארימקייט, והשי\"ת יתן לו אריכות ימים ושנים טובות להאיר בסביבתו ובתוספת בנר מצוה ותורה אור ומאור שבתורה זוהי תורת החסידות דרכי' ומנהגי', ואפילו בשביל פעולה אחת טובה, הנה ידוע הכתוב בתניא פרק כ\"ה אשר בעשיית מצוה איזה שתהי',הנה למעלה הוא ענין נצחי לעולם ועד, וידוע ג\"כ פתגם הבעש\"ט מה ששמענו כמה פעמים מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אשר נשמה יורדת למטה ומלובשת כמה עשרות בשנים בגוף ישראל בכדי לעשות טובה ליהודי בגשמיות או ברוחניות.</p>\n<p>בברכה לאריכות ימים ושנים טובות עם כל הפירושים.</p>\n<h4><i><b>ז'תתקנד</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>מוה\"ר אברהם אליעזר:</b> זמערקאוויץ, מויזבערי ק.פ. אפריקה.</p>"],[1200950200,"ז'תתקנה\n\n<p>ב\"ה, ד' אדר תשי\"ג</p><p>ברוקלין.</p><p>הרב הגאון הרה\"ח נו\"נ אי\"א חו\"ב עוסק<br>\nבצ\"צ וכו'<br>\nמוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>מוסג\"פ מכתבי מענה באופן רשמי על החלטתם בהאסיפה. ולפלא קצת על</p>\n<p>החלטתם. כי בטח סיפר מוהר\"א שי' וואלף איך שנסע לעשות מגבית בהיותו כאן, וכן הר\"מ שי' גורארי'. כן בל\"ס ידוע להם הקישויים שפוגש הרב קיפניס שי' ועתה הרב הבלין שי',אשר בהנ\"ל יש גם מומחים למקצוע אוסף כספים, ובכ\"ז הוא כנ\"ל. וכפי הידיעות שיש לי ממהותו של הרב... שי', הרי לכאורה אינו מתאים כלל להיות שד\"ר לאסוף כספים ובפרט במדינה זו, שנמצאים בכל מקצוע ובכל ענין כו\"כ מהם, וכאלו שכבר נעשו מומחים למקצוע זה מכמה שנים, אז מען ווארפט זיי ארויס דורכן טיר קריכן זיי דורכן פענסטער ובבת שחוק וסבר פנים יפות וכו'...</p>\n<p>בכבוד ובברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקנה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 122, מצילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובהנסמןד בהערות שם.</p>"],[1200950201,"ז'תתקנו\n\n<p>ב\"ה, י\"ב אדר תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה על הודעותו מקשוה\"ת של בתו תחי, יתן השי\"ת שתהי' בשעה טובה ומוצלחת ובבנין עדי עד על יסודי התורה ומצוה כפי שהם מוארים במאור שבתורה זוהי תורת החסידות.</p>\n<p>והנה ידוע דרך הקדושה שהוא לאט לאט, ובמילא, צריך הי' למצוא דרכים המתאימים לקרב את המיול\"ח, לתורת החסידות דרכי' והנהגותי', ובפרט ע\"פ מרז\"ל דחתנו כבנו, וידוע שמצות חינוך בבן היא מוטלת על האב, ובפרט מצות חינוך דתלמוד תורה שהוא מדאורייתא על האב, וכפסק רבינו ז\"ל בהלכות ת\"ת בתחלתו ובכמה מקומות. ופשוט אשר לימוד תורת החסידות הוא בכלל זה.</p>\n<p>בברכת מזל טוב,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקנו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 96.</p>\n<p><b>מקשוה\"ת של בתו:</b> ראה לעיל אגרת ז'תתקנב.</p>"],[1200950202,"ז'תתקנז\n\n<p>ב\"ה, כ\"ב אדר תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ וכו'<br>\nמוה\"ר סעדי' שי'</p>\n<p>שלום וברכה!</p>\n<p>נתקבל מכתבו מאור ט\"ז אדר עם הרשימות המצו\"ב. כן קבלתי מכתב מקסבלנקה, אשר כבר בא לשם בשעה טובה ומוצלחת, ולפלא שלא הודיע עד\"ז במברק. והשי\"ת יעזרהו ויצליחו, שיה' משנה מקום משנה מזל לטובה ולברכה, ויצליח בעבודתו בכרם חב\"ד במוסד כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע צי\"ע, אשר זה ימשיך לו תוספת ברכה והצלחה גם בעניים הפרטים - שלו ושל ב\"ב שיחיו.</p>\n<p>מוסג\"פ קונטרס שהו\"ל זה לא כבר.</p>\n<p>בברכת חג פסח כשר ושמח,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקנז</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר סעדי':</b> ליברוב. אגרות נוספות אליו - לעיל ז'תתצז, ובהנסמן בהערות שם.</p>\n<p><b>כבר בא לשם:</b> ראה לעיל אגרת ז'תתקלז.</p>"],[1200950203,"ז'תתקנח\n\n<p>ב\"ה, כ\"ה אדר תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר משה פנחס שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל הודעתו אודות המלוה מלכה, סעודתא דדוד מלכא משיחא, שערך בביתו במוצש\"ק העבר. ולפלא מה שמצטער על, שלפי השקפתו, התוצאה היא פעוטה, וכבר ידוע פתגם הבעש\"ט, מה ששמענו מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע: והי' ראשיתך מצער - ועי\"ז - ואחריתך ישגא מאד. ובודאי גם בנדון זה יהי' כן - הן בגשמיות והן ברוחניות. והשי\"ת יזכהו ואת זוגתו שיחיו וכל המתועדים בהתועדות זו, להועד עוד פעמים רבות בהתועדות חסידותית ובשמחה אמיתית, ולפרוץ עי\"ז את הענינים המעלימים ומסתירים, עד אשר נזכה כולנו, בתוך כלל ישראל, שיוסרו הכתלים והמחיצות ויתגלה, למטה מעשרה טפחים, זה שנאמר עליו הנה זה עומד אחר כתלנו - הוא דודו מלכא משיחא.</p>\n<p>בברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקנח</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר משה פנחס:</b> כץ. אגרות נוספות אליו - לעיל ז'תשסה, ובהנסמןב הערות שם.</p>\n<p><b>פתגם הבעש\"ט:</b> ראה גם לעיל חט\"ו אגרת ה'תלט, ובהנסמן בהערות שם. חט\"ז ה'תתקיא. חי\"ח ו'תקכב. לקמן ח'סג.</p>"],[1200950204,"ז'תתקנט\n\n<p>ב\"ה, ז' ניסן ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הרב הגאון הרה\"ח וו\"ח אי\"א נו\"מ חו\"ב<br>\nעוסק בצרכי<br>\nציבור וכו' מוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>מוסג\"פ העתק מכתבי למר שז\"ר שי', ותכנו אינו דורש ביאור נוסף. ולחוות דעת כת\"ר בכל זה - אחכה. וכפי ההשערה, הנה זהו המוצא היחידי בהמצב עתה, שעלול ח\"ו שהחינוך כולו יעבור לידי הממשלה, ואותו שישאר מבחוץ יקבל רק חצי התקציב והחצי השני צריך יהי' להאסף על ידי כל מפלגה ומפלגה אשר לא תוותר על חינוכה, אשר אז מקום לחשש, וקרוב לודאי, שלא יהי' ביד המפלגות להספיק התקציב, ובמילא יבוטלו כמה מתשב\"ר מחינוכם וכו' וכו'.</p>\n<p>... כפי הידיעות שקבלתי ימים אלו, הנה כמה מהיראים, כנראה, כבר השלימו עם הרעיון - מבלי כל מלחמה, ואפי', כנראה, מבלי כל השתדלות. על פי מרז\"ל אל תדין את חברך עד כו' וכיון שנמצא אני בחוץ לארץ - הנה אינני דן בגוף הדבר אם יש להאשימם על העדר ההשתדלות אם לא, אבל, וכפי פתגם כ\"ק מו\"ח אדמו\"ר - דאס איז א זאך פאר מלאך מיכאל, אבער דער ענין טוט זיך דאך ניט אפ. ולכן כתבתי לשז\"ר שי' כנ\"ל. ודעתי חזקה, ש\"מסירות נפש\" זו יש לתבוע בתוקף מכל המפלגות - התחל באגודה וסיים בפועל המזרחי, ולעשות רעש אם לא יסכימו על מסירות נפש כזו, ואבוי ואבוי שגם לזה מס\"נ יקרא.</p>\n<p>ות\"ח לכת\"ר אם יודיעני בהקדם חוות דעתו על כל הנ\"ל. ובודאי מה שיש בידו לעשות בכיוון זה יעשה. ות\"ח על ההודעה.</p>\n<p>ידיעה משמחת קבלתי לפני השבת, אף שעדיין איני יודע אם נכונה היא לגמרי, שבכל אופן מדברים ע\"ד חינוך ממשלתי בפועל לא בתשי\"ד, אלא בתשט\"ו.</p>\n<p>קבלתי מכתבו עם הידיעה שמשנה דירתו למקום חדש, ונתקבל קודם נסעי על ציון כ\"ק מו\"ח אדמו\"ר וכבקשתו הזכרתיו על הציון, שיהי' משנה מקום משנה מזל לטובה בגשמיות וברוחניות גם יחד, אשר חירות אמתית היא כששניהם הולכים יחדו, שלום בפמליא של מטה, שעי\"ז נעשה ג\"כ שלום בפמליא של מעלה (יעוין לקו\"ת ס\"פ מטות), ונמשך ברכה והצלחה כיון שהכלי - שלום.</p>\n<p>בטח יודיעוני חדשות ע\"ד מר ציוני וז' שי'.</p>\n<p>בברכה לחג הפסח כשר ושמח ומתוך בריאותה נכונה בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><p>מוסג\"פ מכ' כללי, שבטח יענינו.</p>\n<h4><i><b>ז'תתקנט</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובהנסמן בהערות שם.</p>\n<p><b>העתק מכתבי למר שז\"ר:</b> דלקמן - ז'תתקס.</p>\n<p><b>שישאר מבחוץ...חצי התקציב:</b> שבדרך זה נפתח ה\"חנוך העצמאי\".</p>"],[1200950205,"ז'תתקס\n\n<p>ב\"ה, ח' ניסן, ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"מ ענף עץ אבות עוסק בצרכי<br>\nציבור וכו'<br>\nמוהרש\"ז שי'</p>\n<p>שלום וברכה!</p>\n<p>בזכרי את שיחתנו בעת ביקורו כאן והשקפתו על אדות היחס של כבוד לרגשת הדת של החרדים בבני ישראל ולמסורת העבר של עמנו, אשר יש לתבוע מכל המשרדים והמוסדות באה\"ק ת\"ו, הנני בא לכבודו בשורותי דלקמן:</p>\n<p>א. בודאי משערים וגם יודעים, עכ\"פ במקצת, אודות הרושם המכאיב והתמרמרות בחוגים שונים, ולאו דוקא של החרדים, שגרמה הידיעה על דבר שאיפת הממשלה לשנות המצב הנוכחי ולהעביר לרשותה את כל החינוך באה\"ק ולבטל הזרמים, בה בשעה אשר רקע הממשלה בענינים דתיים עד עתה לא הי' נייטראלי, ומזמן לזמן עוד הולך ונגרע.</p>\n<p>וזאת להעיר, אשר איני דן אודות עצם העובדה של חינוך ילדים על ידי מפלגות פוליטיות, כי לא עתה זמן דיון זה ולא כאן המקום, אבל שינוי המצב הקיים והעתקתו \"מימין לשמאל\" בצורה כזו מכאיב הוא.</p>\n<p>ב. כנראה, וגם השכל מחייב כן, הנה עיקר הסיבה לשאיפת הממשלה לבטל הזרמים, אינה לשם התקפה על החלק הדתי שבדבר, אלא משום נימוקים פוליטיים, היינו, בלי יופי המליצה, פשוט מטכסים עצה כיצד למנוע שלא יחנכו ויגדלו בבתי הספר הזרמים מנגדים להשקפות הפוליטיות והכלכליות של המפלגות אשר רסן הממשלה בידן עכשו. שהרי זרמי החינוך עתה משתייכים למפלגות ובמילא משמשים גם כן במות להשקפות פוליטיות מנגדות אחת לחברתה.</p>\n<p>ג. אף אם ישנם כאלו אשר כוונתם בביטול הזרמים היא התקפת הדת, בטח מועטין הם ולא הם המנסחים את השיטה של המפלגות השליטות. ועוד זאת אשר בהתבוננות הגישה המתאימה הרי מוצאים בלב <b>כל</b> אחד מישראל זיקה לדתיות, ולא לדתיות סתם אלא לדת ישראל, הגם אשר רגש זה מתבטא בכמה מבני עמנו, באופנים שונים, מפני כמה סיבות.</p>\n<p>ד. כפועל יוצא משלושת נקודות אלו, הנה פתרון הנכון לדעתי הוא - באם כבר הוחלט לבטל הזרמים - להוציא את החינוך של הזרמים מרקע הפוליטיקה, היינו שבתי הספר יצאו מרשותם והנהלתם של המפלגות הפוליטיות, ויועמדו לרשותם של אירגונים אשר צורתם היא אך ורק רוחנית-חינוכית. במלים אחרות, שהנהלת בתי הספר תימסר לידי מוסדות ואנשים (עסקנים, הורים מורים וכדומה) אשר אורח חייהם והשקפתם בדת מתאימים לתכנית בית הספר, ולא תהי' בידי אנשים כאלו שאין רוחם כרוח בית הספר אלא שיעמידו \"משגיח על הכשרות\".</p>\n<p>הנני מקוה כי הצעתי הנ\"ל תתקבל אצל כ' ובמילא ישתדל בזה באופן המתאים.</p>\n<p>והסיכויים להגשמת הענין, בודאי במדה גדולה תלויים הם בהשתדלותו. והאיש אשר זכה לגשם ענין חינוך חובה, יזכה גם כן בענין חינוך מצוה ותורה. ואודה לכ' על הודעתו מחוות דעתו בכהנ\"ל.</p>\n<p>בכבוד ובברכת חג הפסח כשר ושמח.</p>\n<h4><i><b>ז'תתקס</b></i></h4>\n<p>מהעתק המצורף לאגרת הקודמת, כנזכר שם.</p>\n<p><b>מוהרש\"ז:</b> שזר. אגרות נוספות אליו - לעיל ח\"כ ז'תעה, ובהנסמן בהערות שם.</p>\n<p><b>ולבטל הזרמים:</b> שגם מהם סלד כ\"ק אדמו\"ר שליט\"א והשתדל לייסד \"זרם בלתי זרמי\", כדלעיל ח\"ו אגרת א'תקלה, ובהנסמן בהערות שם.</p>\n<p><b>ויועמדו לרשותם של ארגונים:</b> בהמשך לזה - לעיל ח\"ז אגרת ב'קז.</p>\n<p><b>משגיח על הכשרות:</b> בחנוך \"ממלכתי דתי\".</p>"],[1200950206,"ז'תתקסא\n\n<p>ב\"ה, י\"ג ניסן, תשי\"ג</p><p>בנוגע להתדפיס שלו בפולמוס על אודות הנדפס בתלפיות, הנה עוד יתירה מזה עשה, ונודעתי מזה רק עתה בהגיע לידי \"הגדה...\" שנבהלתי לקרות בה שמציע בפועל לשתות כוס חמישי, וכותב ג\"כ ההנהגה בזה, ובפרט שצריך להודות על הנס דאתחלתא דגאולה כו' וכו' - שהוא היפך פסק דין השו\"ע והאחרונים, מורי ישראל והפוסקים שנתקבלו מכל ישראל. והחומר בזה לגבי הנ\"ל הוא מובן, כיון שהגדה הוא ספר המסור לכל וההוראה נוגעת במעשה בפועל. ובפרט כשהיא מנוקדת - הרי באה היא גם לידי עמי הארץ שאינם יודעים שעמי הארץ הם, ובטח ילמדו ק\"ו ובנין אב וכו' - שאם מותר לעשות היפך השו\"ע בדבר זה אף שלא ראה מימיו הן אצל אביו והן אצל זקנו, הרי עאכו\"כ שאפשר לעשות היפך השו\"ע בענינים אחרים והאריכות אך למותר.</p>\n<h4><i><b>ז'תתקסא</b></i></h4>\n<p>נדפסה בקובץ יגדיל תורה ירושלים חוב' כח ע' 5.</p>"],[1200950207,"ז'תתקסב\n\n<p>ב\"ה, י\"ג ניסן תשי\"ג</p><p>ברוקלין.</p><p>הנהלת צעירי אגודת חב\"ד באה\"ק ת\"ו,<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>זה זמן רב שלא קבלתי ידיעות מפעולותיהם הטובות אשר בטח עשו בזה בקשר עם יום ההילולא יו\"ד שבט, ימי הפורים, ועושים הכנות לחג הפסח הבע\"ל. ואולי נתעכב המכתב בדרך הילוכו ועוד יתקבל. ומובן אשר כל המפרט ה\"ז משובח.</p>\n<p>ולקראת ימי החג הבאים עלינו ועל כל ישראל לטובה הנני בזה להביע ברכתי לחג הפסח כשר ושמח,</p>\n<p>ולקיום היעוד המקווה, כימי צאתך מארץ מצרים אראנו נפלאות, בגאולתנו האמיתית והשלימה, בימיהם ובימינו ע\"י משיח צדקנו.</p>\n<p>בברכת החג.</p>\n<p>זה עתה נתקבל מכתבם מט' ניסן.</p>\n<p>נ\"ב. לא הספיק הזמן לפני החג שיחתום כ\"ק אדמו\"ר שליט\"א את המכתב, ומפני שמחת קדושת המועד, הנני חותם בשמו.</p>\n<p>המזכיר</p>\n<p>א. קווינט</p>\n<p>* * *</p>\n<p>פשיטא, שאין לערב זרם אחר ומפקחו בסדרי בית רבקה וכיו\"ב.</p>\n<p>נ\"ב. מטובו להודיע באופן בלתי רשמי את המצב לאמיתו בנוגע להבית רבקה והגן ילדים בהכפר. וכן הסיבה האמיתית להעכוב שעד שעתה בענין חילוף הקרקע עם חברת מהדרין. ות\"ח מראש.</p>\n<h4><i><b>ז'תתקסב</b></i></h4>\n<p>נדפסה בקונ' צדי\"ק למלך\" ד ע' 97.</p>\n<p><b>פשיטא:</b> בשולי נוסח דומה להנ\"ל, בטופס הנשלח למו,ה דוד בראוומאן. נדפסה בקונ' \"צדי\"ק למלך\" ג ע' 46. אגרות נוספות אליו - לעיל ז'תתמ, ובהנסמן בהערות שם.</p>\n<p><b>חילוף הקרקע:</b> ראה גם לעיל ח\"ז אגרת א'תתקלט, ובהנסמן בהערות שם.</p>"],[1200950208,"ז'תתקסג\n\n<p>ב\"ה, כ\"ז ניסן, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוה\"ר סעדי' שי'</p>\n<p>שלום וברכה!</p>\n<p>קבלתי מכתבו מז' ניסן וכן המכתב שאחריו. ובשאלתו באיזה מקום יתעסק בעבודתו, הנה כפי שסיפר הרה\"ג והרה\"ח הרבא\"ג שי' היתה אסיפה משותפת מכולם ביחד כשהי' במרוקה, ואז הי' המדובר, שהוא יעבוד באחת העיירות היותר גדולות שאחרי מכנס וקסלבנקה, והיותר נראה הוא מידלעט, כיון ששם מוסדות שלנו היותר מרובים באוכלוסין. ובכלל - נראה הדבר. וכיון אשר משלנו במרוקה הם רק ד' ה' אנשים, ויש שם כר נרחב ביותר לעבודה באופן גדול בחינוך וא\"כ, במילא, ג\"כ בענין הפצת החסידות דרכי' והנהגותי', והרי כדאי שיתפזרו - עד כמה שאפשר - בעיירות שונות. ובטח, במשך זמן לא ארוך, ימצא כאו\"כ מהם עוזרים על אתר לענינים הטפלים לפ\"ע. וכיון שהכוונה היא להשפיע לא רק על התלמידים והקטנים אלא גם על הגדולים הבע\"ב הרבנים וכו', ובכדי לקרב אותם לא רק לסייע במוסדות אהלי\"י אלא גם לעניני חסידות בכלל, אשר זה פועלים יותר ע\"י לימוד עניני חסידות הקלים, הסיפורים ע\"ד דרכי החסידים וכו' - הנה תקותי ובטחוני, שבמקום שיתיישב הנה יארגן חוג של אברכים ובע\"ב - כמובן ברשיון הרבנים והחכמים שלא יהי' בזה כל ענין של פחיתות כבודם ודמותם (מפני כו\"כ טעמים) - ובמילא במשך הזמן יעמוד מחוג זה ג\"כ עוזרים ומשפיעים ומחנכים.והאריכות אך למותר. ובטח למותר להעירם, אודות יום ל\"ג בעומר הבע\"ל. וכידוע עד כמה חשוב אצל הספרדים יום הילולא, ובפרט - של הרשב\"י בעל הזהר. ובמילא בודאי חגיגתו תשביע רצון כל הנ\"ל,.</p>\n<p>המחכה לבשו\"ט ובברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקסג</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר סעדי':</b> ליברוב. אגרות נוספות אליו - לעיל ז'תתצז, ובהנסמן בהערות שם.</p>"],[1200950209,"ז'תתקסד\n\n<p>ב\"ה, י\"ב אייר, תשי\"ב</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>איך בין געווען צופרידען צו באקומען אייער בריף פון ערב שבת קודש און אויך האב איך באקומען פון אייער פאמיליע א פאטאסטאט פון דער ערלויבעניש וואס מען האט אייך געגעבן צו טראגען א בארד און פיאות וכו'.</p>\n<p>און השם יתברך יצליחו תמיד כל הימים - איר זאלט קענען לערנען תורה און מקיים זיין מצות מתוך הרחבה.</p>\n<p>און ווי איך האב אייך געשריבען - צו משפיע זיין אויך אויף אייער קאמפאני, איז דאך אפילו ווי איר שרייבט, אז נאר איין איד [איז] פאראן אין אייער קאמפאני, איז דאך אפילו המקיים נפש אחת מישראל כאילו קיים עולם מלא, און בפרט אז איך רעכען, אז עס זיינען דא מערערע אידען, נאר איר ווייסט ניט פון זיי, איז כדאי צו נאכזוכען, און מסתמא איז דאס בהשגחה פרטית, אז איר זאלט קענען מקרב זיין זיי צו יהדות.</p>\n<p>בייגעלייגט איז דא די אויסגאבע צו שבועות הבע\"ל, וועלכעס וועט אייך זיכער קענען דינען אין דאס אויבען דערמאנטע.</p>\n<p>בברכה להצלחה בכל עניניו בגשמיות וברוחניות.</p>\n<p>המחכה לבשורות טובות.</p>\n<h4><i><b>ז'תתקסד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 72.</p>"],[1200950210,"ז'תתקסה\n\n<p>ב\"ה, י\"ג אייר, תשי\"ג</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ וכו' מוה\"ר שלמה שי'</p>\n<p>שלום וברכה!</p>\n<p>איך באשטעטיק די ערהאלטונג פון אייער בריף פון ז' אייר. און איך בין געווען צופרידן צו לייענען אין עם, אז דער געזונט צושטאנד פון אייער פרוי תחי' האט זיך געבעסערט. און איך האף אז אויך אויף ווייטער וועט איר קענען אנזאגען גוטע בשורות אין דעם.</p>\n<p>אויך האט איר באדארפט אננעמען די השגחה פרטית אין דעם ענין, וואס יעצט געפינט זיך אין לונדון הרה\"ג הרה\"ח אי\"א עוסק בצ\"צ כו' מוה\"ר אליעזר שי' קאראסיק, אין שליחות פון די ליובאוויטשער ישיבות אין אה\"ק ת\"ו, וואס [אין] דעם איז אייך געגעבן געווארן א געלעגנהייט צו פארגרעסערן אייערע פעולות אין די ענינים וועלכע זיינען פארבונדן מיט הפצת תורת הנגלה ותורת החסידות, און דורך דעם פארגרעסערן די השפעה פון ברכה והצלחה פון השם יתברך אין דעם וואס אייער פרוי און איר נויטיקן זיך.</p>\n<p>און השם יתברך זאל אייך העלפן איר זאלט טאן אין דעם און אייער</p>\n<p>פרוי - שיחיו - מיט א פרייליכער הארץ און מיט גוטן געזונט.</p>\n<p>המחכה לבשורות טובות,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקסה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 125.</p>\n<p><b>מוה\"ר שלמה:</b> פעריןו. אגרות נוספות אליו - לקמן ז'תתקסח. ח'מג. ח'עב. ח'קכ. ח'קנד.</p>\n<p>ח'קצ. ח'קצז. ח'קצט.</p>"],[1200950211,"ז'תתקסו\n\n<p>ב\"ה, י\"א סיון, ה'תשי\"ב</p><p>ברוקלין, נ.י.</p><p>מר א.מ. הברמן שי'</p>\n<p>שלום וברכה!</p>\n<p>נזדמן ליד כ\"ק אדמו\"ר שליט\"א (ולפלא שלא מצא כ' לנחוץ לשלוח לספרית כ\"ק אדמו\"ר שליט\"א) החוברת שערי חב\"ד בעריכת כ'. כ\"ק אדמו\"ר שליט\"א עיין בו וציין בשולי הגליון איזה הערות, שהננו בזה להעתיקן, ובטח תהיינה לו לתועלת, ונרשמו על סדר רשימת הספרים למספרם:</p>\n<p>4 - תכנית שלא נתגשמה עדין.</p>\n<p>5 - <b>שמות בא.</b> זה באה רק פרשת <b>שמות.</b> וארא-בא נמצאים בדפוס.</p>\n<p>9 - צילום מדפוס קאפוסט.</p>\n<p>13 - נכנס בו רק הכתב בקשה. ונדפס ע\"פ השוואת שני כתבי-יד - בהקדמת המו\"ל שמחבר הכתב הוא אדמו\"ר האמצעי, <b>ולא</b> אביו אדמו\"ר הזקן.</p>\n<p>42 -41 - היא רשימתו של אדמו\"ר (רבי יוסף יצחק) זצוקללה\"ה נבג\"מ זי\"ע מליובאוויטש, אלא שרצה שידפיסוה בעילום שמו.</p>\n<p>42 - הו\"ל גם בהעתקה ללה\"ק עם הוספות באה\"ק ת\"ו.</p>\n<p>47 - ע' 307 שיטה 11 <b>ג' ד'</b>, צ\"ל <b>ג' ך'</b> (כ\"ף ארוכה) - ראה עד\"ז מכתב כ\"ק אדמו\"ר (רבי יוסף יצחק) מליובאוויטש הנדפס בסו\"ס הערות לתניא ע' 120.</p>\n<p>52 - ע' 310 שיטה 16 <b>ח' דפים</b> ט\"ס.</p>\n<p>55* - <b>בסופו: אגרת הקדש</b> כנראה צ\"ל אגרת <b>התשובה</b>.</p>\n<p>82 - <b>בסופו: משנת תר\"ס</b>. ונתקנו בהם כמה פרטים, ולדוגמא: נשמטה תיבת <b>פרק</b> אשר בראש כל סימן שבאגרת הקודש.</p>\n<p>85 - נדפס באשכנז בסביבות מינכען. ולא בברוקלין.</p>\n<p>93 - <b>שמות קצת פרשיות</b> הם רק פ' בשלח (דרוש א') ופ' פקודי (-ב' דרושים). דרושי דס' שמות - לבד פ' פקודי - באו בס' תורה אור.</p>\n<p>94 - ההסכמות הם על הלקוטי תורה ולא על ההוספות.</p>\n<p>98 נדפס בהגהה מיוחדת (לפי דברי הרבני ר' אנשיל אראנאוויטש הי\"ד שהתעסק בזה - תקנו קרוב <b>לשלשת אלפים</b> טעויות!) בסופו בא לוח התיקון.</p>\n<p>99 - נשמט לוח התיקון.</p>\n<p>100 - כמו 98 ולא 8.</p>\n<p>108, 108, 108, 107, 106, 105, 104, 102 - <b>כולם</b> תצלים מכת\"י ר' שמואל סופר הנק' ג\"כ ר' שמואל דער שרייבער.</p>\n<p>109 - נדפסו בו גם מכתבים לקוטים וכו' מרבנו הזקן - בעל התניא - מבנו אדמו\"ר האמצעי, מבני ה\"צמח צדק\" וכו'.</p>\n<p>116 - עדין נמצא בדפוס.</p>\n<p>121 - (4), 58, (6) ע'.</p>\n<p>133 - 132 - טעות. והם - 131'.</p>\n<p>182 -179 ישנם דרושים שנדפסו באחד מאלו ולא בהשני. ובכלל כמה שנויים בהגדות האלו מאחת לחברתה.</p>\n<p>201 - בדף ו, א.. - הוא אגרת בעל התניא הנדפסת באגה\"ק שלו סי' כז.</p>\n<p>226 - עם הקדמה ורשימה ארוכה מאת מכ\"ק אדמו\"ר (רבי יוסף יצחק) מליובאוויטש זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>229 - ההעתקה המסודרת ע\"ס שמות נמצאת עתה ברשות הוצאת קה\"ת ומכינים אותה לדפוס.</p>\n<p>230 - מימיוגרף <b>ולא</b> צילום.</p>\n<p>236 - בצירוף שני מכתבים מבנו אדמו\"ר (רבי יוסף יצחק) זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>251 - הוא מאת כ\"ק אדמו\"ר, (רבי יוסף יצחק) זצוקללה\"ה נבג\"מ זי\"ע מליבאוויטש.</p>\n<p>252 - בצירוף הערות מכ\"ק אדמו\"ר שלום דובער (מהורש\"ב) ומכתב ושתי רשימות מבנו אדמו\"ר, (רבי יוסף יצחק) - זצוקללה\"ה נבג\"מ זי\"ע מליובאוויטש.</p>\n<p>292 - מימיוגרף ולא צילום.</p>\n<p>(ברשימת המחברים והעורכים, ע' 369, לכ\"ק אדמו\"ר ה\"צמח-צדק\", מצאנו שהשמיט המספרים 32, 267).</p>\n<p>ברשימה מיוחדה המוסג\"פ רשמנו מה שנדפס על ידי קה\"ת מאז הופיע החוברת של כ', ובטח ימצא בה תועלת כשיערוך הוספה ל\"שערי חב\"ד\".</p>\n<p>בכבוד ובברכה</p>\n<p><b>מזכירות כ\"ק אדמו\"ר</b></p>\n<p><b>שליט\"א</b></p>\n<h4><i><b>ז'תתקסו</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>החוברת שערי חב\"ד:</b> רשימת דפוסי ספרי חב\"ד, בתוך \"עלי עלין\" תשי\"ב.</p>"],[1200950212,"ז'תתקסז\n\n<p>ב\"ה, ט\"ו סיון, תשי\"ג</p><p>ברוקלין.</p><p>1הנכבד והנעלה, איש המעלה, עסקן במרץ, עומד בפרץ, בן<br>\nפורת וכו', מ' יוסף שי' מורסיאנו ראש ועד העיר ברגנה<br>\nיע\"א</p>\n<p>שלום וברכה!</p>\n<p>מאד שמחתי ויגל לבי לשמוע מהתיקון הגדול שעשו במחנם הט' למנוע חילול שבת וחילול יו\"ט בפרהסיא של בני ובנות ישראל, אשר בהשתדלות מע\"כ וחביריו פסקו תלמידי בית הספר הצרפתי מלילך לביה\"ס ביום השבת קדש ובימי הרגל, ומה גדול שכרו ושכר חבריו שיחיו, שזכו להיות ממזכי הרבים אשר זכות הרבים תלוי בהם, ובטח גם להבא יעמדו על משרמתם לחזק חומת התורה והיהדות וחינוך הכשר בפרט.</p>\n<p>ובטח לא יסתפקו בהשפעתם על בני ובנות ישראל להיות סור מרע, אלא ישתדלו ג\"כ בחלק של ועשה טוב, היינו למלא ימי המנוחה והשמחה בתוכן של קדושה ואור תורה על ידי מסיבות שבת וכדומה.</p>\n<p>והשי\"ת יצליח עבודתם בקדש לטובת הכלל והפרט ויוסיפו כח ואומץ בעבודתם וכמרז\"ל מעלין בקדש, ואשר עסקנות ציבורית זו תמשיך ותשפיע להם ולבני ביתם שיחיו שפע ברכות גם בענינים הפרטיים בגו\"ר.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקסז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 73.</p>"],[1200950213,"ז'תתקסח\n\n<p>ב\"ה, ט\"ו סיון, תשי\"ג</p><p>ברוקלין, נ.י.</p><p>הוו\"ח, אי\"א נו\"נ עוסק בצ\"צ מוה\"ר שלמה<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>איך האב באקומען די ערשטע טעלעגראמע, אז עס באדארף זיין די אפעראציע בא אייער פרוי תחי', און נאכדעם די צווייטע טע\"ג אז עס איז געווען בהצלחה. און איך ערווארט צו נאך גוטע בשורות בפרטיות אין דעם.</p>\n<p>און איך ווינטש אייך, אז פון היינט אן און ווייטער, זאלט איר שטענדיג אנזאגן נאר גוטס, וועגען זיך און פון אייער פאמיליע, און אויך וועגן אייער עסקנות להרים קרן התורה והיהדות בכלל.</p>\n<p>און דעריבער האט מיר פארשאפט פיל פרייד אייער שרייבן, אז איר העלפט הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר אליעזר שי' קאראסיק אין זיין שליחות, און עס [איז] באוואוסט די הבטחת רז\"ל אז ווען מען טוט באמת העלפט השם יתברך.</p>\n<p>המחכה לבשורות טובות,</p>\n<p><b>מ. שניאוסאהן</b></p>\n<h4><i><b>ז'תתקסח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 127.</p>\n<p><b>מוה\"ר שלמה:</b> פערין, לונדון. אגרות נוספות אליו - לעיל ז'תתקסה, ובהנסמן בהערות שם.</p>"],[1200950214,"ז'תתקסט\n\n<p>ב\"ה, כ\"ט סיון, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ צמ\"ס<br>\nחו\"ב וכו' וכו'<br>\nמוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>מכתבו קבלתי. ולכמה סיבות נתעכב המענה, ואת כת\"ר שי' רוב הסליחה ע\"ז.</p>\n<p>... משנה מפורשת היא, שאף שיש לומר מה לנו ולצרה הזאת, בכ\"ז דוחים הטענה.</p>\n<p>וה\"ה בנדון דידן, שכיון שכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע הטיל עליו ענין חשוב ונחוץ למאד, ה\"ז נכנס בענין דמושבע ועומד מהר סיני...</p>\n<p>ומתאים למה שמענו מכ\"ק מו\"ח אדמו\"ר שהקב\"ה אינו \"נשאר בע\"ח\" וע\"פ, מרז\"ל שמדתו של הקב\"ה מדה כנגד מדה, הרי, בודאי, ע\"י שיתן מזמנו לעניני תו\"א, תומשך לו הצלחה בהזמן שישאר לרשותו - לשאר הענינים שלו, הכללים והפרטים. שבסה\"כ הרי עוד ירוויח בזה...</p>\n<p>ו) בהמשך להנ\"ל. זה מזמן שעלה בדעתי שהישיבות דחב\"ד ידפיסו כולם ביחד קובץ תורני ובו חדו\"ת מהתלמידים. ובאופן בלתי רשמי - נא להודיעני חוו\"ד, ואם ישנם בין תלמידי לוד ותו\"א תלמידים המתאימים להנ\"ל.</p>\n<p>ז) במ\"ש אודות מר... שי', שכיון שפעם כבר היתה אצל הפארפ.... ואינה שבעה רצון מפעולתו אז, הנה ברצונם לחכות עוד הפעם על חוות דעתי, אם הוא כמו שכתבתי מכבר שיבקרו אצלו או שחוזר הנני מזה,</p>\n<p>הנה בודאי למותר להודיע את מר... וזוגתו - שיחיו - שאינני פראפ. בכחמת הרפואה, ולא אפילו רופא או פלדשר בזה. ועוד זאת - שכשואלים אצלי חוו\"ד וכותב אני מה שנראה לי הרי אין השואל מוכרח לקיים מה שאמרתי לו, כי הבחירה חפשית אצלו, וכרצונו הטוב יעשה. ובמילא - אין כאן מקום לקפידא וכו' מצדי. ואין להם לעשות איזה פעולה, כדי שלא לפגוע עי\"ז בכבודי כביכול, כי אין מקום להנ\"ל כלל. ואחכ\"ז הנה מה שפעולת פראפ... אז לא השביעה רצונם, הרי עברו כמה שנים מאז. ומה שידוע לי מכמה שפנו לעזרת... שהצליחו. ואיני מוצא טעם, מפני מה בנידון זה יהי' אחרת. ובכ\"א איך שיעשה מר.. וזוגתו שיחיו, הרי יצליחם השי\"ת שיהי' לטוב לפניהם בגשמיות וברוחניות גם יחד.</p>\n<p>ח) ואחרון אחרון חביב. במענה על הודעתו אודות הולדת בן לבנו הוו\"ח אי\"א מוה\"ר אהרון שי', הנה יה\"ר מהשי\"ת שכשם שהכניסוהו הוריו שיחיו לבריתו של אברהם אבינו כן יכניסוהו לתורה ולחופה ולמעשים טובים מתוך הרחבה אמיתית, הן בגשמיות והן ברוחניות. וכת\"ר שי' ירווה רוב נחת חסידותי מכל יו\"ח שי' ויוכל לבשר ג\"כ טובות בהנוגע לב\"ב שי', אשר במדינתנו לפנים.</p>\n<p>בבכת מזל טוב,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקסט</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובנסמןב הערות שם.</p>\n<p><b>משנה מפורשת:</b> סנהדרין לזה, ב.</p>\n<p><b>ששמענו:</b> ראה גם לעיל אגרת ז'תתפב, ובהנסמן בהערות שם.</p>\n<p><b>במדינתנו לפנים:</b> רוסיה.</p>"],[1200950215,"ז'תתקע\n\n<p>ב\"ה ח' תמוז, תשי\"ג</p><p>בשאלתו ע\"ד ס' הישר - יראה מש\"כ בזה בס' שה\"ג לחיד\"א בערכו. ובענין ס' היוסיפון - ידוע שכמה שינויים (וגם זיופים) הוכנסו לתוכו ועניניו דורשים בקורת מומחה במקצוע. ובכללות שאלות כגון אלו ידועה הוראת חז\"ל היכא דעייל ירקא ליעול בשרא וכוורי (שבת קמ, ב). ובפרט כשספק אם גם ירקא הוא.</p>\n<h4><i><b>ז'תתקע</b></i></h4>\n<p>נדפסה בקובץ יגדיל תורה ירושלים גליון טז ע' 10. וראה גם לקו\"ש חט\"ו ע' 368 הערה 17.</p>"],[1200950216,"ז'תתקעא\n\n<p>י\"ב תמוז תשי\"ג:</p>\n<p>התועדויות שמחות ובהתעוררות ובפעולות ממשיות כרצון בעל השמחה.</p>\n<h4><i><b>ז'תתקעא</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 71.</p>"],[1200950217,"ז'תתקעב\n\n<p>ב\"ה, י\"ט תמוז, ה'תשי\"ג</p><p>ברוקלין, נ.י.</p><p>לכל חובבי תורה ומצוה<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>די בית רבקה שולן פאר מיידלעך, וועלכע שטייען אונטער דער אויפזיכט פון <b>\"מרכז</b> <b>לעניני חינוך\"</b>, האבן במשך זיער עלף-יעריקר עקזיסטענץ ערצויגן און ערציען הונדערטער און הונדערטער אידישע טעכטער אין גייסט פון תורה, יראת שמים און מדות טובות, וועלכע זיינען א נחת פאר זייערע עלטערן און א שטאלץ פארן גאנצן אידישן פאלק.</p>\n<p>אין זכות פון זייער הייליגן גרינדער, כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע און אדאנק דער אונערמידלעכער און איבערגעגעבענער ארבעט פון זייערע מנהלים, האבן די <b>בית רבקה</b> מוסדות זיך ערווארבן א נאמען לתהלה ולתפארת אויפן געביט פון חינוך הכשר, ערציענדיק א דור פון פאראנטווארטלעכע רעליגיעזע אידישע טעכטער און מוטערס, פון וועלכע עס איז אין א גרויסער מאס אפהענגיק פון די צוקונפט פון בית ישראל ברוח התורה והמסורה.</p>\n<p>ליידער געפינען זיך איצט די <b>בית רבקה</b> מוסדות אין א קריטישער פינאנציעלער לאגע. די גרויסע לאסט פון די חובות וואס האבן זיך אנגעזאמלט אין די פריערדיקע יארן און די גרויסע הוצאה פון איצט, דראען די יסודות פון זייער עקזיסטענץ.</p>\n<p>באלדיגע הילף איז דרינגנד נויטי[ג].</p>\n<p>איך ווענדע זיך דעריבער מיט א הארציקן רוף צו אלע חובבי תורה ומצוה און בפרט צו די וועמען די מוסדות פון כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע זיינען הייליק און טייער, אז זיי זאלן זיך ווארים אפרופן אויף דעם עמערדזשענסי קאמפיין פון די בית רבקה מוסדות, און מיט אן אפענער האנט און ווארים הארץ זיך באשטייערן אליין און אויך זאמלען בא זייערע פריינט און באקאנטע, אום צו ראטעווען די בית רבקה מוסדות, און צו געבן די דאזיקע וויכטיקע מוסדות די מעגלעכקייט ווייטער אנצוגיין מיט זייער חינוך-הכשר - ארבעט.</p>\n<p>און בזכות זה וועט השי\"ת העלפן די אלע שטיצער און מיטהעלפער אין וואס זיי נויטיקן זיך, בגשמיות וברוחניות.</p>\n<p>הדו\"ש ומברכם בגו\"ר,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעב</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950218,"ז'תתקעב*\n\n<p>ב\"ה, כ\"ט תמוז, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוה\"ר שלמה שי'</p>\n<p>שלום וברכה!</p>\n<p>בנועם קבלתי מכתביו מיו\"ד כ' וכ\"ד תמוז עם המצורפים אלי'. ות\"ח ביחוד על החוברת דל\"ג בעומר שנדפסה בטוב, וטוב טוב עשה שהוסיף השורות האחדות שענין השיחה כל השנה זמנה היא, אף שצריך עיון אולי הי' כדאי שיהי' זה בראש החוברת.</p>\n<p>ובטח בהזדמנות הבאה ימלא באיזה אופן הפיצו.</p>\n<p>ב) איני יודע באיזה קצה צריך לזרז אודות רשיון הר\"ן שי' פינסאן - אם במרוקה או בצרפת, ובטח יתדבר בזה עם הרה\"ג והרה\"ח כו' מוה\"ר רבא\"ג שי'.</p>\n<p>ג) כנראה ממכתב הרה\"ח כו' מוהר\"ס שי 'ליבעראוו, חוג עבודתו לא נתברר כ\"כ.</p>\n<p>והפלא והתמי' מהו הסיבה לזה. אף שכותב הנני בזה להרה\"ג כו' והרה\"ח הרבא\"ג שי' - בכ\"ז, מפני הסדר, הנני מזכיר זה גם לכת\"ר שי'.</p>\n<p>ד) מוסג\"פ רשימת המשך המאסר שכנראה בטעות שכחו לצרפה למכ' הקודם.</p>\n<p>ה) זה איזה פעמים שאלתי, שלכאורה, כדאי שבמכ\"ע המופיעים במרוקה, שבטח ישנם כאלה שנקראים ע\"י היהודים, ראוי להשתדל שמזמן לזמן יודפס שם ע\"ד הפעולות, וכן גם מעניני חסידות הדרכותי' ומנהגי' ודברי הימים שלה - מתאים לאופי הקוראים וסוג העתון.</p>\n<p>ו) נהניתי ממה שבין השיטין של מכתבו ניכר שגם בעיני בשר רואה הוא הצלחת הענינים, ויה\"ר מהשי\"ת שהן ההצלחה והן הראי' שלו בענינים שעדיין לא ראה הנ\"ל, תבואנה גם הם בנראה ונגלה בהקדם.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובעניניו הפרטים,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעב*</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר שלמה שי':</b> מטוסוב. אגרות נוספות אליו - לעיל ז'תתקנג, ובהנסמן בהערות שם.</p>\n<p><b>רשיון... פינסאן:</b> ראה לעיל ח\"ז אגרת ב'יח.</p>"],[1200950219,"ז'תתקעג\n\n<p>ב\"ה, א' מנ\"א, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוה\"ר שלום שי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו מכ\"ה תמוז, בו כותב ע\"ד הסברא לסדר המשך הכתות של ישיבת אחי תמימים במחנם הט', נוסף על אלו שישנם עתה, אשר כפי השערתו, יכול לעכב איזה תלמידים הנמצאים בכתות הגבוהות שימשיכו לימודם בישיבה גם להבא, ושואל אם אפשר יהי' לשלוח מכאן 7 - 6 תלמידים עם ראש ישיבה למחנם הט' בכדי להשגיח על תלמידים הנ\"ל.</p>\n<p>והנה בודאי אשר להוסיף כתות גבוהות יותר נכון במאד מאד (לקו\"ת שלח לח, ג).</p>\n<p>ובנוגע להענין דשילוח תלמידים מכאן, הנה צריך להתדבר בזה עם הנהלת הישיבה דכאן, אבל, לכאורה, כמה קישויים בדבר. והעיקר, אשר לכאורה הורי הנ\"ל, אינם צריכים להסכים ע\"ז, כיון שזהו היפך דרך הרגיל, כי נוסעים מעיר קטנה לעיר גדולה ומישיבה קטנה לישיבה יותר גדולה - ולא להיפך. ובודאי זוכר ג\"כ הנסיון בשיקאגא עד\"ז ושלא הצליח, אף כי לא כל התנאים שוים, משא\"כ - אם היו מוסיפים אומץ אודות הנערים ובחורים בעירו, ומסתברא שזהו נקל הרבה יותר. ובכ\"א איני שולל את הענין, וכנ\"ל שיתדבר עם הנהלת הישיבה.</p>\n<p>שיעשה מר דאן שי' מקוה בחצר כת\"ר - ובטח יהי' בלא מחלוקת - נכון במאד ומכל הצדדים.</p>\n<p>בברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעג</b></i></h4>\n<p>מצילום האגרת.</p>\n<p>מוה\"ר שלום שי': פויזנר. אגרות נוספות אליון - לעיל ז'תשסז, ובהנסמן בהערות שם.</p>\n<p><b>המשך הכתות:</b> ראה גם לעיל אגרת ז'תתקלט.</p>\n<p><b>דשילוח תלמידים מכאן:</b> ראה לקמן אגרת ז'תתקצז.</p>\n<p><b>הנסיון בשיקאגא:</b> ראה תולדות חב\"ד בארה\"ב ע' רסה-ו.</p>"],[1200950220,"ז'תתקעד\n\n<p>ב\"ה, ח' מנ\"א, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוהרנ\"ן שי'</p>\n<p>שלום וברכה!</p>\n<p>נתקבל מכתבו מה' מנ\"א וכן שתי החוברות- חשבון הכנסה והוצאה בעד חשון-אייר שנה זו. ות\"ח ת\"ח.</p>\n<p>בטח כמו שכותב במכתבו מכבר, קבלו כמה תלמידים לימי החופש, אשר אז יש לקוות שמקצתם ישארו גם אח\"כ ללמוד, ועכ\"פ באהלה של תורה. והשי\"ת יצליחם.</p>\n<p>מוסג\"פ הקונטרס שהו\"ל זה עתה. ובטח יזכה בו את הרבים. והשי\"ת יהפוך ימים אלו לששון ולשמחה בעגלא דידן.</p>\n<p>הת' דאיספניא - כדאי לקבלם - (וזהו האלטן גם את אחיהם). הת' דמרוקו שאצלם ורוצים לנסוע- נחוץ למנעם מזה (בדרכי נועם) - מלבד במקום שיש חשש קלקול להכלל, ח\"ו.</p>\n<p>בברכת הצלחה בגו\"ר ובפרט בריאות הנכונה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 128.</p>\n<p><b>מוהרנ\"ן:</b> מוה\"ר ניסן נמנוב. אגרות נוספות אליו - לעיל ז'תתט, ובהנסמן בהערות שם.</p>"],[1200950221,"ז'תתקעה\n\n<p>ב\"ה, כ\"ג מנ\"א, תשי\"ג</p><p>ברולקין.<br>\nמרת מרים מריישא תחי'</p>\n<p>ברכה ושלום!</p>\n<p>זיינער צייט האב איך באקומען אייער בריף אין וועלכן איר פרעגט מיין מיינונג ווען קען בעלה הרב שי' קומען אין פאריז.</p>\n<p>די זעלבע פראגע האב איך באקומען פון אייער מאן הרב שי' און האב עם געענטפערט, אז דאס ווענדט זיך אן דעם מצב אויפן ארט, וואס ער דארף באווארענען צוויי זאכן: א) אז זיין אוועקפארן זאל ניט שאדן טאן די חדרים און ישיבות דארטן. ב) אז ער זאל קענען האבן די צוריק איינרייזע וויזע קיין מאראקא אן שוועריגקייטן. און וויבאלד השי\"ת האט עם מזכה געווען, און דורך עם אויך די גאנצע פאמיליע מיט דעם זכות צו מיטבאטייליקן זיך אנפירן די מוסדות פון מיין שווער כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע איז זיכער, אז דאס איז די וועג דורך וועלכער אייער מאן הרב און די גאנצע פאמיליע וועלן האבן די הצלחה וברכה אין דעם וואס יעדער נויטיגט זיך. דעריבער דארפמען דאס אנהאלטן מיט אלע כוחות.</p>\n<p>און השי\"ת זאל אייך אלעמען העלפן עס זאל דאס אייך אנקומען גרינג.</p>\n<p>זעלבסטפארשטענדלעך, אז אין צוזאמענהאנג מיט דאס אויבן געזאגטע, ווענדעט זיך אויך די באשטימונג פון דער צייט פון אייער טאכטערס חתונה בשעה טובה ומוצלחת.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א,</p>\n<p>המזכיר: א. קווינט</p>\n<h4><i><b>ז'תתקעה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 99, מצילום האגרת.</p>\n<p><b>מרת מרים מריישא:</b> ליברוב, שבעלה הרב סעדי' הי' באותה שעה בשליחות במרוקו, ורצה לבוא לפריז לחתונת בתם תי'.</p>"],[1200950222,"ז'תתקעו\n\n<p>ב\"ה, כ\"ג מנ\"א תשי\"ג</p><p>ברולקין.</p>\n<p>שלום וברכה!</p>\n<p>... ומה ששואל אצלי אודות ההיתר שקיבלה אשתו בזיווג שני, הנה זה צריך לברר אצל אחד הרבנים על אתר, המכירים את אלו שנתנו ההיתר שבטח הם בני סמכא, ובמילא אין אחר מעשה בי\"ד כלום. וצריך הנ\"ל, להיות חזק בבטחונו בהשי\"ת שימלא צרכיו בהמצטרך לו, אלא שצריך לחזק ההתקשרות עם השי\"ת, ע\"י תוספת בענינים של תורה ומצות. והשי\"ת יצליחו, וימלא ימי הריון בתו תחי' כשורה ובנקל, ותלד זחו\"ק כשורה ובקל.</p>\n<p>בברכה - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעו</b></i></h4>\n<p>נדפסה בקובץ יגדיל תורה ירושלים גליון יט ע' 12 והשולמה ע,פ צילום האגרת.</p>"],[1200950223,"ז'תתקעו*\n\n<p>ב\"ה, כ\"ג מנ\"א, תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו...</p>\n<p>ובמענה על סיום מכתבו, הנה סיום מכתבו נכתב בעידנא דריתחא, או, עכ\"פ בזמן שהלב הי' שליט על המוח. ותקותי שלעת הזאת הנה גם הוא רואה, אשר שאלתו ובקשתו שכותב אין לזה מקום כלל, כי כאשר זיכהו השי\"ת, אותו וכל ב\"ב שיחיו, להיות דבוקים באילנא דחיי, מוסד כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר זהו הצלחתו בכלל ובפרט, הרי מובן ופשוט שצריך להאחז בזה, ואדרבה להוסיף כח ועוז, אלא שבאם, ככל מעשי בנ\"א, יש חסרונות ודברים שאינם כהוגן - צריך לחפש הדרכים והאופנים איך למנעם. והאריכות בזה בודאי אך למותר. ויוסיף אומץ בעבודתו אליבא דנפשי', ובד\"מ כו\"כ ענינים וועלען זיך אויסגלייכען.</p>\n<p>ב) בנוגע לתוכן מכתב... הנה מוכרחני להגיד, וכמו שכתבתי ג\"כ להרה\"ג הרה\"ח...</p>\n<p>שי', כי מפני סדר העבודה מוכרח שכל ההשפעות בפועל ילכו דרך מרכזנו.. אף שבנוגע לאופן וכמות השפעה יתדבר [בזה] עם הרה\"ג הרה\"ח... שי'. ואי אפשר לעשות, ובפרט כלפי הדזוינט כו\"כ צנורות וכו'. מובן מעצמו, שהשפעה צ\"ל באופן כזה שלא יהי' בזה מיעוט דמות המקבל (שמפני כמה טעמים יש להתנהג בזה ע\"פ נגלה וחסידות וגם בהתאם לתועלת העבודה) וכמה דרכים בזה, שהמקבל זאל זיך ניט פילען געטראפען, ובודאי האריכות גם בזה למותר.</p>\n<p>בברכת הצלחה בעבודתו בקדש ובעניינם הפרטים,</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ\"ב. נתקבלה חבילתה ספרים ששלח [...] תמוז, ובטח ימשיך גם על להבא. ומ\"ש שיש מהם מפורסמים, הנה בדורנו זה גם ספרים מפורסמים אזלו מהשוק, ובכל הספיקות בכגון דא - יש לפשטם לקולא, היינו לשלחם לכאן.</p>\n<h4><i><b>ז'תתקעו*</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>סיום מכתבו:</b> על הקשיים בעבודת השליחות.</p>\n<p><b>חבילת הספרים ששלח:</b> עבור הספריה.</p>"],[1200950224,"ז'תתקעז\n\n<p>ב\"ה, אדר\"ח אלול, תשי\"ג</p><p>ברוקלין.</p><p>מרת חנה תחי'</p>\n<p>ברכה ושלום!</p>\n<p>איך בין געווען צופרידען צו באקומען אייער בריף פון ט\"ו מנ\"א אין וועלכען איר שרייבט וועגען אייער צוקונפטיגער ארבעט אין די ענינים פון טהרת המשפחה און האט אויך איבערגעדרוקט די בראשור פון ד\"ר סמיטליין.</p>\n<p>אין דער פראגע וועגען א באגלייט בריף צו דער בראשור, זעלבסט פארשטענדלעך אז דער באגלייט בריף דארף זיין אין ענגליש און דאס אומגעפער דארף זיין דער אינהאלט.</p>\n<p>היות מיר זיינען זיכער אז די בייגעלייגטע בראשור וועט אייך געוויס אינטרעסירען, ערלויבען מיר זיך צו שיקען זי אייך און אויב מיר קענען אייך דינען אין צוזאמענהאנג מיט דעם בנוגע צון די דינים און אדרעסין א.א.וו. זייען מיר גרייט מיט צופרידענהייט דאס צו טאן.</p>\n<p>איך בין אויך געווען צופרידען צו לייענען אין אייער בריף, אז עס איז פאראיבער דער עגמת נפש וואס איר האט געהאט אלס פארזיצערין, און השי\"ת זאל אייך געבען הצלחה אין אייער ארבעט אויך אויף ווייטער,</p>\n<p>בברכת הצלחה וכתיבה וחתימה טובה לשנה טובה</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעז</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מרת חנה תחי':</b> גולדשטיין. אגרות נוספות אליה - לעיל ז'תתקמז, ובהנסמן בהערות שם.</p>\n<p><b>בראשור פון ד\"ר סמיטליין:</b> ראה אג\"ק אדמו\"ר מוהריי\"צ נ\"ע ח\"ב אגרת תקד.</p>"],[1200950225,"ז'תתקעח\n\n<p>ב\"ה, ט' אלול, תשי\"ג</p><p>ברוקלין.</p><p>1ה0נהלת רשת אהלי יוסף יצחק אשר באה\"ק ת\"ו<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מאשר הני קבלת מכתביהם מד' ט\"ז כ\"א כ\"ב כ\"ג כ\"ט ול' מנ\"א עם המצורפים אליהם, ת\"ח ת\"ח על הבשו\"ט אשר רואים הצלחה בעבודתם ומרגישים אשר ברכת נשיאנו שעל שמו נקראים המוסדות שורה עליהם ומשפיע ברכה והצלחה, כן יוסיף השי\"ת לימים יבואו וכפסק רז\"ל, מעלין בקודש.</p>\n<p>ב) אחכה לבשו\"ט בהקדם מהסיום הטוב בענין התשלומין שעליהם לקבל</p>\n<p>מהמוסדות שנזכרו במכתבם וכן מהמשך בענין הצעה ליסוד בית ספר בסביבות חיפה.</p>\n<p>ג) זה מזמן נשלחו סידורים וספרנו להמו\"ס הוו\"ח אי\"א נו\"נ מוה\"ר יהודא שי' שמוטקין וכותבים עתה אליו שימסור לצרכי הרשת סך מסויים של סידורים וספרנו מתאים לבקשתם במכתבם.</p>\n<p>... ה) נבהלתי לקרות במכתבם אודות התפטרותם של הוו\"ח אי\"א נו\"ע מו\"ה...ש י'... ממשרתו, וכן אביו מהסיוע שלו. ואין סיבת הבהלה שלי פן יחסר סיוע בהרשת, כי מובטחני בכ\"ק מו\"ח אדמו\"ר שימלא את זה, אבל כבר ידוע פתגם ופירוש כ\"ק אדמו\"ר מוהר\"ש עה\"פ ריוח והצלה יעמוד ממקום אחר ואת ובית אביך תאבדו <b>את הזכות לזה</b>...</p>\n<p>ו) נהניתי ממ\"ש אשר נהגו בשתי חתימות על הטשעקין, וכמרז\"ל בענין צדקה שצריכה להיות בשנים.</p>\n<p>ז) בטח יעמדו בקישור עם הרה\"ג והרה\"ח כו' וכו' מוה\"ר ישראל אביחצ[י]רא שי', כי מלבד המכתב שמבקשים ממנו הנה יש לו השפעה בחוג הספרדים... הקירוב הדעת משני הצדדים בטח יבוא תועלת.</p>\n<p>... י) טוב ונחוץ שיארגנו כל המורים השייכים אלינו ויתחילו בלימודים לא בכ\"ה תשרי, שזהו התחלת זמן הרשמי, אלא קודם לזה, כפי צורך הענינים. ועליהם לגייס טובי המורים שהיו אצלם עד עתה וכן המורים מבין אנ\"ש הנחוצים לעבודה בהרשת, וכמו שסו\"ס שלמו החובות דשנת תשי\"ג, הרי בודאי יקבלו המורים בשנת תשי\"ד את משכורתם, ובודאי באופנים טובים יותר מאשר עד עתה, ומתאים לבקשתם שלחתי ג\"כ דעתי זו במברק וז\"ל:</p>\n<p>\"התחלת הלימודים במוסדות הרשת באלול נכונה במאד, ובטחוני חזק שהמורים מאנ\"ש, יגייסו עצמם לתכנית זו כפי הצורך, ובודאי תהי' משכורתם בטוחה. ואחכה לבשורות טובות. חתימתי\".</p>\n<p>... בברכת הצלחה בעבודתם הקדושה בדרך למעלה מן הטבע, ובטח ינצלו בזה גם את הימים של שנת תשי\"ג שהיתה שנת הצלחה בהמקומות שהתחילו עכ\"פ במעשה בפועל, ובברכת כוח\"ט לכאו\"א מהם וב\"ב שיחיו.</p>\n<h4><i><b>ז'תתקעח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 129.</p>"],[1200950226,"ז'תתקעט\n\n<p>ב\"ה, יו\"ד אלול, תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>זה מכבר שכתב לי הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוהרב\"א שי' גאראדעצקי, אשר בתוך שאר סדרי העבודה, הנה - הוא לקח על עצמו תפקיד מיוחד בעבודת הרשת.</p>\n<p>והנ\"ל, כתב עד\"ז בקורת רוח, ומה תמהתי לקבל ידיעה, אשר התפטר ממשרתו זו.</p>\n<p>כיון שאיני יודע פרטי הדברים, איני רוצה לכתוב עד\"ז חוות דעתי במשקל הראשון.</p>\n<p>ואחכה למכתב מבאר הנ\"ל, או מה טוב - מכתב מודיע שחזר למשמרתו ולאיתנו, (ויעויין בענין איתן שבנפש מאמר רבינו הזקן הנדפס בקונטרס תורת החסידות ובמאמרים שנסמנו שם. ונדבר ע\"ז גם בד\"ה ראה דש\"ק מברכים אלול השתא), היינו שבאיתן ולתוקף הנשמה יפעול בהתרחבות ובהתפשטות, ובמילא גם בהצלחה מופלגה. והשי\"ת ימשיך לו הצלחה בעבודתו בקדש, ובמילא גם בעניניו הפרטים.</p>\n<p>בברכת כוח\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקעט</b></i></h4>\n<p>מצילום האגרת.</p>"],[1200950227,"ז'תתקפ\n\n<p>ב\"ה, יו\"ד אלול, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר מנחם<br>\nזאב שי' הלוי</p>\n<p>שלום וברכה!</p>\n<p>בעתו קבלתי מכתביו מי\"ז וכ\"ב מנ\"א ובטח יודעי בשו\"ט מעניניו הפרטים.</p>\n<p>אודות ביקורו של מר... שי' כאן, הנה ע\"פ [מה] שכתבתי מכבר, שאינו ענין בזריעה לבדה, שזורעים מיט א ווארט, אלא שאח\"כ צריך להשתדל שיבוא לפועל, בכל אחד לפי ענינו.</p>\n<p>ותחלת ההשתדלות בזה - ששואלים אותו מה ששמע וכו' ובמילא יש להנ\"ל, הזדמנות לספר את אשר בלבבו, והשואל יכול למלאות ולקרב בפועל כו'.</p>\n<p>מ\"ש שהר\"א שי' שטערן שו\"ב מו\"ל בקרוב ספר ספורי מעשיות צדיקים, הי' צריך לעוררו שירשום בשוה\"ג או בסוף הספר ממי שמע הסיפור, ואם הוא בר סמכא, ועד כמה כו'.</p>\n<p>בנוגע להרב...שי', הנה צריך הי' לעוררו - הן בדבר השפעתו על בנו שנסע לאה\"ק ת\"ו, וכן בענין המקוה במחנו, אשר בשני הענינים דברו בקרירות לבד שהסברתו היתה, כמאמר הברייתא - אנו אין לנו להשען אלא על אבינו שבשמים, הרי ידוע פתגם כ\"ק מו\"ח אדמו\"ר שהברייתא מביאה מאמר זה בהמשך לכל הענינים של חבלי משיח, מה שהיוקר יאמיר וכו'.</p>\n<p>ת\"ח על מ\"ש אודות תלמידי הישיבה, ובטח ידוע מהנעשה עמדם ובפרט בימי אלול ותשרי, ובטח נשמע גם בישיבתם אשר היתה כאן הצעתי שיוסיפו תלמידי הישיבה (7והר\"י, והנהלה לא כש\"כ) בלימוד עבודה'דיקע מאמרים ביחוד בימים אלו, ומה טוב אשר גם במאנטרעאל יעשו כזאת ומה טוב אשר גם בשאר המקומות.</p>\n<p>... בודאי מותר לו להצטדק על מ\"ש בענינים הנ\"ל, כי נכון הדבר במאד, והלואי שלעתים תכופות יותר בפרטיות יותר.</p>\n<p>השי\"ת יזכהו לבשר טובות מעניניו הפרטיים.</p>\n<h4><i><b>ז'תתקפ</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ה ע' 102, מהעתקה. והיא השלמה לארת ב'רכז דלעיל ח\"ז.</p>\n<p><b>מוה\"ר מנחם זאב שי':</b> גרינגלס. אגרות נוספות אליו - לעיל ז'תתשעד, ובהסמן בהערות שם.</p>\n<p><b>ממי שמע הסיפור:</b> ראה גם לעיל חי\"א אגרת ג'תו, ובהנסמן בהערות שם.</p>\n<p><b>הברייתא:</b> סוף סוטה.</p>\n<p><b>פתגם:</b> ראה גם לעיל חי\"ב אגרת ג'תתקכה.</p>"],[1200950228,"ז'תתקפא\n\n<p><i>[י\"ג אלול תשי\"ג]</i></p>\n<p>... עתה נתקבל מכ' בו מודיע ע\"ד בניו שיחיו, ובטח משתמש בהשפעתו עליהם שיהיו צנורות להפצת המעיינות חוצה, ובפרט בנו הבכור מר דוד שי' העובד בצבא, אשר שם מוכרח הדבר ביותר להאירם במאור שבתורה זוהי תורת החסידות והנהגה החסידותית און ארום חסידות. ומי יודע אם לעת כזאת הגיע למשרתו זו. וידועה הבטחת אדמו\"ר הזקן לכל אלו המשתדלים בעניניו - שהבטיחוהו שיצליחו בזה.</p>\n<p>בהערתו, מדוע לא סימנו בסוף פ' פקודי סכום פסוקי הסדרה, הנה יש לחפש בדפוסים הראשונים,כי לדעתי אין זה אלא השמטת המדפיס, ונמשך הדבר כן גם אצל שאר המדפיסים שבאו אחריו,</p>\n<p>ואולי אפשר שהי' כתוב \"בלי כל סימן\", והכוונה בזה היתה שיש בסדרה צ\"ב פסוקים, ובא הבחור הזעצער ותפס את הענין כפשוטו שאין כאן סימן, והשמיט מלות אלו מחסרון ידיעה.</p>\n<p>בברכה לנחת חסידות מכל יו\"ח שיחיו,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקפא</b></i></h4>\n<p>חלקה נדפסה בס' תו\"ת על הש\"ס בסופו ובלקו\"ש ח\"ו ע' 408 והושלמה ע\"פ צילום האגרת.</p>\n<p>האגרת היא אל מו\"ה אלכסנדר סענדר יודאסין. אגרות נוספות אליו - לעיל חי\"ח ו'תקנז, ובהנסמן בהערות שם.</p>"],[1200950229,"ז'תתקפב\n\n<p>ב\"ה, י\"ד אלול, תשי\"ג</p><p>ברוקלין.</p><p>הרב הגאון והרה\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nצנמ\"ס כו' וכו'<br>\nמוהרש\"י, שי'</p>\n<p>שלום וברכה!</p>\n<p>... מה ששואלני כת\"ר שי' למ\"ש לו מכבר ע\"ד ספרו בפרק ל\"ג בעומר, במכתבי אליו, הנה הראיתי מקום לשו\"ת דברי נחמי' שהעיר עדמש\"כ בפע\"ח שכ\"ב פ\"ז. כן אולי כדאי שבהפרקים דימים נוראים וחגה\"ס - יכניס בהם ענינים המתאימים ממנהגי חב\"ד ומקורותיהם עפ\"י המודפס בקונטרסי ר\"ה וחגה\"ס דשנה העברה ושלפני זה.</p>\n<p>נהניתי ממ\"ש כת\"ר שנסע למקום הבראה. והשי\"ת יחזק את בריאותו ויוסיף אומץ בפעולות לתורה ולמצוה וליראת שמים.</p>\n<p>בברכת כוח\"ט לשנה טובה ומתוקה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>נ\"ב. מוסג\"פ הקונטרס שהו\"ל זה לא כבר.</p>\n<h4><i><b>ז'תתקפב</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובהנסמן בהערות שם.</p>\n<p><b>מ\"ש לו מכבר:</b> לעיל ח\"ג אגרת תפה.</p>\n<p><b>ספרו:</b>המועדים בהלכה.</p>"],[1200950230,"ז'תתקפג\n\n<p>ב\"ה, כ\"ג אלול, תשי\"ג</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני מכתבו מעש\"ק עם הפ\"נ.</p>\n<p>ועליו הי' להסביר ל... שי' אז דאס איז ניט קיין סדר להתנהג ככה עם השי\"ת, אז פריער ווען די טאכטער איז נישט היינט געדאכט ניט געזונט זאגט מען צו, און דערנאך ווערט מען שוואך אין דעם צוזאג און מען ווארט ביז ר\"ל עס קומט א נייער מיחוש און מען דערמאנט זיך אויף דעם צוזאג.</p>\n<p>ו[דברים] אלו צריך להסבירו בדרכי נועם ובנחותא וכו'. והשי\"ת יצליחו למצוא האותיות המתאימות ואשר אצל... שי' יהיו אודנין פתיחין.</p>\n<p>ת\"ח על המשך השיחות שקבלתי, ובטח [י]משיך בזה גם על להבא (הסיפור שלו אודות הנסיעה של כ\"ק אדמו\"ר מוהרש\"ב ובנו כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע להאלמנה ובנותי' וכו' שמעתי מכ\"ק מו\"ח אדמו\"ר אודותם אף כי איזה פרטים הם בשינויים).</p>\n<p>ולקראת השנה החדשה הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולב\"ב שיחיו ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקפג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 74. והיא אל מוהרר\"נ הכהן. אגרות נוספותא ליו - לעיל ז'תתעח, ובהנסמן בהערות שם.</p>\n<p><b>הסיפור:</b> שבספרו שמועות וסיפורים הוצ' תש\"נ ח\"א ע' 125.</p>"],[1200950231,"ז'תתקפד\n\n<p>ב\"ה, כ\"ז אלול, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר משה פנחס שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>נהניתי בקבלת מכתבו מכ\"ג אלול, ואף שאין הזמן גרמא כלל לכתיבת מכתבים, הנה מהנעימות והשמחה אשר גרם לי בהידיעה מהתענינותו ופעולותיו לסלק את המגיע להרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ כון' מוהרי\"ד שי' גראנער, יצאתי מגדרי ומגדר הזמן וכותב הנני שורותי אלה, ויה\"ר מהשי\"ת אשר ילך בדרכו זו ובתוס' אומץ כו', ובפרט בתור כהן, שע\"י יושפע המגיע גם לשאר השייכים ועובדים בישיבת תו\"ת באופן המתאים, ואין לך דבר העומד בפני הרצון.</p>\n<p>ובהתאם לזה:</p>\n<p>ב) כדאי הי' שישתדל גם בענין הבא לקמן, והוא כי בטח ידוע לו אשר הרה\"ח כו' מוהר\"ש קונטורוב ע\"ה הנה כיון שע\"פ צוואתו קצב סכום בשביל הישיבה תו\"ת ולבניו לא הי' איכפת להם אם הי' נקבר בהלאט שקנה בביה\"ח אחר, ובמילא לא הי' מקום לבקש מאתם לשלם בעד הקרקע דביה\"ח אגודת חב\"ד, וסו\"ס קבור הוא עד עתה בקרקע שלא שלמו בעדה, און מיט אזעלכע זאכען דארפמען זיך ניט טשעפען. ולכן הי' מהנכון וטוב, ואולי גם מוכרח, שמהסכום אשר הקציב המנוח הנ\"ל, בעד הישיבה, תשלם הישיבה המחיר במקח השוה מה שמשלמים בעד קרקע כזו, ועוררתי עד\"ז עתה ולא קודם מכמה סיבות. והעיקר כיון שכבר נכנס להישיבה חלק מהעזבון של הנ\"ל צריך לסדר את הנ\"ל, מובן שגם מצד אחר אעורר אודות זה, אבל מגלגלין זכות ע\"י זכאי, ובטח מצדו יעשה התלוי בו.</p>\n<p>ולקראת השנה החדשה הבאה עלינו ועל לכל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולב\"ב שיחיו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.</p>\n<p>בברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקפד</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר משה פנחס:</b> כץ. אגרות נוספות אליו - לעיל ז'תשסה, ובהנסמן בהערות שם.</p>"],[1200950232,"ז'תתקפה\n\n<p>ב\"ה, שלהי אלול, תשי\"ג</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ כו'<br>\nמוה\"ר חיים שאול שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו וכן הפ\"נ שלו עם תשורתו היקרה מכתב כ\"ק אדמו\"ר מוהר\"ש נ\"ע, ות\"ח ת\"ח על תשורתו זו, ובטח ידוע לו מי הוא שאליו נכתב המכתב ויכתבו עד\"ז בהזדמנות הבאה.</p>\n<p>דא\"ג - מ\"ש בשולי המכתב בדבר התרנגולים, הנה כנראה הכוונה למכתב כ\"ק אדמו\"ר מוהר\"ש שנכתב להרה\"ג הרה\"ח הרד\"צ נ\"ע חן ונמצא באוסף כי\"ק של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ולקראת השנה החדשה הבאה עלינו ועל כל ישראל לטובה ולברכה, הנני בזה להביע ברכתי לו ולב\"ב שיחיו, ברכת כתיבה וחתימה טובה לשנה טובה ומתוקה בגשמיות וברוחניות.</p>\n<p>בברכה ובת\"ח,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקפה</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר חייםש אול:</b> ברוק. אגרות נוספות אליו - לעילחי\"ט ז'פא, ובהנסמן בהערות שם.</p>\n<p><b>בשולי המכתב:</b> אג\"ק שלו אגרת ו*.</p>\n<p><b>כנראה הכוונה למכתב:</b> שם אגרת ו.</p>"],[1200950233,"ז'תתקפו\n\n<p>ב\"ה, ד' תשרי, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת צעירי אגודת חב\"ד אשר בעיה\"ק<br>\nירושלים ת\"ו,<br>\nד' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבם מכ\"ד אלול אחרי השתיקה והפסק הארוך, והנה אין הזמן גרמא לכתיבת מכתבים עתה ומוסג\"פ מכתבי כללי אשר ישמש ג\"כ בתור מכתב פרטי אליהם, ובטח יפרסמוהו באופן המתאים בחוגים היותר רחבים.</p>\n<p>לפלא אשר לאחר שכתבו לי שעומדים הם בקישור עם צעירי אגו\"ח דתל אביב ובכ\"ז לא השתתפו בבטאון שי\"ל לח\"י אלול באופן ניכר ובטח יתקנו את זה בהזדמנות המתאימה.</p>\n<p>בשאלתם אם לשלוח לכל הר\"י ומנהלי הישיבת מכתב המובא בתחלת קונטרס העבודה ועץ חיים, הנה לדעתי עדיין מוקדם הזמן לזה, אף שיש לפרסם את הנ\"ל בין חבריהם ומכיריהם מבלי הפליה באיזה ישיבה הוא לומד, אבל לעלות בחומה וברעש איני יודע אם יצליח בזה בנוגע לפועל הרי זוהי תכלית כל העבודה שתבוא למעשה בפועל ואם אפשר בקול דממה דקה ה\"ז הוא טוב וכמרז\"ל והלכת בדרכיו מה הוא כו' והלא לא ברעש ולא ברוח ולא באש כו' כ\"א בקול דממה דקה.</p>\n<p>בברכת חתימה וגמר חתימה טובה לכל אחד ואחד מהם בפרט ולכולם ביחד אשר חפץ ה' בידם יצליח להפיץ המעיינות חוצה ולעשות מהחוץ פנים ומהמעינות המים אשר לים מכסים כי מלאה הארץ דעה אתה ה'.</p>\n<p>נ\"ב. לפלא שאין מזכירים במכתבם אודות תכנית עבודה לחדש תשרי ובטח לא יהי' חסרון בפועל רק שלא כתבו אודות זה.</p>\n<h4><i><b>ז'תתקפו</b></i></h4>\n<p>מהעתק המזכירות.</p>"],[1200950234,"ז'תתקפז\n\n<p><i>[נוסח המברק להת'... מוצאי יוה\"כ ה'תשי\"ד, בנסעם על האני' \"אליזבט\"]</i></p>\n<p>\"חתימה וגמר חתימה טובה להם ולשכניהם הנוסעים. יסבירו להם שבהשגחה פרטית נמצאים יחד לתועלת כולם בהתאמצות בתשובה להשי\"ת בחרטת העבר וקבלה [...].</p>\n<h4><i><b>ז'תתקפז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 131.</p>"],[1200950235,"ז'תתקפח\n\n<p><i>[ב' מר חשון תשי\"ג]</i></p>\n<p>... מובן, ובפרט ע\"פ מרז\"ל - ב\"מ פ\"ו ריש ע\"א - שאין לזה גבול. ואולי [ה]טענה צודקת לפ\"ע, אבל ידועה הנהגת נשיאינו רבוה\"ק שאחזו תמיד בדרך המיצוע. וכן בודאי נוהגים ג\"כ אנ\"ש אשר על אתר שם...</p>\n<h4><i><b>ז'תתקפח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ג ע' 47.</p>\n<p><b>שאין לה גבול:</b> הוצאותה חתונה. וראה גם לעילח\"י אגרת ג'צב.</p>"],[1200950236,"ז'תתקפט\n\n<p>ב\"ה, כ\"ג מ\"ח, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>איך האב באקומען אייער בריף פון ט' חשון וואס בעט אנטשולדיגונג פאר אייער שרייבן ניט-גוטע פריילעכע ידיעות.</p>\n<p>על פי רוב איז אזוי אז ווען מען <b>דארף</b> שרייבן און מען לייגט דאס אפ [פון] טאג צו טאג, קומט אן דענסטמאל א סיבה וועלכע צווינגט צו שרייבן, דאגעגן ווען מען שרייבט אין צייט, ווען עס איז פאראן גוטע בשורות, אויך דענסטמאל אנזאגן, און ניט ח\"ו אין א פארקערטן פאל, פארשפארט מען מלמעלה צו אנווענדן אנדערע מיטלען וועלכע צווינגען צו שרייבן און פארבינדן איינעם מיטן אנדערן.</p>\n<p>איך האף אז צו דער צייט פון אנקומען פון דיזן בריף איז דער ענין וועגן וועלכן איר שרייבט שוין איינגערארענט גיווארן צום גוטן, און האפענטליך וועלן אויך די אנדערע ענינים [ווערן] כדבעי לאט לאט. און איך ערוואט צו הערען פון אייך גוטע בשורות אז אלעס איז שלום בגשמיות והכל שלום ברוחניות.</p>\n<p>בברכה.</p>\n<p>נ\"ב. ווען איך וועל זיין אויפן ציון הק' פון מיין שווער כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע וועל איך מזכיר זיין די אלע וועגען וועלכע איר שרייבט צום גוטען געזונט און פרנסה טובה.</p>\n<p>זה עתה נת' מכתבו מי\"ט מ\"ח.</p>\n<h4><i><b>ז'תתקפט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 75.</p>\n<p><b>על פי רוב:</b> ראה גם לעילח\"כ אגרת ז'תשמו, ובהנסמן בהערות שם.02</p>"],[1200950237,"ז'תתקצ\n\n<p>ב\"ה, י\"א כסלו, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוהר\"מ שמואל דוד שי' הלוי שד\"ר</p>\n<p>שלום וברכה!</p>\n<p>נתקבלה הרשימה עם המצורפים אלי'.</p>\n<p>לפלא שמיום ששאל בנוגע לבריאות בנו שי' וחוו\"ד הרופא, בטלפון ע\"י הרחמ\"א שי' חדקוב, לא נשמע ממנו מאומה מהנעשה אתם, ובודאי זהו סימן לטוב, ובכ\"ז בטח יודיע פירוש.</p>\n<p>בודאי ניצל היומי דפגרא דיו\"ד כסלו, וכן ינצל את חג הגאולה י\"ט כסלו וימי החנוכה הבע\"ל באופן המתאים (ואם נמצאים שם אברכים דישיבת תו\"ד - בטח גם אותם ימשיך בהנ\"ל) ויכתוב גם עד\"ז.</p>\n<p>בברכת חג הגאולה והצלחה בעבודתו בקודש למעלה מדרך הטבע, וברכות</p>\n<p>והצלחות בעניניו הפרטים ולבריאות נכונה של זוגתו בניהם וגם הוא בעצמו בכלל.</p>\n<p><b>מ. שניאורסאהן</b></p><p>נתעכב מכתבי ובינתים מסר לי הרה\"ח כו' הרחמ\"א שי' אשר נדחה לע\"ע נתוח בנו שי', וכל עכבה לטובה.</p>\n<p>בענין דירה - טוב שיעסוק במרץ המתאים בקנית בית, ובפרט שיש רוצין לסייעו בזה סיוע של ממש.</p>\n<p>נתקבל מכתבו המהיר עם הפ\"נ, והשי\"ת ימלא המשאלות שבכל הפ\"נ לטובה ולברכה.</p>\n<h4><i><b>ז'תתקצ</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 131.</p>\n<p><b>מוהר\"מ שמואל דוד שי':</b> רייטשיק. אגרות נוספות אליו - לעיל ז'תתק, ובהנסמן בהערות שם.</p>\n<p><b>תו\"ד:</b> תורה ודעת.</p>\n<p><b>בענין דירה:</b> ראה גם לעיל אגרת ז'תתקל.</p>"],[1200950238,"ז'תתקצא\n\n<p>ב\"ה, ח' טבת, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ, עוסק בצ\"צ כו'<br>\nמהורנ\"ן שי'</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מג' טבת והקודם לו, ות\"ח ת\"ח על ידיעתו מחלוקת מעות חנוכה לתלמידים וההסברה שנתן להם, ויה\"ר אשר יפעלו הדברים בהנוגע לחיי היום יומים בפועל.</p>\n<p>ב) שמחתי לקבל ידיעה שיש תקוה שקבוצת תלמידים מאשכנז יבואו ללמוד להישיבה בפאריז, ולפלא שאינו מזכיר דבר עד\"ז במכתבו, ובודאי עושה בזה במרץ המתאים והשי\"ת יצליחם, וידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע טובה פעולה אחת מאלף אנחות, וכדאי הי' לפרסם שם הישיבה ע\"י השדרי\"ם ובכל האופנים שאפשר ושמקבלים תלמידים לישיבתם וכו' כי הרי סו\"ס יש כמה תלמידים מהישיבות באנגליא ובאנטעווערפען וכו' וכמו שכתב כ\"ק מו\"ח אדמו\"ר באחד ממכתביו שכשמעמידים פנס ברחוב חשכת הלילה מתקבצים סביבותיו, הרי עאכו\"כ כשמעמידים מאור שבתורה זוהי תורת החסידות ברחוב, בודאי יתקבצו סביבו, אלא שאלה שלע\"ע נמצאים ברחוב אחר צריכים להודיעם עד\"ז באותיות כאלו שיגיע אליהם...</p>\n<p>המחכה לבשו\"ט.</p>\n<h4><i><b>ז'תתקצא</b></i></h4>\n<p>מהעתק המזכירות.</p>\n<p><b>מוהרנ\"ן:</b> מוה\"ר ניסן נמנוב. אגרות נוספות אליו- ליעל ז'תתט, ובהנסמן בהערות שם.</p>\n<p><b>באחד ממכתביו:</b> חי\"ג אגרת ד'תשג, ובהנסמן בהערות שם.</p>"],[1200950239,"ז'תתקצב\n\n<p>ב\"ה, כ\"ט טבת, תשי\"ג</p><p>ברוקלין.</p><p>הנהלת רשת אהלי יוסף יצחק ליובאוויטש<br>\nבאה\"ק ת\"ו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>מוסג\"פ מכתב שנתקבל זה עתה ובבקשה להודיע בהקדם אם אפשר לצרפם</p>\n<p>להרשת בתור מוסד חדש או סניף ממוסד שכבר ישנו ובאם לאו - אזי להתייעץ בהקדם עם הת\"ת אשר בכפר חב\"ד אם בידם לעשות כנ\"ל כיוון שכפי המכתב זהו בסמיכות לספריא, ובכל אופן בבקשה להחזיר המכתב הנ\"ל.</p>\n<p>בברכת הצלחה בעבודתם בקדש.</p>\n<h4><i><b>ז'תתקצב</b></i></h4>\n<p>מהעתקה.</p>"],[1200950240,"ז'תתקצג\n\n<p>ב\"ה, כ\"ט טבת, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר מנחם זאב שי' הלוי</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו ממוצ\"ש ויחי וכן הקודמים לו ביחד עם המוסגר בהם. כן קבלתי הפ\"ש ע\"י הרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר בן ציון שי' שם טוב שד\"ר, אשר באמת אינו משביע רצון כפי ששיערתי, כיון שכנראה הענינים לא לבד שאינם עולים למעלה, אלא שבהשוואה לביקורו של הנ\"ל מאז, נראה בהם תנועה למוטב. וכיון שנמצאים במקומו כמה מארזי הלבנון, הן אלו שבאו לשם מכבר הן מאנ\"ש הפליטים חדשים שבאו מחדש, איני יודע מי המעכב - לולי הרשלנות והעדר העשי'. ואוי ואבוי שצריכים לחכות שיבוא מי מבחוץ לעורר על ענינים פשוטים כד' אמות של חסידים.</p>\n<p>ואם לא היו דיבורים באופן שיוצא מן הכלים הרי גם זה אינו מועיל.</p>\n<p>ב) במ\"ש אודות תמונת האותיות שכתב לי מוה\"ר יעקב שי' זילבערמאן, הנה מכתבו נתקבל, וכפי שרואה אני ממכתב כת\"ר שי', הרי, כנראה, שאין להנ\"ל קבלה איש מפי איש, אלא רק שמדייק בתמונת הפרשיות שראה. ולכאורה, בענינים כמו אלו צריך לשמוע איש מפי איש - מה בדוקא ומה בא בהזדמן, אבל אינו בדוקא. וכדאי לחפש אם ימצאו כאלה.</p>\n<p>ג) בנוגע לספר דרכי החיים שהניח פה, עדיין לא הי' זמני בידי לעיין בו כנצרך, ואולי יהי' זה במשך שבוע הבע\"ל...</p>\n<p>בברכה - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקצג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 100, מצילום האגרת.</p>\n<p><b>מוה\"ר מנחם זאב שי':</b> גרינגלס. אגרות נוספות אליו - לעיל ז'תשעד, ובהנסמן בהערות שם.</p>\n<p><b>תמונת... זילבערמאן:</b> ראה לעיל ח\"ח אגרת ב'שפב. ח\"ט ב'תתכב.</p>"],[1200950241,"ז'תתקצד\n\n<p>ב\"ה, כ\"ט טבת, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר<br>\nשלום שי'</p>\n<p>שלום וברכה!</p>\n<p>נודעתי אשר ביקר בעירם הרה\"ג הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר חנניא יו\"ט ליפא שי' דייטש והציע איזה תיקונים בהמקוה דמחנם אשר לדעתו נחוצים הם בהחלט, וכנראה - נכונים דבריו, כפי שהודיעוני הנה הבטיחו אותו הרבנים דשם לתקן את הזקוק תיקון, אבל חוששני שלא יתארך הדבר ובמשך הזמן הנה גם יעשה לענין ישן, וכו', ואל בינת כת\"ר שי' אשען, אשר ימצא הדרכים המתאימים לפעול שתתוקן המקוה בהקדם <b>היותר</b> אפשרי. ובודאי יסייעו בזה, אם נצרך הדבר, גם הרה\"ג הרה\"ח אי\"א נו\"נ מוהרז\"ש שי' דווארקין. מובן אשר כל הנ\"ל אפשר וצריך להעשות מבלי לנגוע בכבודו (האמיתי או המדומה) של מי שהוא, כי הרי הכוונה בכל הנ\"ל היא טהרת בנות ישראל, ובמילא צריך להעשות הדבר באופן שיבוא הדבר לפועל ובהקדם, ואחכה לבשו\"ט.</p>\n<p>בברכה- המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקצד</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר שלום שי':</b> פויזנר. אגרות נוספות אליו - לעיל ז'תשסז, ובהנסמןב הערותש ם.</p>"],[1200950242,"ז'תתקצה\n\n<p>ב\"ה, כ\"ט טבת, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>... מ\"ש בהנוגע לבריאות... ומצטער אשר לא דיבר באותיות המתאימות ובהדגשה המתאימה. הנה ההדגשה אינה נוגעת כאן כלל, אלא שבכלל הנהגתם בזה אינה מובנת כל צרכה, וכמו שאמרתי לו בהיותו כאן, שאין לאחוז מקל בשני ראשים וכיון שאחזו בדרך זו, הרי עליהם לשאול דעת רופא מומחה ולעשות כהוראתו.</p>\n<p>והשי\"ת יצליחו ואת זוגתו שיחיו לקבל רוב נחת ועונג מכל יו\"ח שיחיו ומתוך בריאות הנכונה.</p>\n<p>בברכה - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ז'תתקצה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 101.</p>\n<p><b>לא דיבר באותיותה מתאימות:</b> ראה לעיל אגרת ז'תתקמב.</p>"],[1200950243,"ז'תתקצו\n\n<p>ב\"ה, כ\"ט טבת, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר...<br>\nשי'</p>\n<p>שלום וברכה!</p>\n<p>א) מ\"ש בנוגע לבנו... שי', הנה מובן הדבר שהנצרך לו על הוצאותיו או לפעמים לעניני הרפואה, הרי לא יהי' מחסור בזה ח\"ו.</p>\n<p>ובהנוגע למצב בריאותו בכלל, הנה כל משך זמן היותו כאן לא הסתכל כ\"כ לחביריו, וניכר הי' בו אז ער קען זיך ניט צופאסטען, אם מפני שבטבעו אינו כ\"כ מעורב עם חברים או שלא התרגל לתנאי חיים חוץ לביתו.</p>\n<p>וכיון שבהנוגע ליראת שמים הלא ת\"ל שלם הוא, גם לומד כאן בישיבה זה משך זמן של איזה שנים, ובמילא נמצא ג\"כ בעונת השידוכין, הרי סברא נכונה היא שיסע לביתם, אשר שם בנקל יותר למצוא שידוך המתאים, והעיקר שגם ההסתדרות בגו\"ר תהי' קלה יותר בשבילו, הן במפני שנמצא בין משפחתו והעיקר מפני התנאים השונים באה\"ק ת\"ו מאשר כאן.</p>\n<p>בכ\"ז אמרתי לבנו שי' במענה על שאלתו, שאם גם יסע לאה\"ק ת\"ו הרי יכין כאן וויזה חזרה לכאן, כדי שלא יהיו כל קישויים אם ירצה לאחר ביקורו בביתו לחזור לכאן למשך זמן, ובודאי יראה השי\"ת הדרך הנכונה בשבילו - נכונה בגשמיות וברוחניות גם יחד.</p>\n<p>... ה) מוסג\"פ מכתב ל... שי', ובטח ימים אלו יהי' אצלו בשו\"ט. ובמילא יש להסביר לו ולחבריו שליט\"א, ע\"פ סיפור החסידים אודות הרה\"צ כו' וכו' ר' הלל נ\"ע מפאריטש, ששמעתיו ג\"כ - אף כי בקיצור - מכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, שבנסעו לליובאוויטש נתהפכה העגלה, ובמילא יצא בזה ידי חובתו, והאריך ימים ושנים לאח\"כ.</p>\n<p>וה\"ה בנדון דידן, שכיון שמרז\"ל כל החונף לרשע סוף נופל בידו, הנה יש לקיימו ע\"פ פירוש האריז\"ל בסוף לקו\"ת עה\"פ ישבע בחרפה, שע\"י החרפה בלבד יוצאים ידי חובתם ואז לא יוכה, הרי גם בנדון דידן בודאי יצליח השי\"ת שיהי' מספיק באופן כזה.</p>\n<p>ובנוגע לצד השני ידוע ביאור המובא בחסידות וגם בספרי מוסר, אשר עלוקה שמוצצת דם הרי כבר עשתה את שלה ובמילא בטלה מן העולם. והשי\"ת יזכהו ויצליחו לבשר טובות בהקדם היותר אפשרי בכהנ\"ל.</p>\n<h4><i><b>ז'תתקצו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 132.</p>\n<p><b>סיפור החסידים:</b> ראה מגדל עז ע' רלז, וש\"נ.</p>\n<p><b>המובא בחסידות:</b> תורה אור בראשית ה, ד.</p>"],[1200950244,"ז'תתקצז\n\n<p>ב\"ה, ד' שבט, תשי\"ד</p><p>ברוקלין.</p><p>האברכים הלומדים בישיבת אחי תמימים</p>\n<p>בפיטסבורג,</p>\n<p>ליב חיים שי' טוירק, אברהם שי' הולזמאן,</p>\n<p>שמחה</p>\n<p>ירחמיאל שי' צירקינד, מרדכי צבי שי'</p>\n<p>בערקאוויטש, צבי</p>\n<p>דוב שי' שיינער, ישכר דוב שי' פירסט ויצחק</p>\n<p>נתן שי'</p>\n<p>אדרעס</p>\n<p>שלום וברכה!</p>\n<p>נתקבלה תרומתם לקופת המעמד, ויהי רצון שיקויים בהם פירוש רבינו הזקן בכתוב וצדקה תרומם גוי, אשר על ידי הצדקה מתרוממים כל כחות הנפש, ובעיקר - בהנוגע אליהם - בזיכוך המוח והלב, להשכיל ולהבין בתורתנו הק', בתורת הנגלה ובתורת החסידות מתוך התמדה ומסירה ונתינה.</p>\n<p>בברכה,</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<p>המזכיר: א. קווינט</p>\n<h4><i><b>ז'תתקצז</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>האברכים... בפיטסבורג:</b> ראה גם לעיל אגרת ז'תתקעג. אגרת נוספת אליהם - לעיל ח\"ח ב'תקסו.</p>\n<p>פירוש רבנו הזקן:3 2תורה אור בראשית א, ב.</p>"],[1200950245,"ז'תתקצח\n\n<p>ב\"ה, ד' שבט, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ עוסק בצ\"צ צמ\"ס<br>\nכו'<br>\nמוה\"ר יצחק מאיר שי' הכהן</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת העתק הפס\"ד שלהם עם הטעמים, וכבקשתו הוחזר לו, ובטח כבר הגיע לידו.</p>\n<p>ויה\"ר מהשי\"ת, אשר כמרז\"ל ת\"ח מרבים שלום בעולם, הנה יצליח בעבודה זו, ובזה גופא בריבוי, אשר בד\"מ ממשיך גם ריבוי בברכה ובכל הענינים המנוים במדרש אסתר רבה בסופו.</p>\n<p>מוסג\"פ העתק המאמר שנאמר אשתקד ביום ההילולא של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אשר בטח ינהג בו טוב עין לזכות גם את אחרים.</p>\n<p>בכבוד ובברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><p>עי' רש\"י סוטה י. ד\"ה במה בירכו: כל ברכה שבמקרא לשון ריבוי הוא, דבר המרבה ומצוי בו שובע.</p>\n<h4><i><b>ז'תתקצח</b></i></h4>\n<p>נדפסה בקונ' צדי\"ק למלך\" ב ע' 134.</p>\n<p><b>מוה\"ר יצחק מאיר:</b> רפופורט.</p>"],[1200950246,"ז'תתקצט\n\n<p>ב\"ה, ד' שבט, תשי\"ד</p><p>ברוקלין.</p><p>מרת... תחי'</p>\n<p>ברכה ושלום!</p>\n<p>עס איז ערהאלטן געווארן אייער בריף פון... און אויך דער פריערדיקער, און ווען איך וועל זיין אויף דעם ציון הק' פון מיין שווער כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה זי\"ע, וועל איך מזכיר זיין די אלע וועגן וועלכע איר שרייבט וועגען זיי, יעדערן פון דעם וואס ער נויטיגט זיך.</p>\n<p>דאס וואס איר שרייבט וועגן אייער טאכטער... תחי', האב איך שוין געשריבן אייך עטליכע מאהל, אז ווען א טאכטער שטייט אין שידוכים, איז די ערשטע זאך דארפן עלטערן און ספעציעל א מוטער צו ריידן מיט איר וועגן דעם ווי א אידישע הויז דארף זיך פירן, און ספעציעל בנוגע צו טהרת המשפחה (מקוה), וואס נאר דאן ווען א איד פירט זיך אין דער וועג פון תורה קען א איד זיין גליקלעך.</p>\n<p>און דעריבער איז ניטא קיין שום ארט צו שעמען זיך און ניט ריידן וועגן דעם, און אויך ניט באנוגענען זיך מיט איין מאל ריידן, און ווי עס ווייזט אויס פון אייער שווייגן אין דעם, האט מען ווייניג געטאן אין דעם אדער גארניט געטאן.</p>\n<p>דעריבער פאר[שטיי] איך ניט וואס איז בא אייך דער וואונדער אז עס גייט ניט גלאטיק, ווען מען טוט ניט דאס וואס השם יתברך הייסט טאן.</p>\n<p>און איך האף, אז לכל הפחות איצטער וועט איר אנהויבן צו ריידן מיט אייער טאכטער וועגן דעם. און השם יתברך זאל העלפן אז אייער טאכטער תחי' זאל האבן א גוטן זיווג און איר זאלט האבן פון איר און פון אלע אייערע קינדער פיל אידישן נחת.</p>\n<p>בברכה.</p>\n<h4><i><b>ז'תתקצט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 133.</p>"],[1200950247,"ז'תתר\n\n<p>ב\"ה, ח' שבט, תשי\"ד</p><p>ברוקלין.</p><p>צו די ליידיס אוקזילערי פון בראנזוויל און איסט ניו יארק,<br>\nובראשן מרת דבורה תחי' גרינבערג ומרת מנוחה רחל תחי'<br>\nגראנער</p>\n<p>ברכה ושלום!</p>\n<p>אין די טעג פון פארן יארצייט הילולא פון מיין שווער כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, בין איך צופרידן צו באקומען א גרוס פון אייך, און ספעציעל פון אייער ארבעט אין די פערשידענע צווייגן פון מיין שווער'ס כ\"ק אדמו\"ר ענינים און מוסדות וואס ער האט געגרינדעט אדער פארגעזעצט זיי, און זיכער וועט איר אויך אויף ווייטער טאן אזוי.</p>\n<p>און אזוי ווי יעדער לעבעדיקע זאך וואקסט, וואט אויך אייער ארבעט פון צייט צו צייט וואקסן און גרעסער ווערן, און דענסטמאל וועט מיין שווער כ\"ק אדמו\"ר, אויך מוסיף זיין און ממשיך זיין ברכה והצלחה אין אייער ארבעט, און אויך ברכה והצלחה צו יעדערע פון אייך אין דעם וואס זי אליין נויטיגט זיך און אירע בני בית, און [השם] יתברך זאל אייך מזכה זיין צו אנזאגן גוטע בשורות אין דאס אלעס אויבן דערמאנטע.</p>\n<p>מיט א וואונטש צו יעדערע פון אייך און אייערע בני בית שיחיו.</p>\n<h4><i><b>ז'תתר</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 134.</p>"],[1200950248,"ח'א\n\n<p>ב\"ה, כ\"ד שבט, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר מנחם זאב שי' הלוי</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מט\"ז שבט, ובטח מכתבי הקודם כבר הגיעו, ובמה שכותב אודות... הנה כבר כתבתי לו ומה תועלת במה שאכפול עוה\"פ, ובפרט שאמרתי לו גם בע\"פ, והוא שיעשו כהוראת רופאים מומחים, והתורה נתנה רשות לרופא לרפאות.</p>\n<p>והשי\"ת יצליחם.</p>\n<p>ב) בהנוגע להתלמידים דבית המדרש שניכר בהם העדר המשמעת ואי שמירת הזמן וכו'. הנה אין זה הנהגה כלל וכלל שאני אהי' ממלא מקום המשגיח ולמלאות מקום כאו\"א מההנהלה וכו', וכמ\"ש הוקר רגלך מבית רעך. ושמירת הזמן וההשגחה הרי צ\"ל על זה - כמו בכל מוסד חינוך - אנשים ממונים. ואם יעשו מלאכתם באמונה איני מבין מפני מה לא יצליחו הם במה שבישיבות אחרות מצליחים, ובפרט שכבר דברתי עם אחדים מהת' בהנוגע להנ\"ל ובודאי מסרו גם לחבריהם.</p>\n<p>ג) ובהדומה להנ\"ל - גם בהנוגע להת'... כי מה לו ללמוד פשטים וביאורים בה'קרעכץ וכו' ובמילא אינו יודע מה לעשות - אשר כיון ששאל בפירוש ועניתי לו ג\"כ בפירוש שלא יפסיק, הרי אין מקום לספק.</p>\n<p>ד) מוסג\"פ העתק מכתבי שנשלח באופן רשמי להרה\"ח כו' מוהר\"ל שי' קרעמער.</p>\n<p>וכפי שנמסר לו ע\"י התלפון בטח יפרסמו בש\"ק מברכים הבע\"ל, בכ\"ז שלוח גם לו העתקה בזה ותקותי שגם היא תתקבל קודם הש\"ק מברכים. ובודאי ינצל אותו ככל האפשרי. ואחכה לבשו\"ט.</p>\n<p>בברכה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'א</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>מוה\"ר מנחם זאב שי':</b> גרינגלס. אגרות נוספות אליו - לעיל ז'תשעד, ובהנסמן בהערות שם.</p>\n<p><b>מכתבי:</b> אפשר דלעיל ח\"ח ב'תכח.</p>"],[1200950249,"ח'ב\n\n<p>ב\"ה, כ\"ח שבט, תשי\"ד</p><p>ברוקלין.</p><p>הנהלת ישיבת תורת אמת אשר בירושלים<br>\nעיה\"ק ת\"ו<br>\nה' עליהם יחיו</p>\n<p>שלום וברכה!</p>\n<p>... ומטובם לעשות התועדות בהשתתפות כל התלמידים, ואחרי אשר ילמדו המאמר דיום ההסתלקות ד\"ה באתי לגני ה'שי\"ת (כולו או מקצתו) יתועדו המשפיעים עם הנ\"ל בביאור ענין נשיא הדור בכלל ונשיא חב\"ד בפרט. וע\"פ המבואר בהמכתב שבהקדמת הקונטרס די\"ב תמוז השי\"ת, ולא עזב ולא יעזוב הרועה את צאן מרעיתו, כמובן בתוספת ביאור מתאים להמתועדים.</p>\n<p>ומובן אשר אם מכל התועדות צ\"ל בכן, הרי עאכו\"כ מהתועדות כהנ\"ל ובנוגע לבני תורה היינו בכן בתוספת אומץ בלימוד תורת הנגלה ובתורת החסידות.</p>\n<p>המחכה לבשו\"ט בהנ\"ל ומברכם בברכת הצלחה בעבודתם בקודש.</p>\n<h4><i><b>ח'ב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 135.</p>\n<p><b>לעשות התועדות:</b> נוסח דומה לישיבת תו\"ת לוד. בהמשך אליה - לעיל ח\"ח אגרת ב'תנט.</p>"],[1200950250,"ח'ג\n\n<p>ב\"ה, אדר\"ח אד\"ר, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מכ\"ב שבט וכן ב' הקודמים. ונהניתי לקרוא בו שכבר קבל הוויזה. וכיון שכפי מכתבו הנה הרב הצבאי מודאג מחוסר ממלא מקומו במקום שירותו, אשר בודאי זהו נוגע לעניני יראת שמים דאנשי הצבא, הנה צריך לסדר את הענין ולהבטיח שלא יהי' מגרעות בהנ\"ל וככל דבר שבקדושה - אם אפשר להיות תוספת הרי מה טוב.</p>\n<p>נהניתי ממ\"ש תוכן שיחותיו עם המושפעים שלו שהוא ה\"בכן\" בהנוגע לקיום מצות מעשיות אשר זהו כל האדם, וכדי שיהי' בחיות וענין של קיימא מוכרח ג\"כ שידעו אודות המאור שבתורה זוהי תורת החסידות מנהגי' והדרכותי'.</p>\n<p>והשי\"ת יצליח לבשר טוב בכל הנ\"ל, וכן מבריאות זוגתו תחי' ובכל מעניניו הפרטים.</p>\n<p>נ\"ב. מוסג\"פ העתק מכתבי שכתבתי ימים אלו לאגוד נוער כאן, ונוער שאין לו אלא ידיעה מצומצמת ביותר בתורה ומצות ותקותי שיביא לו תועלת בשיחותיו עם חבורתו.</p>\n<p>מובן אשר אין לנסוע ביום הש\"ק באני' אשר המלחים או הבע\"ב הם בני-ברית.</p>\n<h4><i><b>ח'ג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 135, והיא אלמ ו,ה יחיאל מיכל יהודה ליב שי' זלמנוב.</p>\n<p>אגרות נוספות אליו - לעיל ז'תתקנ, ובהנסמן בהערות שם.</p>\n<p><b>אין לנסוע ביום הש\"ק:</b> ראה בזה לעילח\"כ אגרת ז'תקנד, ובהנסמן בהערות שם.</p>"],[1200950251,"ח'ד\n\n<p>ב\"ה, ו' אד\"ר, תשי\"ד</p><p>ברוקלין.</p><p>ש\"ב מרת זלדה תחי'</p>\n<p>ברכה ושלום!</p>\n<p>זה שוב זמן רב שלא קבלתי ממנה כל מכתבים וידיעות, וכבר מורגל אצל חסידים גם מדורות שלפנינו, שכאשר הכל שלום הנה אין כותבים, ואף שרבינו הזקן כבר התאונן על זה, הנה כנראה ממנהג הדורות שלאחריו לא פעלה הקו[ב]לנא שלו במילואה והמנהג עודנו קיים.</p>\n<p>ובאמת רציתי במאד גם בנוגע אלי' לפרש שתיקותה בנוהג הנ\"ל, ובכ\"ז כיון שאפשר לברר הרי אין סומכין על החזקה, ות\"ח אם תכתוב הן אודות עצמה ובעלה שי' וכן אמה הרבנית תחי', ויה\"ר שאך טוב תבשר במכתבי'.</p>\n<p>וכיון שבמכתבה האחרון כותבת שיתכן שתשלח את מה שכתבה ונדפס, הנה תמלא גם זה, אף שבכלל [ב]מה שנדפס לרבים אין מתגלה האדם כ\"כ ועכ\"פ פחות יותר מאשר במכתב, אבל למילוי ושלימות קוי הדמות בודאי הנה כל ענין מועיל.</p>\n<p>מסגיר הנני העתק מכתב שכתבתי בקשר עם יום הגאולה י\"ט כסלו העבר אשר תוכנו משמש מענה על חלק ממכתבה אלי.</p>\n<p>בפ\"ש חמה לאמה הרבנית ולבעלה שיחיו, המחכה לבשו\"ט.</p>\n<h4><i><b>ח'ד</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 136.</p>\n<p><b>זלדה:</b> מישקובסקי-שניאורסאהן.</p>\n<p><b>התאונן על זה:</b> ראה אג\"ק שלו ח\"א אגרת צ.</p>\n<p><b>שכתבתיח.. י\"ט כסלו העבר:</b> לעיל ח\"ח בקרצב.</p>"],[1200950252,"ח'ה\n\n<p>ב\"ה, י\"ב אדר, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת הפ\"נ בעד זוגתו תחי', וכבקשתו, כשאהי' על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקלל\"ה נבג\"מ זי\"ע אזכירה לרפו\"ק ואחכה לבשו\"ט.</p>\n<p>בהזדמנות זו הנני לעוררו עוד הפעם במה שהזכרתי לו איזה פעמים כשהתראינו פא\"פ והוא אודות ההכרח הכי גדול שיפעל השפעתו על בנו הרב שי' אשר השי\"ת זיכהו שנשמעים לקולו במדה חשובה בחוגי הרבנים הצעירים שי', שבנו ישפיע עליהם ועל..</p>\n<p>שהוא חבר בו, שידגישו יותר ויתאמצו ביותר בעינים דיראת שמים ומצות מעשיות בפועל הן בהנוגע להבתי כנסיות והקהלות של הרבנים הצעירים והן בהנוגע להתאחדות השונות שהם מכריזים מזמן לזמן, וכיון ש[מ]לפ[נ]י שנה היתה ניכרת שם הזזה ותנועה לצד ימין הרי עתה בקל יותר להמשיך בזה ועאכו\"כ שלא לתת מקום לחלישות כמו שנרגש בחדשים האחרונים.</p>\n<p>אינני רוצה לפרט ולפרש פרטים בהנ\"ל כי בודאי ידוע לבנו הרב שי' עוד יותר מאשר לי, אפשר שבנו שי' אינו מכיר או שאינו מאמין שיוכל להשפיע בזה, אבל בשים לב שכאו\"א מאתנו כשפועל בענינים דתורה ומצות הרי הוא שלוחו של המקום ב\"ה ממה\"מ הקב\"ה ושלוחו של אדם (העליון שעל הכסא ה\"ה כביכול) כמותו (עיין לקו\"ת ויקרא בתחלתו) הרי צריך ללכת בטח בדרך השפעה הנ\"ל ואז מצליח השי\"ת, ועכ\"פ עלינו לעשות כאו\"א המוטל עלינו בשלימות וה' הטוב בעיניו יעשה.</p>\n<p>וככל הדברים אלה גם בנוגע לכת\"ר שי' שבודאי כשידבר עם בנו הרב שי' או בע\"פ או בכתב בדברים היוצאים מן הלב כנ\"ל בודאי ישפיע עליו.</p>\n<p>בכבוד ובברכה המחכה לבשו\"ט.</p>\n<h4><i><b>ח'ה</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 78.</p>\n<p><b>שבנו ישפיע עליהם:</b> בהמשך לזה - לקמן ח'י. ח'יח.</p>"],[1200950253,"ח'ו\n\n<p>ב\"ה, כ\"ה אד\"ר, תשי\"ד</p><p>ברוקלין.</p><p>האברך... שיחי'</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו אשר כיון שאין הוא שבע רצון מפרטים אחדים בסדרי הישיבה, ולפי דעתו מבלבלים פרטים אלו מהתמדה בלימוד כדבעי, וכן בהנוגע להתפלה, הרי יש אצלו סברא אודות נסיעה לישיבת תומכי תמימים באה\"ק ת\"ו, ושואל חוות דעתי בזה.</p>\n<p>והנה למותר להאריך בהידוע ופשוט, אשר הענינים המפריעים לתורה עבודה או גמילת חסדים, סיבתם הוא השאור שבעיסה, היינו היצר הרע המבלבל את האדם בכמה אופנים ודרכים, כי אף שנקרא כסיל, הנה בכל זה בהנוגע לעבודתו - אומן מומחה הוא, וכידוע פתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, אשר היצר הרע בא לכל אחד ואחד בטענות מתאימות לתכונת נפש אדם פרטי זה עד שגם לפעמים הוא מתלבש באצטלא של צורבא מרבנן, ירא שמים וכו', ולכן על כל אחד לבדוק הדק היטב היטב הדק את הנופל בדעתו בהנוגע שינויים בעבודת השי\"ת, ולדעת מי הטוען טענות אלו, אם מצד ימין או מצד שמאל. ובטח ידוע לו הסיפור אודות הרה\"צ מטשערנוביל, שנדפס בשיחת פסח תש\"ג, ואחת הבחינות היא אם השינוי יגרום לביטול תורה ועבודה - או לאו.</p>\n<p>ובנידון דידי' - כיון שנמצא הוא בישיבה שנתייסדה על ידי צדיקים נשיאי הדור ומתנהלת ברוחם, היינו לימוד התורה ביראת שמים, הנה קרוב הדבר, גם מבלי ידיעות פרטיות בזה, שלימוד בה תועלת גדולה כרוכה בזה, ובמילא מובן גם כן אשר היצה\"ר מתקומם בזה בכמה מיני תחבולות לבטל ולבלבל אותו מלהתנהג מתאים לפי דרישת הישיבה בכל הפרטים.</p>\n<p>מובן גם כן, שאם יבוא היצה\"ר ויגלה כוונתו שאינו רוצה להניחו להיות שוקד בלימדו תורת הנגלה ותורת החסידות, הרי בטח לא ישמע לו, ומתאים למה שנאמר והנחש הי' ערום, הרי בא בערמומיות, שאדרבה הישיבה מבלבלת אותו משקידה בתורה ומענינים דעבודת השם ביראת שמים כדבעי, שאז תקוותו שיתקבלו הטענות שלו, ויבלבל אותו מתורה ותפלה. ואף שצריך היצה\"ר להבטיח לו שאם יבוא לישיבה אחרת הרי אז לא יבלבל אותו ויכל לשקוד בתורה ולהדר בתפלה, הרי מובטח הוא היצה\"ר, שכיון שישמע לקולו בתחלה - שכל התחלות קשות - הרי בטח גם אחר כך ימצא אופן איך להמשיכו עוד יותר ברשתו.</p>\n<p>כי הרי נתנה לאדם הבחירה חפשית ושני דרכים לפניו, וכמאמר הכתוב ראה נתתי לפניך את החיים ואת הטוב את כו', אבל ביחד עם זה ניתנו לו לאדם סיוע מיוחד שיבחר בטוב, וכמאמר הכתוב ובחרת בחיים. ובודאי גם בנידון דידי' הרי אף שהיצה\"ר הוא ערום ביותר, ניתנו לו הכוחות לבטל כל הטענות שלו ולהתאמץ במסירה ונתינה על ידי היסח הדעת גמור מהטענות המבלבלות שאין הסביבה מתאמת לפניו ושהכל אשמים בביטול תורה ותפלה שלו ולא הוא בעצמו כו' וכו'.</p>\n<p>מובן גם כן שבין חביריו בישיבה ישנם כמה ענינים הדורשים תיקון, כי אין שלם בתכלית השלימות אלא הקב\"ה בורא העולם אבל העצה לזה הוא שישפיע על חביריו בתיקון עניניהם, ולא שהוא יהי' מושפע מהם, אשר זהו ג\"כ סגולה שיתתקנו חסרונותיו הוא על ידי חביריו, וכמאמר - וכמבואר - בהענין דכל ישראל ערבים זב\"ז, שהם קומה שלימה ויש מעלה בזה מה שאין בזה, ועל ידי אהבת ישראל משלימים כל אחד את חבירו.</p>\n<p>המורם מכל הנ\"ל, שיסיח דעתו ממחשבות המבלבלות מתורה ועבודה <b>וישקיע</b> את עצמו בלימוד תורת הנגלה ותורת החסידות ובעבודת התפלה - מתאים לסדרי הישיבה ודרישותי', ותקויים בו הבטחת רז\"ל אשר יגעת - הרי אז - ומצאת.</p>\n<p>אינו מזכיר אם גם בנוגע לחבירו... שי' הרי גם אותו מבלבלים אלו הטענות שכותב בהנוגע לעניניו, ואם כן הוא - הרי מובן שגם אליו שייך מענה הנ\"ל.</p>\n<p>בברכת הצלחה בלימוד תורה ביראת שמים.</p>\n<p>בשם כ\"ק אדמו\"ר שליט\"א</p>\n<h4><i><b>ח'ו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 102.</p>\n<p><b>הסיפור:</b> ראה גם לעילחט\"ז ה'תתקצח, ובהנסמן בהערות שם.</p>"],[1200950254,"ח'ז\n\n<p>ב\"ה, ט' אדר ב', תשי\"ד</p><p>ברוקלין.</p><p>הוו\"ח אי\"א נו\"נ כו' מוה\"ר שמואל צבי שי'<br>\nשו\"ב</p>\n<p>שלום וברכה!</p>\n<p>הגיעתני הידיעה ע\"י הטעלעפאן ואח\"כ במכתב מהרה\"ח אי\"א נו\"נ עוסק בצ\"צ מוה\"ר משה אלי' שי' גערליצקי אשר מצב בריאותו אינו כדבעי. וכשאהי' על הציון 4הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אזכירו לרפו\"ק. ותקותי חזקה שבעצמו יוכל לבשרני טוב בזה.</p>\n<p>ובודאי למותר להעיר, שבכל דבר ודבר צריך לראות רמז מלמעלה בהנוגע לתורת ה' ועבודתו, ובפרט כשחקוק בלבו של אדם, אשר הלב הוא משכן הרגש אהבת ה' וכו', וכמ\"ש ואהבת את ה\"א בכל לבבך, וכשמוסיף איש הישראלי בבריאות הרוחנית מוסיפין לו מלמעלה בבריאות הגשמית.</p>\n<p>והנה הדרך כיצד יבוא לאהבתו ית' - הוא ע\"י ההתבוננות בכמה אופנים, וכמבואר בתניא בכמה פרקים בזה. ולכן מהנכון שיקבע שיעור, לכה\"פ איזה פעמים בשבוע, בתורת החסידות. ובודאי יכול להתדבר בזה עם הרה\"ח גערליצקי שי' אודות סדר הלימוד בזה.</p>\n<p>בטח נודע לו משלשת השיעורים השוים לכל נפש מתקנת כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע, והם א) אמירת שיעור תהלים - כפי שנחלק התהלים לימות החודש - בכל יום אחר תפילת שחרית. ב) לימוד פרשה חומש עם פירוש רש\"י מפרשת השבוע - ביום א' מהתחלת הסדרה עד פ' שני וביום שני מפרשת שני עד שלישי וכו' - ג) שיעור לימוד תניא כפי שנחלק התניא לימות השנה.</p>\n<p>בברכה לרפו\"ק - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'ז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 103, מצילום האגרת.</p>\n<p><b>מוה\"ר שמואל צבי:</b> דושאסעף, מונטריאל.</p>"],[1200950255,"ח'ח\n\n<p>פורים תשי\"ד:</p>\n<p>פורים שמח בהתעוררות לעשות תינוקות וגדולים לתלמידי ותלמידות מרדכי ושמחה פורץ גדרים והעלמות.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'ח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 71.</p>"],[1200950256,"ח'ט\n\n<p>ב\"ה, ט\"ז אדר ב', תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>איך בין געווען צופרידן צו באקומען אייער בריף, אין וועלכען איר שרייבט וועגען אייער ארבעט אין די תלמוד תורה'ס און מסיבות שבת.</p>\n<p>און השי\"ת זאל געבען אויף ווייטער הצלחה אין דעם, אז די ארבעט זאל פארגרעסערט ווערן, און צוזאמען מיט דעם זאל פארגרעסערט ווערן די הצלחה און אויך די באטייליגונג פון די אלע וועלכע זיינען זוכה צו נעמען איינטייל אין דער עבודת הקדש.</p>\n<p>וואס איז אלע צייטן איז דאס געווען העכסט וויכטיג, און על אחת כמה וכמה אין אונזער דור וואס מיר זיינען געבליבן די שארית הפליטה, איז מיט יעדער פרט וואס מען איז מקרב לבן של בני ובנות ישראל לאבינו שבשמים טוט מען אויף דערמיט א דבר גדול ביותר.</p>\n<p>און השי\"ת איז א בטוח, צו ממלא זיין זיינע הבטחות וואס ער איז מבטיח בתורתנו הק' פאר אזעלכע פעולות.</p>\n<p>און בפרט - זאל השי\"ת העלפען אייך, איר זאלט קענען אנזאגן גוטע בשורות וועגען אייער טאכטער... תחי', פון דער ערפילונג פון משאלות לבבה לטובה. זיכער היט זי אפ טהרת המשפחה, וואס דענסטמאל בענטשט השי\"ת מיט געזונטע קינדער לאריכות ימים ושנים טובות.</p>\n<p>בייגעלייגט איז דא א קאפיע פון מיינעם א מכתב כללי פאר פרויען, וואס זיכער וועט איר איבערגעבען עם צו אייער טאכטער תחי'.</p>\n<p>בברכת הצלחה,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'ט</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 79.</p>"],[1200950257,"ח'י\n\n<p>ב\"ה, כ\"א אדר ב', תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>נעם לי לקבל מכתבו, בו מבשר טוב אשר זוגתו תחי' חזרה לאיתנה. ובודאי עפ\"י מרז\"ל דמעלין בקודש, ימשיך לבשר טוב בגשמיות וברוחניות, הן בהנוגע לו ולזוגתו, והן בהנוגע לילדיו וב\"ב - שיחיו - אשר הרי זה מצוה דאורייתא לשמח לבב רעיתו, שהוא חלק מהכלל גדול בתורה, כמאמר רבי עקיבא, כמצוה כללית דואהבת לרעך.</p>\n<p>ת\"ח על מה שכתב לבנו הרב שי' אודות תוכן מכתבי לכת\"ר בהנוגע אליו, ובודאי הוסיף גם מדילי'. וכיון שרואה אני במכתב בנו שי' שידבר עוד עמדו בהנ\"ל, בודאי ינצל גם הזדמנות הבאה לחזק אותו ולעודדו.</p>\n<p>וע\"פ המאמר הידוע אשר הזמן הוא אבדה שאינה חוזרת וכל האפשר להעשות היום אין לדחותו לאח\"כ, ובפרט שידוע דכל יומא ויומא עביד עבידתי', וכל יום ויום צ\"ל ממולא בתוכן המתאים ליכולת איש פרטי זה, ובפרט אם האיש הוא כללי, היינו שיש לו חוג שיוכל להשפיע עליו ומקבלים הוראותיו.</p>\n<p>וביחוד שהוא ג\"כ מעניניא דיומא, שהרי ימים אלו חזרו מנסיעתם לאה\"ק ת\"ו הרב... והרב... - שיחיו - ראשי ומנהיגי הסתדרות הרבנים, ובודאי ישפיע ביקורם באה\"ק ת\"ו והדו\"ח שהביאו על יחס חברי הסתדרות הרבנים להשאלות הקשורות באה\"ק ת\"ו, ויחס זה [יתבטא] ויבוא פועל גם בהדרשות שכפי מנהג המדינה, ידרשו בימי חג הפסח הבע\"ל - ימים הראשונים ובפרט בימים האחרונים.</p>\n<p>בברכה לו ולזוגתו ולכל ב\"ב - שיחיו - לחג הפסח כשר ושמח בגשמיות ברוחניות גם יחד.</p>\n<h4><i><b>ח'י</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 80.</p>\n<p><b>תוכן מכתבי:</b> דלעיל ח'ה.</p>"],[1200950258,"ח'יא\n\n<p><i>[חורף תשי\"ד]</i></p>\n<p>אם קורא הוא בשימת לב הראוי' את ירחונינו בטח כבר הי' יכול לראות שבאופן פרינציפי <b>אין</b> הוא דן אלא ע\"ד תומ\"צ ומאורעות דזמן <b>העבר ולא</b> ע\"ד המאורעות דזמננו זה, 0וע\"ז יש די מכ\"ע יום יומיים). והטעמים מובנים כל המתבונן בהמצב דזמן ההווה - (יוצא מן הכלל יחידי הי' המאמר ע\"ד הסתלקות נשיא המל\"ח <b>ומייסד עתוננו</b> - הרבי מליובאוויטש זצוקללה\"ה).</p>\n<h4><i><b>ח'יא</b></i></h4>\n<p>נדפה בקונ' \"צדי\"ק למלך\" ג ע' 124, מצילום האגרת. ונכתבה במענה לשאלה למה לא נכתבה ב\"שמועסן מיט קינדער און יוגנד\" הערכה על א' מגדולי ישראל שנפטר.</p>\n<p><b>הי' המאמר... זצוקללה\"ה:</b> בגליון אדר תש\"י.</p>"],[1200950259,"ח'יב\n\n<p>ב\"ה, ה' ניסן, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>לאחרי הפסק ארוך הי' נעים לי לקבל מכתבם מכ\"ט אד\"ש, וכמאמר כ\"ק אדמו\"ר מוהר\"ש נ\"ע, אז גוט איז גוט איז בעסער ניט בעסער, הנה יה\"ר מהשי\"ת שיבשרו בשורות עוד יותר משמחות בהנוגע לענינים הגשמים ובהנוגע לענינים הרוחניים.</p>\n<p>ובמ\"ש אודות המבואר בתניא פכ\"ג בביאור ההפרש בין מצות לתורה, הנה יעויין בזה בהגהות הצ\"צ שנדפסו בספר קיצורים והערות לתניא וכן במאמרים שישנם בכמה ביכלעך חסידות, ובודאי גם באותן הנמצאים באה\"ק ת\"ו, ומתחיל להבין מה שמתבאר בתניא פרק כ\"ג.</p>\n<h4><i><b>ח'יב</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ב ע' 137.</p>\n<p><b>וכמאמר:</b> ראה גם לעיל אגרת ז'תשעז, ובהנסמן בהערות שם.</p>\n<p><b>להבין מה שנתבאר:</b> נדפס בתניא עם מ\"מ ליקוט פירושים וכ'ו ע' תלו ואילך.</p>"],[1200950260,"ח'יג\n\n<p>ב\"ה ו' ניסן, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>במענה על מכתבו מיום ההילולא ב' ניסן, הנה בהנוגע לבתו הבכירה תחי' בת ט\"ז שנה, ושואל במה תתעסק להבא כיון שגמרה את הלימוד בבית הספר דיסודי התורה,</p>\n<p>הנה שמעתי שנמצא [...] בית ספר לנערות יר\"ש כדבעי ובודאי על אתר יכול לברר בזה אל נכון. ואם כן הוא, כדאי להכניסה לשם, ובטח במשך הזמן, הנה נוסף על הידיעות וההשתלמות שיתוספו לה, בטח תוכל להשפיע גם על סביבתה שם.</p>\n<p>בהנוגע לפרנסתו בגשמיות, הנה בטח יעזור השי\"ת. ואם בכלל אמרז\"ל שאין להתפעל ממיצר ודוחק זמני, ועאכו\"כ כאשר אנשי מדינתנו דלפנים שראו ניסים בגלוי וראו ג\"כ אשר שקר הכסף והבל הנכסים גשמים וכו', שאין להתפעל מ[ז]ה כלל.</p>\n<p>ואף שמובן שהמיצר והדוחק מבלבלים ומפריעים מכמה ענינים, ובעיקר גם מעבודת השי\"ת, הרי יש להתפלל ע\"ז ביחוד, שכאשר מן המיצר קראתי ה' אזי ענני במרחב י-ה, מתחלה מרחב ברוחניות, שמתמעטים הבלבולים במיצרים הגשמיים, ואח\"כ נעשה מרחב בגשמיות.</p>\n<p>ומסוגלים להנ\"ל ימי הפסח שנקרא החג דיציאת מצרים, יציאה ממיצרים וגבולים דלעו\"ז ואפילו מיצרים וגבולים דקדושה, כמבואר בדא\"ח בכ\"מ.</p>\n<p>אודות התעסקותו בשדה החינוך הכשר, אז מען גייט ארום א גאנצן טאג און מען קומט כמעט מיט גארניט.</p>\n<p>הנה תמוה עד כמה פתגמי נשיאינו הק' [...], גם הידועים אותם ומתבוננים בהם, הרי סו\"ס מיינען זיי אז דאס מיינט מען א אנדערן ניט עם.</p>\n<p>והרי בטח יודע [...] בפתגם הבעש\"ט לעשות טובה אחת פעם אחת ברוחניות או בגשמיות, ואם שכינתא מוריד זיין חלק אלוקה ממעל ממש אויף מאטערן זיך - כפתגם הרשב\"ץ - אין א זאק פון פלייש מיט ביינער [...] בשביל פעולה או טובה אחת, עאכו\"כ שכאו\"א מאתנו צריך להיות שמח בחלקו כאשר השי\"ת מזכהו ומצליחו לעשות פעולות כאלו כמה וכמה פעמים ביום אחד.</p>\n<p>ומבואר זה ג\"כ במכתבי הכללי דיו\"ד כסלו שנה זו.</p>\n<p>וכיון שעוד אחדים מאנ\"ש מסופק[ים] בהנ\"ל, מטובו לפרסם תוכן שורותי אלה, וישמש מענה גם להם.</p>\n<p>כבקשתו כשאהי' על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע אזכיר את כל אלו שכותב אודותם להמצטרך לכאו\"א. והשי\"ת יזכהו לבשר בכל הנ\"ל.</p>\n<p>בברכת חג הפסח כשר ושמח.</p>\n<h4><i><b>ח'יג</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 81.</p>\n<p><b>כפתגם הרשב\"ץ:</b> ראה גם לעיל ח\"ח אגרת ב'תקצג.</p>\n<p><b>במכתבי הכללי:</b> לעילח\"ח ב'רצב</p>"],[1200950261,"ח'יד\n\n<p>ב\"ה, ח' ניסן, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ כו' מוה\"ר ליב שי'<br>\nהכהן</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיום ההילולא של כ\"ק אדמו\"ר [מוהרש\"ב] נ\"ע, בצרוף רשימת זכרונותיו עשרים דפים. ודבר נכון עשה מה שרשמם, ובודאי ימשיך בזה. וכבר כתבתי כ\"פ בכגון דא לאחיו הרה\"ח כו' מוה\"ר רפאל נחמן שי' בנחיצות וגודל דבר זה. - בנוגע לשאלתו אם להדפיס זה בבטאון חב\"ד או בחוברת פרדס התמים - הרי עדיין לא הי' הזמן גרמא לקראם ובמשך איזה זמן אענה, בל\"נ, גם על זה ובכל אופן ימשיך בהרשימות וכנ\"ל.</p>\n<p>ולקראת חג המצות הממשמש ובא, הנני בזה לאחל לו ולב\"ב שיחיו שיחוגו אותו בכשרות ובשמחה, וע\"פ המבואר בכ\"מ אשר הימים טובים משפיעים על הימים הבאים אחריהם עד הרגל הבא שלאחריו וכמבואר ג\"כ בלקו\"ת לרבנו הזקן בפ' ברכה דצ\"ח ע\"ב הנה יומשך זה בביתו ובסביבתו גם בימי השנה.</p>\n<p>והנה שם (בלקו\"ת הנ\"ל) המדובר הוא בבחי' ביטול שישנו בכל המועדים ובמילא א\"צ להמשיך אלא עד הרגל הבא אחריו, משא\"כ בענינים המיוחדים לכל מועד ומועד שנמשכים על כל השנה כולה, ובפרט בנוגע לחג הפסח וכפתגם כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בשיחת חג הפסח ה'תש\"ג: הארת כל המועדים מאירה בכל יום והארת חג הפסח נמשכת תמיד.</p>\n<p>ויש להסביר הדברים בקיצור עכ\"פ, אשר בכללות שבועות הוא עינן התורה זמן מ\"ת. סוכות הוא בכללות עינן המצות וכללותם מצות הצדקה, מקיפים (יעוין תניא פרק ה') וכמ\"ש ואשים דברי בפיך ובצל ידי כסיתיך. ופסח זמן חירותינו הוא ענין האמונה וכלשון הזהר דמצה היא מיכלא דמהימנותא. והנה עניני תורה ומצות תלוים בזמן ובמקום, משא\"כ האמונה שהיא מצוה תמידית ויסוד כל התורה ומצוה, וק\"ל.</p>\n<p>בברכת חג הפסח כשר ושמח,</p>\n<p><b>מ. שניאורסאהן</b></p><p>קראתי רשימותיו זה עתה, ומתאימים יותר לפרדס הת', מאשר לבטאון. ובודאי ממשיך בהן.</p>\n<h4><i><b>ח'יד</b></i></h4>\n<p>מצילום האגרת.</p>\n<p><b>הרה\"ח... הכהן:</b> אגרות נוספות אליו - לעיל ד'תתסד, ובהנסמן בהערות שם.</p>\n<p><b>אם להדפיס:</b> חלק נדפס בבטאון חב\"ד גליון יג. \"שמועות וסיפורים\" ח\"ב (הוצ' תש\"נ) ע' 114 - 123. \"כפר חב\"ד\" גליון 547 (ט\"ז מ\"ח תשנ\"ג) ע' 12 ואילך.</p>\n<p><b>ולקראת חג המצות:</b> מכאן ואילך דם לעילח\"ח אגרת ב'תקע.</p>"],[1200950262,"ח'טו\n\n<p>פסח תשי\"ד:</p>\n<p>פסח כשר ושמח והתועדות מיוחדת בסעודת משיח.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'טו</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 72.</p>\n<p>ח'ריח</p>\n<p>מצילום האגרת.</p>\n<p><b>מוהר\"ש שי':</b> מטוסוב. אגרות נוספות אליו - לעיל ז'תתקנג, ובהנסמן בהערות שם.</p>"],[1200950263,"ח'טז\n\n<p>ב\"ה ג' דחוהמ\"פ, ה'תשי\"ד</p><p>ברוקלין, נ.י.</p><p>מכ' ב.<br>\nהרה\"ח וכו' וכו' מוהר\"ש שי'</p>\n<p>שלום וברכה!</p>\n<p>בהמשך למכתבי הראשון דהיום, הנה צריך הי' לברר בדיוק סדר היום של אסיפת הספרדים שאדותה כתב, כי יש חשש שידונו בה ג\"כ ע\"ד ממלא מקומו של הרב עוזיאל ע\"ה, ובמילא צריך הצד החרדי להיות מוכן עם קנדידאט מתאים. ובפרט שזה מכמה זמן שאחד מראשי מנהיגי מפא\"י ביקר בתפוצות ובאה\"ק ת\"ו ואחת ממטרותיו היתה להתבונן במהות הרבנים הספרדים הראויים להציגם בתור מועמדים למשרה הנ\"ל, והרי מובן שהקנדידאט שימצא חן בעניי הנ\"ל קשה יהי' ליראי ה' לסמוך עליו וד\"ל.</p>\n<p>מובן שגם על מכתבי זה חלים אלה התנאים שכתבם במכתבו אלי דיום ה' ניסן.</p>\n<p>ואחכה לבשורות טובות בהנוגע למכתבי זה ושלפניו.</p>\n<p>בברכה.</p>\n<p>(משום קדושת המועד לא באה החתימה)</p>\n<p><b>מ. ש.</b></p>\n<h4><i><b>ח'טז</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 104, מצילום האגרת.</p>\n<p><b>מוה\"ר מנחם זאב שי':</b> גרינגלס. אגרות נוספות אליו - לעיל ז'תשעד, ובהנסמן בהערות שם.*</p>\n<p>מצילום האגרת.</p>\n<p><b>מוהרש\"י:</b> זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובהנסמן בהערות שם.</p>"],[1200950264,"ח'יז\n\n<p>ב\"ה, ט\"ו אייר, תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ח הוו\"ח אי\"א נו\"נ עוסק בצ\"צ<br>\nמוה\"ר מנחם זאב שי' הלוי</p>\n<p>שלום וברכה!</p>\n<p>מאשר הנני קבלת מכתבו מיו\"ד אייר והקודם לו דב' אייר. ות\"ח על הבשו\"ט מה שכותב מהטבת מצב התלמידים בהנוגע בלימוד תורת הנגלה ותורת החסידות, וכן מהטבת מצב אלו ששלח לי פ\"נ בעדם. והשי\"ת יצליחו גם על להבא לבשר תמיד אך טוב בגו\"ר, מהנעשה בד' אמות שלו ובחלקו בעולם בכלל.</p>\n<p>מ\"ש אודות תוספת תלמידים.. בתו\"ת דמאנטרעאל, הנה כבר ידוע הכתוב בפי' המשניות להרמב\"ם ומובא בחסידות, אשר התינוק מושכים אותו ללימוד לא ע\"י ציווים ועאכו\"כ שלא בשבטים, אלא ע\"י שנותנים לו ממתקים וכו', ודוקא כאלו שיש <b>לו</b> חוש בהם בהמצב שהוא נמצא אז, ולא על שם העתיד, אף שתינוק בכלל מסוגל הוא לענינים דקבלת עול וכפי' וכו'. ועאכו\"כ בנדון דידן, שכן צ\"ל הסדר...</p>\n<p>נתעכב מכ' זה. ובינתיים נת': הס' ויגד ליעקב, מכ' מי\"ד וי\"ח לחד\"ז. ואחכה לבשו\"ט ע\"ד הביקור אצל מר שז\"ר שי'. ות\"ח מראש.</p>\n<p>בברכה - המחכה לבשו\"ט,</p>\n<p><b>מ. שניאורסאהן</b></p><h4><i><b>ח'יז</b></i></h4>\n<p><b>מצילום האגרת.</b></p>\n<p>מוהרש\"י: זוין. אגרות נוספות אליו - לעיל ז'תתקלא, ובהנסמן בהערות שם.</p>"],[1200950265,"ח'יז*\n\n<p>ב\"ה, י\"ח אייר תשי\"ד</p><p>ברוקלין.</p><p>הרה\"ג והרה\"ח אי\"א נו\"נ צמ\"ס עוסק בצ\"צ<br>\nכו'<br>\nמוהרש\"י שי'</p>\n<p>שלום וברכה!</p>\n<p>... בשוחחי כאן עם מר שז\"ר שי', נעם לי לשמוע ממנו הערצתו את כת\"ר, וסיפר לי ג\"כ שהי' לו חלק פעיל במה שנמסר לכת\"ר השידור ברדיו את השיעור, וכששאלתיו איך ישפיע זה על מהלך עבודת האנציקלופדי' שהרי זוהי מצה שא\"א לעשותה ע\"י אחרים, הבטיחני שלא בלבל זל\"ז, נוסף על זה שהאנציקלופדיא הוא ענין לחוג מסוים, משא\"כ השידור ברדיו כו' והתבטא בהתלהבות ע\"ד גודל הענין וכו' וכו'.</p>"],[1200950266,"ח'יח\n\n<p>ב\"ה, ו' תמוז, תשי\"ד</p><p>ברוקלין.</p>\n<p>שלום וברכה!</p>\n<p>אמש ביקר אצלי בנו... שי' ודברנו בארוכה בענינים אלו שדברתי עם כת\"ר, שי', ויה\"ר שיהי' לתועלת הרבים, ובפרט שבעוד שבועים תהי' הכנסי' של הסתדרות הרבנים, בה משתתף גם בנו הרב שי', בקשתיו ועוררתיו לנצל השפעתו שם בכל הענינים.</p>\n<p>והנה בנו הרב שי' אינו מאמין כ\"כ בהשפעתו, נוסף על זה- מעריך את המצב בצבעים בלתי שמחים, שבמילא מחליש את המרץ בעשי' בזה, וכמבואר בתניא ריש פרק כ\"ו בפעולת העצבות (משא\"כ מרירות- וכמ\"ש שם פרק ל\"א).</p>\n<p>ובודאי שגם כת\"ר מצדו, יעורר את רוחו וירוממו, והרי ידוע, אשר כאשר מתעסקים בענינים של תורה ומצות, הרי ממלאים בזה את שליחותו של אדם העליון, אשר אז, כביכול, שלוחו של אדם כמותו, וכמבואר בלקו\"ת פ' ויקרא, ובמילא מתוסף ג\"כ בהצלחה.</p>\n<p>ובראותי גם את יחס בנו הרב שי' אליו בטוח הנני שדבריו בזה יעשו על בנו שי' רושם חזק. וכבר ידעו ידוע הנביא בדרא דמשיחא, אשר אפילו החלש יאמר גבור אני, ובפרט אלו שזכו להיות בעלי השפעה על חוג של בני ובנות ישראל.</p>\n<p>ז\"ע נתקבל מכתבו מד' תמוז, בו כותב אודות בריאותו, ואזכירו לרפו\"ק בהיותי על הציון הק' של כ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע.</p>\n<p>ומ\"ש אודות חוו\"ד הרופאים, הנה כבר ידוע מאמר הצמח צדק, אשר התורה נתנה רשות לרופא <b>לרפאות</b> אבל לא ח\"ו מאכן שווער אויף'ן הארצען, וכאשר מתחזקים בבטחון בהשי\"ת, הרופא כל בשר ומפליא לעשות, ממשיכים את זה בפועל בטוב הנראה והנגלה.</p>\n<p>בברכה לאריכות ימים ושנים טובות - לו ולזוגתו - שיחיו - ולברוב נחת מכל יו\"ח שיחיו מתוך בריאותה הנכונה.</p>\n<h4><i><b>ח'יח</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" א ע' 83.</p>\n<p><b>שדברתי עם כת\"ר:</b> ראה לעיל אגרות ח'ה.ח'י.</p>"],[1200950267,"ח'יט\n\n<p>ב\"ה, י\"א תמוז, תשי\"ד</p><p>ברוקלין, נ.י.</p><p>הוו\"ח אי\"א נו\"נ וכו' מו\"ה זעליג שי'</p>\n<p>שלום וברכה!</p>\n<p>י צ ף ך ו ם ד ר ש ח ץ ת</p>\n<p>פ ;63636#&amp; ג א ן נ מ כ ה ז ;8206#&amp;</p>\n<p>ק ס ל ט ע ;63637#&amp; ב ;8207#&amp;.</p>\n<p>מסכו עאךמדמ המכדמדמ ןונןנ;63636#&amp;גא ןמכףקטכ אדרו ןטס;63637#&amp;למ</p>\n<p>מע י\"ג סיון. ט ב;63636#&amp;כ סןוצטאכ;63637#&amp;םמ המגמכום ןנמקוסע;63637#&amp; ג םול. קעמ ;63636#&amp; סעאכט זוםטץמל. ט קעמ ג ךמםצו כודו בףהוע סגאה;63637#&amp;בא. ץמע ;63636#&amp; םו ןטרטעו עמקםמ ךמדהא.</p>\n<p>מ. קעמ ;63636#&amp; ןטרטעו. קעמ ף אס םוע געולוםט הכ ףקןב;63636#&amp; ךנמלו ענוץ עאח ג םוהוכ;8207#&amp; ט ג סףבבמעף. עמ. גמ ןונג;63636#&amp;ץ. - לטםףע םומבץמהטלמ םאיעט ךאזה;63636#&amp;י הום;63637#&amp;.</p>\n<p>ט ;8206#&amp;עמ למזםמ םאיעט - ןנט זוכאםטט. נמלו עמדמ. םאהמ</p>\n<p>חםאע;63637#&amp; םאטחףסע;63637#&amp; םוסךמכ;63637#&amp;ךמ ןנמךםל משניות ט. ץמע ב;63636#&amp; מהטם ןונוך תניא עאך קעמ טה םא עאבמעף ט גמחאנאשא ס;63637#&amp; ס נאבמע;63636#&amp; למדכם ב;63636#&amp; ץאחונום חעמ םאטחףסע;63637#&amp;. ;8206#&amp;עמ</p>\n<p>ןעטםוסוע ףהאקף םו עמכ;63637#&amp;ךמ ג הוכאץ סג חאםם;63636#&amp;ץ ס הףרוגםמי זטחם;63637#&amp;;8207#&amp;. םמ עאךזו ג לאעונטאכ;63637#&amp;םמי זטחםט.</p>\n<p>אהו;8207#&amp;ס;63637#&amp; ןמכףקטע;63637#&amp; ץמעמרטו סגוהוםט . ט זוכא;8207#&amp; אל סקאסע;63637#&amp; ט - ג מסמבוםםמסעט - ג רטהףץו.</p>\n<p>בברכה</p>\n<p><b>מ. שניאורסאהן</b></p><p><i>[תרגום חפשי]</i></p>\n<p>אחרי הפסקה גדולה ביותר, נתקבל מכתבך מי\"ג סיון. שמחתי במיוחד לקרוא בו שבאת בקשרי שידוכין בסוף הקיץ תתקיים חתונתך בשעטומ\"צ, אך לא ציינת הקביעות המדויקת של יום הנשואים.</p>\n<p>באשר לכך שהנך כותב שאין לך זמן לקביעות-עתים מעבר לשלוש פעמים בשבוע וביום הש\"ק - הנה ראשית דבר, חייבים למצוא לפחות עשר-חמש-עשרה דקות כל יום לקביעות עתים לתורה, וכשיש רצון - ניתן למצאם. נוסף לכך, צריכים לדעת בע\"פ כמה פרקי משניות ולפחות פרק אחד תניא, כדי שבעת יציאתך לעבודה וחזרתך (לבית) תוכל לשננם בע\"פ. דבר זה יביא לך הצלחה לא רק בעניינים הקשורים לחייך הרוחניים, אלא גם בחייך הגשמיים.</p>\n<p>אני מקווה לשמוע בשורות טובות ומאחל לך אושר ובפרט איחולי מזל-טוב לבואך בקשרי השידוכין.</p>\n<h4><i><b>ח'יט</b></i></h4>\n<p>צילום האגרת ותרגומה נדפסה ב\"כפר חב\"ד\" גליון 566 (ג' ניסן ה'תשנ\"ג).</p>\n<p><b>מו\"ה זעליג:</b> אלטהויז. אגרות נוספות אליו - לעיל ז'תתקד, ובהנסמן בהערות שם.</p>"],[1200950268,"ח'כ\n\n<p>י\"ב תמוז תשי\"ד:</p>\n<p>התועדות שמחה ורבת פעולות וביחוד בכבוש הנוער.</p>\n<p><b>מנחם שניאורסאהן</b></p><h4><i><b>ח'כ</b></i></h4>\n<p>נדפסה בקונ' \"צדי\"ק למלך\" ד ע' 72.</p>"]]});
